/// One full-haystack boundary observation shared by dependency projections.
///
/// Raw byte-derived properties and Unicode word classification each stay
/// unprepared until a requested dependency needs that family. A broader
/// raw-key retry computes each observation at most once and reuses it.
struct PreparedBoundaryObservation<'h> {
    haystack: &'h [u8],
    position: usize,
    line_terminator: u8,
    raw_enabled: u32,
    global_dependencies: u32,
    unicode_class: u8,
    #[cfg(test)]
    raw_preparations: u8,
    #[cfg(test)]
    unicode_classifications: u8,
}

impl<'h> PreparedBoundaryObservation<'h> {
    #[inline]
    fn new(
        line_terminator: u8,
        haystack: &'h [u8],
        position: usize,
        global_dependencies: u32,
    ) -> Self {
        debug_assert!(position <= haystack.len());
        Self {
            haystack,
            position,
            line_terminator,
            raw_enabled: RAW_BOUNDARY_ENABLED_UNPREPARED,
            global_dependencies,
            unicode_class: UNICODE_BOUNDARY_CLASS_UNPREPARED,
            #[cfg(test)]
            raw_preparations: 0,
            #[cfg(test)]
            unicode_classifications: 0,
        }
    }

    #[inline]
    fn prepare_raw(&mut self) -> u32 {
        if self.raw_enabled == RAW_BOUNDARY_ENABLED_UNPREPARED {
            let before = self
                .position
                .checked_sub(1)
                .and_then(|index| self.haystack.get(index))
                .copied();
            let after = self.haystack.get(self.position).copied();
            let absolute = binary_boundary_class(
                self.position == 0,
                self.position == self.haystack.len(),
            );
            let configured_line = binary_boundary_class(
                self.position == 0 || before == Some(self.line_terminator),
                self.position == self.haystack.len() || after == Some(self.line_terminator),
            );
            let crlf_line = binary_boundary_class(
                self.position == 0
                    || before == Some(b'\n')
                    || before == Some(b'\r') && after != Some(b'\n'),
                self.position == self.haystack.len()
                    || after == Some(b'\r')
                    || after == Some(b'\n') && before != Some(b'\r'),
            );
            let ascii_word = binary_boundary_class(
                before.is_some_and(is_ascii_word),
                after.is_some_and(is_ascii_word),
            );
            let packed = absolute
                | (configured_line << 2)
                | (crlf_line << 4)
                | (ascii_word << 6);
            let unicode_dependencies =
                BoundaryContextClassifier::new(self.global_dependencies).unicode_word();
            let raw_dependencies = self.global_dependencies & !unicode_dependencies;
            self.raw_enabled = RAW_BOUNDARY_ENABLED_BY_PAIR_CLASS[packed] & raw_dependencies;
            #[cfg(test)]
            {
                self.raw_preparations = self
                    .raw_preparations
                    .checked_add(1)
                    .expect("test raw boundary preparation count remains bounded");
            }
        }
        self.raw_enabled
    }

    #[inline]
    fn project(&mut self, dependencies: u32) -> u32 {
        debug_assert_eq!(dependencies & !self.global_dependencies, 0);
        let unicode_dependencies = BoundaryContextClassifier::new(dependencies).unicode_word();
        let raw_dependencies = dependencies & !unicode_dependencies;
        let mut enabled = if raw_dependencies == 0 {
            0
        } else {
            self.prepare_raw() & raw_dependencies
        };
        if unicode_dependencies != 0 {
            let class = if self.unicode_class == UNICODE_BOUNDARY_CLASS_UNPREPARED {
                let class = UnicodeLookMatcher::classify_prevalidated(self.haystack, self.position)
                    .class();
                self.unicode_class =
                    u8::try_from(class).expect("Unicode boundary class fits in one byte");
                #[cfg(test)]
                {
                    self.unicode_classifications = self
                        .unicode_classifications
                        .checked_add(1)
                        .expect("test Unicode classification count remains bounded");
                }
                class
            } else {
                usize::from(self.unicode_class)
            };
            enabled |= UNICODE_WORD_ENABLED_BY_CLASS[class] & unicode_dependencies;
        }
        enabled
    }

    /// Charge the same logical assertion checks as the canonical boundary
    /// evaluator, then project them from this invocation's shared observation.
    fn project_metered(
        &mut self,
        dependencies: u32,
        meter: &mut WorkMeter,
        position: usize,
    ) -> Result<u32, SearchError> {
        debug_assert_eq!(dependencies & !self.global_dependencies, 0);
        let checks = u64::from(dependencies.count_ones());
        if checks <= meter.remaining() {
            meter.charge_admitted(checks);
        } else {
            // Preserve the canonical evaluator's one-unit failure report and
            // exact work consumed before a finite limit rejects this boundary.
            for _ in 0..checks {
                meter.charge(1, position)?;
            }
        }
        Ok(self.project(dependencies))
    }

    #[cfg(test)]
    fn raw_preparations(&self) -> u8 {
        self.raw_preparations
    }

    #[cfg(test)]
    fn unicode_classifications(&self) -> u8 {
        self.unicode_classifications
    }
}

fn enabled_assertion_mask_with_classifier(
    classifier: BoundaryContextClassifier,
    line_terminator: u8,
    haystack: &[u8],
    position: usize,
    meter: &mut WorkMeter,
) -> Result<u32, SearchError> {
    debug_assert!(position <= haystack.len());
    if classifier.assertions() == 0 {
        return Ok(0);
    }
    let checks = u64::from(classifier.assertions().count_ones());
    if checks <= meter.remaining() {
        meter.charge_admitted(checks);
    } else {
        // Preserve the canonical evaluator's one-unit failure report and the
        // exact amount consumed before a finite limit rejects this boundary.
        for _ in 0..checks {
            meter.charge(1, position)?;
        }
    }

    Ok(enabled_assertion_mask_unmetered_with_classifier(
        classifier,
        line_terminator,
        haystack,
        position,
    ))
}

#[inline]
fn enabled_assertion_mask_unmetered_with_classifier(
    classifier: BoundaryContextClassifier,
    line_terminator: u8,
    haystack: &[u8],
    position: usize,
) -> u32 {
    debug_assert!(position <= haystack.len());
    if classifier.assertions() == 0 {
        return 0;
    }
    let mut enabled = 0_u32;
    let absolute = classifier.absolute();
    if absolute != 0 {
        let class = binary_boundary_class(position == 0, position == haystack.len());
        enabled |= ABSOLUTE_ENABLED_BY_CLASS[class] & absolute;
    }

    let configured_line = classifier.configured_line();
    let crlf_line = classifier.crlf_line();
    let ascii_word = classifier.ascii_word();
    let byte_context_used = configured_line | crlf_line | ascii_word != 0;
    let (before, after) = if byte_context_used {
        (
            position
                .checked_sub(1)
                .and_then(|index| haystack.get(index))
                .copied(),
            haystack.get(position).copied(),
        )
    } else {
        (None, None)
    };

    if configured_line != 0 {
        let class = binary_boundary_class(
            position == 0 || before == Some(line_terminator),
            position == haystack.len() || after == Some(line_terminator),
        );
        enabled |= CONFIGURED_LINE_ENABLED_BY_CLASS[class] & configured_line;
    }
    if crlf_line != 0 {
        let class = binary_boundary_class(
            position == 0 || before == Some(b'\n') || before == Some(b'\r') && after != Some(b'\n'),
            position == haystack.len()
                || after == Some(b'\r')
                || after == Some(b'\n') && before != Some(b'\r'),
        );
        enabled |= CRLF_LINE_ENABLED_BY_CLASS[class] & crlf_line;
    }
    if ascii_word != 0 {
        let class = binary_boundary_class(
            before.is_some_and(is_ascii_word),
            after.is_some_and(is_ascii_word),
        );
        enabled |= ASCII_WORD_ENABLED_BY_CLASS[class] & ascii_word;
    }

    let unicode_word = classifier.unicode_word();
    if unicode_word != 0 {
        let class = UnicodeLookMatcher::classify_prevalidated(haystack, position).class();
        enabled |= UNICODE_WORD_ENABLED_BY_CLASS[class] & unicode_word;
    }
    enabled
}

const fn binary_boundary_class(left: bool, right: bool) -> usize {
    let left = if left { 1 } else { 0 };
    let right = if right { 1 } else { 0 };
    left | (right << 1)
}

fn assertion_enabled(kind: EdgeKind, enabled: u32) -> Result<bool, SearchError> {
    if kind == EdgeKind::Epsilon {
        return Ok(true);
    }
    let bit = kind.assertion_bit().ok_or(SearchError::InternalInvariant {
        detail: "contextual closure reached a consuming split edge",
    })?;
    Ok(enabled & bit != 0)
}

pub(crate) fn zero_width_edge_enabled_with_line_terminator(
    line_terminator: u8,
    kind: EdgeKind,
    haystack: &[u8],
    position: usize,
) -> Result<bool, SearchError> {
    match kind {
        EdgeKind::Epsilon => Ok(true),
        EdgeKind::AssertHaystackStart => Ok(position == 0),
        EdgeKind::AssertHaystackEnd => Ok(position == haystack.len()),
        EdgeKind::AssertLineStartLf => Ok(position == 0
            || position
                .checked_sub(1)
                .and_then(|index| haystack.get(index))
                .is_some_and(|&byte| byte == line_terminator)),
        EdgeKind::AssertLineEndLf => {
            Ok(position == haystack.len() || haystack.get(position) == Some(&line_terminator))
        }
        EdgeKind::AssertLineStartCrlf => {
            let before = position
                .checked_sub(1)
                .and_then(|index| haystack.get(index));
            let after = haystack.get(position);
            Ok(position == 0
                || before == Some(&b'\n')
                || (before == Some(&b'\r') && after != Some(&b'\n')))
        }
        EdgeKind::AssertLineEndCrlf => {
            let before = position
                .checked_sub(1)
                .and_then(|index| haystack.get(index));
            let after = haystack.get(position);
            Ok(position == haystack.len()
                || after == Some(&b'\r')
                || (after == Some(&b'\n') && before != Some(&b'\r')))
        }
        EdgeKind::AssertWordAscii
        | EdgeKind::AssertWordAsciiNegate
        | EdgeKind::AssertWordStartAscii
        | EdgeKind::AssertWordEndAscii
        | EdgeKind::AssertWordStartHalfAscii
        | EdgeKind::AssertWordEndHalfAscii => {
            let word_before = position
                .checked_sub(1)
                .and_then(|index| haystack.get(index))
                .is_some_and(|&byte| is_ascii_word(byte));
            let word_after = haystack
                .get(position)
                .is_some_and(|&byte| is_ascii_word(byte));
            Ok(match kind {
                EdgeKind::AssertWordAscii => word_before != word_after,
                EdgeKind::AssertWordAsciiNegate => word_before == word_after,
                EdgeKind::AssertWordStartAscii => !word_before && word_after,
                EdgeKind::AssertWordEndAscii => word_before && !word_after,
                EdgeKind::AssertWordStartHalfAscii => !word_before,
                EdgeKind::AssertWordEndHalfAscii => !word_after,
                _ => {
                    return Err(SearchError::InternalInvariant {
                        detail: "word assertion dispatch changed variants",
                    });
                }
            })
        }
        kind @ (EdgeKind::AssertWordUnicode
        | EdgeKind::AssertWordUnicodeNegate
        | EdgeKind::AssertWordStartUnicode
        | EdgeKind::AssertWordEndUnicode
        | EdgeKind::AssertWordStartHalfUnicode
        | EdgeKind::AssertWordEndHalfUnicode) => {
            unicode_assertion_matches(kind, haystack, position)
        }
        EdgeKind::ByteRange => Err(SearchError::InternalInvariant {
            detail: "split state contained a consuming edge",
        }),
    }
}

fn is_ascii_word(byte: u8) -> bool {
    byte == b'_' || byte.is_ascii_alphanumeric()
}

fn unicode_assertion_matches(
    kind: EdgeKind,
    haystack: &[u8],
    position: usize,
) -> Result<bool, SearchError> {
    let look = match kind {
        EdgeKind::AssertWordUnicode => regex_syntax::hir::Look::WordUnicode,
        EdgeKind::AssertWordUnicodeNegate => regex_syntax::hir::Look::WordUnicodeNegate,
        EdgeKind::AssertWordStartUnicode => regex_syntax::hir::Look::WordStartUnicode,
        EdgeKind::AssertWordEndUnicode => regex_syntax::hir::Look::WordEndUnicode,
        EdgeKind::AssertWordStartHalfUnicode => regex_syntax::hir::Look::WordStartHalfUnicode,
        EdgeKind::AssertWordEndHalfUnicode => regex_syntax::hir::Look::WordEndHalfUnicode,
        _ => {
            return Err(SearchError::InternalInvariant {
                detail: "non-Unicode edge in Unicode assertion dispatch",
            });
        }
    };
    Ok(UnicodeLookMatcher::matches_prevalidated(
        look, haystack, position,
    ))
}

/// Reinvest overprovisioned contextual transition slots in forward identity
/// metadata without exceeding this automaton's legacy retained-byte or setup
/// work envelope. Narrow layouts and shapes whose complete identity domain is
/// at most 256 states retain their former dimensions exactly.
fn contextual_lazy_capacities(
    automaton: &Automaton,
    tier: LazyCacheTier,
) -> Result<(usize, usize, usize), SearchError> {
    let states = automaton.stats().states();
    if states == 0 || states > LAZY_MAX_ITEMS {
        return Ok((0, 0, 0));
    }
    let consuming = automaton.stats().consuming_states();
    let legacy_states = forward_lazy_state_capacity_up_to(consuming, tier.state_limit());
    let legacy_items = ordered_partial_permutation_item_capacity(
        consuming,
        2,
        legacy_states,
        "contextual lazy DFA item capacity",
    )?;
    let legacy_slots = contextual_transition_slots(legacy_states)?;
    if tier == LazyCacheTier::Narrow || legacy_states < LAZY_MAX_STATES {
        return Ok((legacy_states, legacy_items, legacy_slots));
    }

    let class_count = automaton.byte_classes().count();
    let global_dependencies = automaton.boundary_context_classifier().assertions();
    let stride = u32::try_from(class_count).map_err(|_| SearchError::InternalInvariant {
        detail: "contextual lazy byte-class count does not fit the row stride",
    })?;
    let byte_budget = lazy_scratch_bytes(
        states,
        legacy_states,
        legacy_items,
        stride,
        legacy_slots,
    )?;
    let initialized_slot_budget = lazy_initialized_slots(
        states,
        legacy_states,
        legacy_items,
        stride,
        legacy_slots,
    )?;
    let maximum_states =
        forward_lazy_state_capacity_up_to(consuming, DIRECT_LAZY_MAX_STATES);
    let byte_limited = maximize_direct_state_capacity(
        legacy_states,
        maximum_states,
        byte_budget,
        |candidate| {
            let items = ordered_partial_permutation_item_capacity(
                consuming,
                2,
                candidate,
                "contextual lazy DFA item capacity",
            )?;
            let slots = compact_contextual_transition_slots(
                candidate,
                class_count,
                global_dependencies,
            )?;
            lazy_scratch_bytes(states, candidate, items, stride, slots)
        },
    )?;
    let expanded_states = maximize_direct_state_capacity(
        legacy_states,
        byte_limited,
        initialized_slot_budget,
        |candidate| {
            let items = ordered_partial_permutation_item_capacity(
                consuming,
                2,
                candidate,
                "contextual lazy DFA item capacity",
            )?;
            let slots = compact_contextual_transition_slots(
                candidate,
                class_count,
                global_dependencies,
            )?;
            lazy_initialized_slots(states, candidate, items, stride, slots)
        },
    )?;
    if expanded_states == legacy_states {
        return Ok((legacy_states, legacy_items, legacy_slots));
    }
    let expanded_items = ordered_partial_permutation_item_capacity(
        consuming,
        2,
        expanded_states,
        "contextual lazy DFA item capacity",
    )?;
    let expanded_slots = compact_contextual_transition_slots(
        expanded_states,
        class_count,
        global_dependencies,
    )?;
    Ok((expanded_states, expanded_items, expanded_slots))
}

/// Reverse counterpart of [`contextual_lazy_capacities`]. The fixed reverse
/// CSR is included in both sides of each exact resource comparison, and only
/// contextual wide layouts can select the expanded result.
fn contextual_reverse_capacities(
    automaton: &Automaton,
    tier: LazyCacheTier,
) -> Result<(usize, usize, usize), SearchError> {
    let consuming = automaton.stats().consuming_edges();
    if consuming == 0 || consuming > LAZY_MAX_ITEMS {
        return Ok((0, 0, 0));
    }
    let legacy_states = reverse_lazy_state_capacity_up_to(consuming, true, tier.state_limit());
    let legacy_items = ordered_partial_permutation_item_capacity(
        consuming,
        1,
        legacy_states,
        "contextual reverse lazy DFA item capacity",
    )?;
    let legacy_slots = contextual_transition_slots(legacy_states)?;
    if tier == LazyCacheTier::Narrow || legacy_states < LAZY_MAX_STATES {
        return Ok((legacy_states, legacy_items, legacy_slots));
    }

    let class_count = automaton.byte_classes().count();
    let global_dependencies = automaton.boundary_context_classifier().assertions();
    let stride = u32::try_from(class_count).map_err(|_| SearchError::InternalInvariant {
        detail: "contextual reverse byte-class count does not fit the row stride",
    })?;
    let states = automaton.stats().states();
    let edges = automaton.stats().edges();
    let byte_budget = reverse_scratch_bytes(
        states,
        edges,
        legacy_states,
        legacy_items,
        stride,
        legacy_slots,
    )?;
    let initialized_slot_budget = reverse_initialized_slots(
        states,
        edges,
        legacy_states,
        legacy_items,
        stride,
        legacy_slots,
    )?;
    let maximum_states = reverse_lazy_state_capacity_up_to(
        consuming,
        true,
        DIRECT_LAZY_MAX_STATES,
    );
    let byte_limited = maximize_direct_state_capacity(
        legacy_states,
        maximum_states,
        byte_budget,
        |candidate| {
            let items = ordered_partial_permutation_item_capacity(
                consuming,
                1,
                candidate,
                "contextual reverse lazy DFA item capacity",
            )?;
            let slots = compact_contextual_transition_slots(
                candidate,
                class_count,
                global_dependencies,
            )?;
            reverse_scratch_bytes(states, edges, candidate, items, stride, slots)
        },
    )?;
    let expanded_states = maximize_direct_state_capacity(
        legacy_states,
        byte_limited,
        initialized_slot_budget,
        |candidate| {
            let items = ordered_partial_permutation_item_capacity(
                consuming,
                1,
                candidate,
                "contextual reverse lazy DFA item capacity",
            )?;
            let slots = compact_contextual_transition_slots(
                candidate,
                class_count,
                global_dependencies,
            )?;
            reverse_initialized_slots(states, edges, candidate, items, stride, slots)
        },
    )?;
    if expanded_states == legacy_states {
        return Ok((legacy_states, legacy_items, legacy_slots));
    }
    let expanded_items = ordered_partial_permutation_item_capacity(
        consuming,
        1,
        expanded_states,
        "contextual reverse lazy DFA item capacity",
    )?;
    let expanded_slots = compact_contextual_transition_slots(
        expanded_states,
        class_count,
        global_dependencies,
    )?;
    Ok((expanded_states, expanded_items, expanded_slots))
}

fn lazy_capacities(
    automaton: &Automaton,
    direct_class_count: usize,
    tier: LazyCacheTier,
) -> Result<(usize, usize), SearchError> {
    let states = automaton.stats().states();
    if states == 0 || states > LAZY_MAX_ITEMS {
        return Ok((0, 0));
    }
    let consuming = automaton.stats().consuming_states();
    let state_capacity = forward_lazy_state_capacity_up_to(consuming, tier.state_limit());
    let legacy_item_capacity = ordered_partial_permutation_item_capacity(
        consuming,
        2,
        state_capacity,
        "lazy DFA item capacity",
    )?;
    if automaton.stats().assertion_edges() != 0 {
        return Ok((state_capacity, legacy_item_capacity));
    }
    if tier == LazyCacheTier::Narrow {
        return Ok((state_capacity, legacy_item_capacity));
    }
    if !(1..=BYTE_ALPHABET).contains(&direct_class_count) {
        return Err(SearchError::InternalInvariant {
            detail: "direct lazy byte-class count is outside the alphabet",
        });
    }

    // Reinvest only resources that the former 256-cell identity rows would
    // have retained and initialized. This keeps both memory and construction
    // work source-independent and no larger than the legacy direct arena.
    let legacy_stride =
        u32::try_from(BYTE_ALPHABET).map_err(|_| SearchError::InternalInvariant {
            detail: "byte alphabet does not fit the direct-row stride",
        })?;
    let byte_budget = lazy_scratch_bytes(
        states,
        state_capacity,
        legacy_item_capacity,
        legacy_stride,
        0,
    )?;
    let initialized_slot_budget = lazy_initialized_slots(
        states,
        state_capacity,
        legacy_item_capacity,
        legacy_stride,
        0,
    )?;
    let direct_stride =
        u32::try_from(direct_class_count).map_err(|_| SearchError::InternalInvariant {
            detail: "direct lazy byte-class count does not fit the row stride",
        })?;
    let maximum_state_capacity =
        forward_lazy_state_capacity_up_to(consuming, DIRECT_LAZY_MAX_STATES);
    let byte_limited_capacity = maximize_direct_state_capacity(
        state_capacity,
        maximum_state_capacity,
        byte_budget,
        |candidate| {
            let items = ordered_partial_permutation_item_capacity(
                consuming,
                2,
                candidate,
                "lazy DFA item capacity",
            )?;
            lazy_scratch_bytes(states, candidate, items, direct_stride, 0)
        },
    )?;
    let state_capacity = maximize_direct_state_capacity(
        state_capacity,
        byte_limited_capacity,
        initialized_slot_budget,
        |candidate| {
            let items = ordered_partial_permutation_item_capacity(
                consuming,
                2,
                candidate,
                "lazy DFA item capacity",
            )?;
            lazy_initialized_slots(states, candidate, items, direct_stride, 0)
        },
    )?;
    let item_capacity = ordered_partial_permutation_item_capacity(
        consuming,
        2,
        state_capacity,
        "lazy DFA item capacity",
    )?;
    Ok((state_capacity, item_capacity))
}

const fn lazy_index_admitted(state_capacity: usize) -> bool {
    state_capacity >= LAZY_HASH_INDEX_MIN_STATES
        && state_capacity > EXACT_FORWARD_LAZY_STATE_CAPACITY
}

fn lazy_index_slots(state_capacity: usize) -> Result<usize, SearchError> {
    if !lazy_index_admitted(state_capacity) {
        return Ok(0);
    }
    state_capacity
        .checked_mul(2)
        .and_then(usize::checked_next_power_of_two)
        .ok_or(SearchError::ArithmeticOverflow {
            computation: "lazy DFA index slots",
        })
}

/// Live forward or reverse identity-index domain for one retained-state
/// boundary.
///
/// Capacities at or below the legacy ceiling are unchanged. A wider direct
/// arena hashes into exactly the same 512-slot prefix until the first identity
/// beyond that ceiling has been proved distinct and transactionally
/// published. Thereafter `state_len` itself proves that the complete wide
/// table was rebuilt.
const fn lazy_active_index_slots(index_capacity: usize, state_len: usize) -> usize {
    if state_len <= LAZY_MAX_STATES {
        if index_capacity < LAZY_LEGACY_IDENTITY_INDEX_SLOTS {
            index_capacity
        } else {
            LAZY_LEGACY_IDENTITY_INDEX_SLOTS
        }
    } else {
        index_capacity
    }
}

fn lazy_index_promotion_max_work(index_capacity: usize) -> Result<usize, SearchError> {
    if index_capacity <= LAZY_LEGACY_IDENTITY_INDEX_SLOTS
        || index_capacity > LAZY_IDENTITY_INDEX_MAX_SLOTS
    {
        return Err(SearchError::InternalInvariant {
            detail: "lazy DFA identity-index promotion has an invalid wide arena",
        });
    }
    // In the adversarial case every hash starts at one slot. Entry `i` then
    // examines `i + 1` slots. Add one clear per already-owned wide slot and
    // one publication per promoted identity.
    LAZY_IDENTITY_INDEX_PROMOTION_STATES
        .checked_mul(LAZY_IDENTITY_INDEX_PROMOTION_STATES + 1)
        .and_then(|work| work.checked_div(2))
        .and_then(|work| work.checked_add(LAZY_IDENTITY_INDEX_OCCUPANCY_WORDS))
        .and_then(|work| work.checked_add(index_capacity))
        .and_then(|work| work.checked_add(LAZY_IDENTITY_INDEX_PROMOTION_STATES))
        .ok_or(SearchError::ArithmeticOverflow {
            computation: "lazy DFA identity-index promotion work",
        })
}

/// Legacy forward identity placement, retained exactly through the 256-state
/// physical domain and scaled only after promotion. Complete linear overflow
/// remains authoritative, so this hash-derived slot is never an identity.
fn lazy_forward_index_start(hash: u64, slots: usize) -> Result<usize, SearchError> {
    let mask = slots
        .checked_sub(1)
        .filter(|_| slots.is_power_of_two())
        .ok_or(SearchError::InternalInvariant {
            detail: "lazy forward identity index does not have power-of-two capacity",
        })?;
    let mask = u64::try_from(mask).map_err(|_| SearchError::ArithmeticOverflow {
        computation: "lazy forward identity-index mask conversion",
    })?;
    usize::try_from(hash & mask).map_err(|_| SearchError::InternalInvariant {
        detail: "lazy forward identity-index slot does not fit usize",
    })
}

fn lazy_index_start(hash: u64, slots: usize) -> Result<usize, SearchError> {
    if slots % LAZY_IDENTITY_INDEX_WAYS != 0 {
        return Err(SearchError::InternalInvariant {
            detail: "lazy DFA index does not have whole buckets",
        });
    }
    let buckets = slots / LAZY_IDENTITY_INDEX_WAYS;
    let mask = buckets
        .checked_sub(1)
        .filter(|_| buckets.is_power_of_two())
        .ok_or(SearchError::InternalInvariant {
            detail: "lazy DFA index does not have power-of-two buckets",
        })?;
    let mask = u64::try_from(mask).map_err(|_| SearchError::ArithmeticOverflow {
        computation: "lazy DFA index mask conversion",
    })?;
    usize::try_from(hash & mask)
        .map_err(|_| SearchError::InternalInvariant {
            detail: "lazy DFA index bucket does not fit usize",
        })?
        .checked_mul(LAZY_IDENTITY_INDEX_WAYS)
        .ok_or(SearchError::ArithmeticOverflow {
            computation: "lazy DFA index bucket start",
        })
}

fn lazy_index_advance(slot: usize, slots: usize) -> Result<usize, SearchError> {
    let next = slot.checked_add(1).ok_or(SearchError::ArithmeticOverflow {
        computation: "lazy DFA index overflow probe",
    })?;
    match next.cmp(&slots) {
        core::cmp::Ordering::Less => Ok(next),
        core::cmp::Ordering::Equal => Ok(0),
        core::cmp::Ordering::Greater => Err(SearchError::InternalInvariant {
            detail: "lazy DFA index overflow probe starts outside the table",
        }),
    }
}

fn reverse_capacities(
    automaton: &Automaton,
    tier: LazyCacheTier,
) -> Result<(usize, usize), SearchError> {
    let consuming = automaton.stats().consuming_edges();
    if consuming == 0 || consuming > LAZY_MAX_ITEMS {
        return Ok((0, 0));
    }
    let state_capacity = reverse_lazy_state_capacity_up_to(
        consuming,
        automaton.stats().assertion_edges() != 0,
        tier.state_limit(),
    );
    let item_capacity = ordered_partial_permutation_item_capacity(
        consuming,
        1,
        state_capacity,
        "reverse lazy DFA item capacity",
    )?;
    Ok((state_capacity, item_capacity))
}

/// Find the greatest monotone capacity whose complete arena fits one legacy
/// resource budget. Callers measure exact retained bytes and initialized
/// slots, including metadata, the power-of-two identity index, aggregate item
/// storage, and exact-class rows.
#[allow(
    clippy::arithmetic_side_effects,
    reason = "the authenticated ordered bounds make midpoint arithmetic exact"
)]
fn maximize_direct_state_capacity(
    minimum: usize,
    maximum: usize,
    resource_budget: usize,
    mut measure_for: impl FnMut(usize) -> Result<usize, SearchError>,
) -> Result<usize, SearchError> {
    if minimum > maximum || measure_for(minimum)? > resource_budget {
        return Err(SearchError::InternalInvariant {
            detail: "compact direct arena does not fit its legacy resource budget",
        });
    }
    let mut accepted = minimum;
    let mut upper = maximum;
    while accepted < upper {
        let candidate = accepted + (upper - accepted).div_ceil(2);
        let fits = match measure_for(candidate) {
            Ok(measure) => measure <= resource_budget,
            // The measure is monotone. Overflow proves this candidate and
            // every larger one exceed a representable budget; it cannot
            // reject the already-representable legacy layout.
            Err(SearchError::ArithmeticOverflow { .. }) => false,
            Err(error) => return Err(error),
        };
        if fits {
            accepted = candidate;
        } else {
            upper = candidate - 1;
        }
    }
    Ok(accepted)
}

/// Count distinct ordered nonempty subsets, capped at the retained row limit.
///
/// A closure generation admits each item at most once, but forward priority
/// makes different orders distinct cache states. `modes` accounts for state
/// identity outside the item sequence, while `empty_modes` admits only the
/// semantically reachable empty identities.
fn capped_ordered_partial_permutations_up_to(
    items: usize,
    modes: usize,
    empty_modes: usize,
    state_limit: usize,
) -> usize {
    let mut total = empty_modes.min(state_limit);
    let mut permutations = 1usize;
    let mut length = 1usize;
    while length <= items && total < state_limit {
        let prior = length.saturating_sub(1);
        let remaining = items.saturating_sub(prior);
        permutations = permutations.saturating_mul(remaining).min(state_limit);
        total = total
            .saturating_add(permutations.saturating_mul(modes))
            .min(state_limit);
        length = length.saturating_add(1);
    }
    total
}

#[cfg(test)]
fn forward_lazy_state_capacity(consuming_states: usize) -> usize {
    forward_lazy_state_capacity_up_to(consuming_states, LAZY_MAX_STATES)
}

fn forward_lazy_state_capacity_up_to(consuming_states: usize, state_limit: usize) -> usize {
    // Nonempty ordered subsets exist in both pending modes. Exactly one empty
    // identity is retainable: the pending nullable initial state in a direct
    // graph, or the nonpending restart state in a contextual graph.
    capped_ordered_partial_permutations_up_to(consuming_states, 2, 1, state_limit)
}

#[cfg(test)]
fn reverse_lazy_state_capacity(consuming_edges: usize, contextual: bool) -> usize {
    reverse_lazy_state_capacity_up_to(consuming_edges, contextual, LAZY_MAX_STATES)
}

fn reverse_lazy_state_capacity_up_to(
    consuming_edges: usize,
    contextual: bool,
    state_limit: usize,
) -> usize {
    if consuming_edges == 0 {
        return 0;
    }
    // Reverse state identity is only its consuming-edge sequence. Contextual
    // initialization can additionally retain one empty sequence when the
    // current assertion mask disconnects every consuming predecessor.
    capped_ordered_partial_permutations_up_to(
        consuming_edges,
        1,
        usize::from(contextual),
        state_limit,
    )
}

/// Maximum aggregate item length of any retained set of distinct identities.
///
/// Enumerate each length exactly, retaining the longest identities first.
/// Products are capped at the bounded state domain: once a layer supplies all
/// remaining identities, larger factorial values cannot affect the arena.
fn ordered_partial_permutation_item_capacity(
    items: usize,
    modes: usize,
    state_capacity: usize,
    structure: &'static str,
) -> Result<usize, SearchError> {
    let mut remaining_states = state_capacity;
    let mut item_capacity = 0usize;
    let mut length = items;
    while length != 0 && remaining_states != 0 {
        let mut permutations = 1usize;
        for ordinal in 0..length {
            let factor = items
                .checked_sub(ordinal)
                .ok_or(SearchError::ArithmeticOverflow {
                    computation: structure,
                })?;
            permutations = permutations.saturating_mul(factor).min(state_capacity);
        }
        let identities = permutations.saturating_mul(modes).min(state_capacity);
        let selected = identities.min(remaining_states);
        item_capacity = selected
            .checked_mul(length)
            .and_then(|items| item_capacity.checked_add(items))
            .ok_or(SearchError::ArithmeticOverflow {
                computation: structure,
            })?;
        remaining_states =
            remaining_states
                .checked_sub(selected)
                .ok_or(SearchError::ArithmeticOverflow {
                    computation: structure,
                })?;
        length = length
            .checked_sub(1)
            .ok_or(SearchError::ArithmeticOverflow {
                computation: structure,
            })?;
    }
    Ok(item_capacity.min(LAZY_MAX_ITEMS))
}

fn lazy_initialized_slots(
    states: usize,
    state_capacity: usize,
    item_capacity: usize,
    direct_row_stride: u32,
    context_slots: usize,
) -> Result<usize, SearchError> {
    if state_capacity == 0 {
        return Ok(0);
    }
    let rows = if context_slots == 0 {
        state_capacity
            .checked_mul(usize::try_from(direct_row_stride).map_err(|_| {
                SearchError::InternalInvariant {
                    detail: "lazy DFA row stride does not fit usize",
                }
            })?)
            .ok_or(SearchError::ArithmeticOverflow {
                computation: "lazy DFA initialized row slots",
            })?
    } else {
        0
    };
    let index_slots = lazy_index_slots(state_capacity)?;
    let context_hot_slots = if context_slots == 0 { 0 } else { state_capacity };
    let context_dense_slots = if context_slots == 0 {
        0
    } else {
        contextual_dense_cells(
            usize::try_from(direct_row_stride).map_err(|_| {
                SearchError::InternalInvariant {
                    detail: "contextual dense class count does not fit usize",
                }
            })?,
            state_capacity,
        )?
    };
    states
        .checked_mul(2)
        .and_then(|slots| slots.checked_add(rows))
        .and_then(|slots| slots.checked_add(context_slots))
        .and_then(|slots| slots.checked_add(context_hot_slots))
        .and_then(|slots| slots.checked_add(context_dense_slots))
        .and_then(|slots| slots.checked_add(state_capacity))
        .and_then(|slots| slots.checked_add(state_capacity))
        .and_then(|slots| slots.checked_add(state_capacity))
        .and_then(|slots| slots.checked_add(state_capacity))
        .and_then(|slots| slots.checked_add(index_slots))
        .and_then(|slots| slots.checked_add(item_capacity))
        .ok_or(SearchError::ArithmeticOverflow {
            computation: "lazy DFA initialized slots",
        })
}

fn lazy_scratch_bytes(
    states: usize,
    state_capacity: usize,
    item_capacity: usize,
    direct_row_stride: u32,
    context_slots: usize,
) -> Result<usize, SearchError> {
    if state_capacity == 0 {
        return Ok(0);
    }
    let rows = if context_slots == 0 {
        state_capacity
            .checked_mul(usize::try_from(direct_row_stride).map_err(|_| {
                SearchError::InternalInvariant {
                    detail: "lazy DFA row stride does not fit usize",
                }
            })?)
            .ok_or(SearchError::ArithmeticOverflow {
                computation: "lazy DFA row cells",
            })?
    } else {
        0
    };
    let index_slots = lazy_index_slots(state_capacity)?;
    let state_u32s = states
        .checked_mul(2)
        .and_then(|slots| slots.checked_add(rows))
        .and_then(|slots| slots.checked_add(state_capacity))
        .and_then(|slots| slots.checked_add(index_slots))
        .and_then(|slots| slots.checked_add(item_capacity))
        .ok_or(SearchError::ArithmeticOverflow {
            computation: "lazy DFA u32 slots",
        })?;
    let u32_bytes =
        state_u32s
            .checked_mul(size_of::<u32>())
            .ok_or(SearchError::ArithmeticOverflow {
                computation: "lazy DFA u32 bytes",
            })?;
    let offsets =
        state_capacity
            .checked_mul(size_of::<usize>())
            .ok_or(SearchError::ArithmeticOverflow {
                computation: "lazy DFA offset bytes",
            })?;
    let modes = state_capacity;
    let hashes =
        state_capacity
            .checked_mul(size_of::<u64>())
            .ok_or(SearchError::ArithmeticOverflow {
                computation: "lazy DFA hash bytes",
            })?;
    let context_bytes = context_slots
        .checked_mul(size_of::<ContextTransitionSlot>())
        .ok_or(SearchError::ArithmeticOverflow {
            computation: "lazy DFA contextual transition bytes",
        })?;
    let context_hot_bytes = if context_slots == 0 {
        0
    } else {
        state_capacity
            .checked_mul(size_of::<ContextHotTransition>())
            .ok_or(SearchError::ArithmeticOverflow {
                computation: "lazy DFA contextual hot-transition bytes",
            })?
    };
    let context_dense_bytes = if context_slots == 0 {
        0
    } else {
        contextual_dense_cells(
            usize::try_from(direct_row_stride).map_err(|_| {
                SearchError::InternalInvariant {
                    detail: "contextual dense class count does not fit usize",
                }
            })?,
            state_capacity,
        )?
        .checked_mul(size_of::<u32>())
        .ok_or(SearchError::ArithmeticOverflow {
            computation: "lazy DFA contextual dense-transition bytes",
        })?
    };
    u32_bytes
        .checked_add(offsets)
        .and_then(|bytes| bytes.checked_add(modes))
        .and_then(|bytes| bytes.checked_add(hashes))
        .and_then(|bytes| bytes.checked_add(context_bytes))
        .and_then(|bytes| bytes.checked_add(context_hot_bytes))
        .and_then(|bytes| bytes.checked_add(context_dense_bytes))
        .ok_or(SearchError::ArithmeticOverflow {
            computation: "lazy DFA scratch bytes",
        })
}

fn reverse_initialized_slots(
    states: usize,
    edges: usize,
    state_capacity: usize,
    item_capacity: usize,
    direct_row_stride: u32,
    context_slots: usize,
) -> Result<usize, SearchError> {
    if state_capacity == 0 {
        return Ok(0);
    }
    let rows = if context_slots == 0 {
        state_capacity
            .checked_mul(usize::try_from(direct_row_stride).map_err(|_| {
                SearchError::InternalInvariant {
                    detail: "reverse lazy DFA row stride does not fit usize",
                }
            })?)
            .ok_or(SearchError::ArithmeticOverflow {
                computation: "reverse lazy DFA initialized row slots",
            })?
    } else {
        0
    };
    let index_slots = lazy_index_slots(state_capacity)?;
    let context_hot_slots = if context_slots == 0 { 0 } else { state_capacity };
    states
        .checked_add(1)
        .and_then(|slots| {
            edges
                .checked_mul(3)
                .and_then(|edges| slots.checked_add(edges))
        })
        .and_then(|slots| {
            edges
                .checked_mul(2)
                .and_then(|edges| slots.checked_add(edges))
        })
        .and_then(|slots| slots.checked_add(if context_slots == 0 { 0 } else { edges }))
        .and_then(|slots| slots.checked_add(rows))
        .and_then(|slots| slots.checked_add(context_slots))
        .and_then(|slots| slots.checked_add(context_hot_slots))
        .and_then(|slots| {
            state_capacity
                .checked_mul(3)
                .and_then(|meta| slots.checked_add(meta))
        })
        .and_then(|slots| slots.checked_add(index_slots))
        .and_then(|slots| slots.checked_add(item_capacity))
        .ok_or(SearchError::ArithmeticOverflow {
            computation: "reverse lazy DFA initialized slots",
        })
}

fn reverse_scratch_bytes(
    states: usize,
    edges: usize,
    state_capacity: usize,
    item_capacity: usize,
    direct_row_stride: u32,
    context_slots: usize,
) -> Result<usize, SearchError> {
    if state_capacity == 0 {
        return Ok(0);
    }
    let rows = if context_slots == 0 {
        state_capacity
            .checked_mul(usize::try_from(direct_row_stride).map_err(|_| {
                SearchError::InternalInvariant {
                    detail: "reverse lazy DFA row stride does not fit usize",
                }
            })?)
            .ok_or(SearchError::ArithmeticOverflow {
                computation: "reverse lazy DFA row cells",
            })?
    } else {
        0
    };
    let index_slots = lazy_index_slots(state_capacity)?;
    let u32_slots = states
        .checked_add(1)
        .and_then(|slots| slots.checked_add(edges))
        .and_then(|slots| {
            edges
                .checked_mul(2)
                .and_then(|edges| slots.checked_add(edges))
        })
        .and_then(|slots| slots.checked_add(rows))
        .and_then(|slots| slots.checked_add(state_capacity))
        .and_then(|slots| slots.checked_add(index_slots))
        .and_then(|slots| slots.checked_add(item_capacity))
        .ok_or(SearchError::ArithmeticOverflow {
            computation: "reverse lazy DFA u32 slots",
        })?;
    let u32_bytes =
        u32_slots
            .checked_mul(size_of::<u32>())
            .ok_or(SearchError::ArithmeticOverflow {
                computation: "reverse lazy DFA u32 bytes",
            })?;
    let range_bytes = edges
        .checked_mul(2)
        .ok_or(SearchError::ArithmeticOverflow {
            computation: "reverse CSR range bytes",
        })?;
    let kind_bytes = if context_slots == 0 {
        0
    } else {
        edges
            .checked_mul(size_of::<EdgeKind>())
            .ok_or(SearchError::ArithmeticOverflow {
                computation: "reverse CSR kind bytes",
            })?
    };
    let offsets =
        state_capacity
            .checked_mul(size_of::<usize>())
            .ok_or(SearchError::ArithmeticOverflow {
                computation: "reverse lazy DFA offset bytes",
            })?;
    let hashes =
        state_capacity
            .checked_mul(size_of::<u64>())
            .ok_or(SearchError::ArithmeticOverflow {
                computation: "reverse lazy DFA hash bytes",
            })?;
    let context_bytes = context_slots
        .checked_mul(size_of::<ContextTransitionSlot>())
        .ok_or(SearchError::ArithmeticOverflow {
            computation: "reverse contextual transition bytes",
        })?;
    let context_hot_bytes = if context_slots == 0 {
        0
    } else {
        state_capacity
            .checked_mul(size_of::<ContextHotTransition>())
            .ok_or(SearchError::ArithmeticOverflow {
                computation: "reverse contextual hot-transition bytes",
            })?
    };
    u32_bytes
        .checked_add(range_bytes)
        .and_then(|bytes| bytes.checked_add(kind_bytes))
        .and_then(|bytes| bytes.checked_add(offsets))
        .and_then(|bytes| bytes.checked_add(hashes))
        .and_then(|bytes| bytes.checked_add(context_bytes))
        .and_then(|bytes| bytes.checked_add(context_hot_bytes))
        .ok_or(SearchError::ArithmeticOverflow {
            computation: "reverse lazy DFA scratch bytes",
        })
}

fn lazy_hash(items: &[u32], pending: bool) -> u64 {
    let mut hash = 0xcbf2_9ce4_8422_2325_u64 ^ u64::from(pending);
    for &item in items {
        hash ^= u64::from(item);
        hash = hash.wrapping_mul(0x0000_0100_0000_01b3);
    }
    hash
}

fn scratch_bytes(states: usize, edges: usize, stack: usize) -> Result<usize, SearchError> {
    let seen = states
        .checked_mul(size_of::<u64>())
        .ok_or(SearchError::ArithmeticOverflow {
            computation: "seen scratch bytes",
        })?;
    let current =
        states
            .checked_mul(size_of::<Thread>())
            .ok_or(SearchError::ArithmeticOverflow {
                computation: "current-thread scratch bytes",
            })?;
    let roots = edges
        .checked_mul(size_of::<Thread>())
        .ok_or(SearchError::ArithmeticOverflow {
            computation: "root scratch bytes",
        })?;
    let closure =
        stack
            .checked_mul(size_of::<Thread>())
            .ok_or(SearchError::ArithmeticOverflow {
                computation: "closure-stack scratch bytes",
            })?;
    seen.checked_add(current)
        .and_then(|value| value.checked_add(roots))
        .and_then(|value| value.checked_add(closure))
        .ok_or(SearchError::ArithmeticOverflow {
            computation: "total scratch bytes",
        })
}

fn allocate_slots<T: Copy>(
    length: usize,
    value: T,
    total_bytes: usize,
) -> Result<Vec<T>, SearchError> {
    let mut vector = Vec::new();
    vector
        .try_reserve_exact(length)
        .map_err(|_| SearchError::ScratchAllocationFailed {
            requested: total_bytes,
        })?;
    vector.resize(length, value);
    Ok(vector)
}

fn retained_bytes(
    seen_at: &Vec<u64>,
    current: &Vec<Thread>,
    roots: &Vec<Thread>,
    stack: &Vec<Thread>,
    lazy: &LazyWorkspace,
    reverse: &ReverseWorkspace,
) -> Result<usize, SearchError> {
    let seen = seen_at.capacity().checked_mul(size_of::<u64>()).ok_or(
        SearchError::ArithmeticOverflow {
            computation: "retained seen scratch bytes",
        },
    )?;
    let current = current.capacity().checked_mul(size_of::<Thread>()).ok_or(
        SearchError::ArithmeticOverflow {
            computation: "retained current scratch bytes",
        },
    )?;
    let roots = roots.capacity().checked_mul(size_of::<Thread>()).ok_or(
        SearchError::ArithmeticOverflow {
            computation: "retained root scratch bytes",
        },
    )?;
    let stack = stack.capacity().checked_mul(size_of::<Thread>()).ok_or(
        SearchError::ArithmeticOverflow {
            computation: "retained closure scratch bytes",
        },
    )?;
    let lazy = lazy.retained_bytes()?;
    let reverse = reverse.retained_bytes()?;
    seen.checked_add(current)
        .and_then(|value| value.checked_add(roots))
        .and_then(|value| value.checked_add(stack))
        .and_then(|value| value.checked_add(lazy))
        .and_then(|value| value.checked_add(reverse))
        .ok_or(SearchError::ArithmeticOverflow {
            computation: "total retained scratch bytes",
        })
}

fn capacity_bytes<T>(vector: &Vec<T>, computation: &'static str) -> Result<usize, SearchError> {
    vector
        .capacity()
        .checked_mul(size_of::<T>())
        .ok_or(SearchError::ArithmeticOverflow { computation })
}

