    fn direct_two_state_inferred_loop() -> Automaton {
        // State zero has an `a` self-loop and enters state one on `x`. State
        // one's `b..=c` edge is one graph equivalence class, while the `q b`
        // branch splits `b` and `c` into distinct global byte classes. A plan
        // learned from the physical `c` cell may therefore scan `b` without
        // publishing that sibling cell.
        Automaton::from_raw(
            RawPlan {
                start: 0,
                roles: vec![
                    StateRole::Consume,
                    StateRole::Consume,
                    StateRole::Consume,
                    StateRole::Accept,
                ],
                edge_offsets: vec![0, 3, 4, 5, 5],
                edge_targets: vec![0, 1, 2, 1, 3],
                edge_kinds: vec![EdgeKind::ByteRange; 5],
                byte_starts: vec![b'a', b'x', b'q', b'b', b'b'],
                byte_ends: vec![b'a', b'x', b'q', b'c', b'b'],
            },
            CompileLimits::default(),
        )
        .unwrap()
    }

    fn direct_split_loop_then_terminal() -> Automaton {
        // State zero treats `a` and `b` identically, while the reachable
        // `q b` branch forces them into distinct global byte classes. A loop
        // proof learned from `a` may therefore scan `b` without publishing
        // the physically distinct direct-row cell.
        Automaton::from_raw(
            RawPlan {
                start: 0,
                roles: vec![
                    StateRole::Consume,
                    StateRole::Accept,
                    StateRole::Consume,
                    StateRole::Accept,
                ],
                edge_offsets: vec![0, 3, 3, 4, 4],
                edge_targets: vec![0, 1, 2, 3],
                edge_kinds: vec![EdgeKind::ByteRange; 4],
                byte_starts: vec![b'a', b'z', b'q', b'b'],
                byte_ends: vec![b'b', b'z', b'q', b'b'],
            },
            CompileLimits::default(),
        )
        .unwrap()
    }

    fn direct_drop_loop_then_terminal() -> Automaton {
        // The retained frontier is `[A, B]`. On `x`, A survives and B dies;
        // unanchored root injection restores B, returning to the exact same
        // ordered state but mixing provenance. The self-loop is consequently
        // Drop, while a later `z` acceptance still belongs to the surviving
        // earlier A thread and requires reverse start recovery.
        Automaton::from_raw(
            RawPlan {
                start: 0,
                roles: vec![
                    StateRole::Split,
                    StateRole::Consume,
                    StateRole::Consume,
                    StateRole::Accept,
                ],
                edge_offsets: vec![0, 2, 4, 5, 5],
                edge_targets: vec![1, 2, 1, 3, 3],
                edge_kinds: vec![
                    EdgeKind::Epsilon,
                    EdgeKind::Epsilon,
                    EdgeKind::ByteRange,
                    EdgeKind::ByteRange,
                    EdgeKind::ByteRange,
                ],
                byte_starts: vec![0, 0, b'x', b'z', b'q'],
                byte_ends: vec![0, 0, b'x', b'z', b'q'],
            },
            CompileLimits::default(),
        )
        .unwrap()
    }

    fn direct_mixed_action_loops_then_terminal() -> Automaton {
        // Both `w..=x` and `y` return to `[A, B]`. The former kill B before
        // root injection restores it and are Drop transitions; `y` preserves
        // both source threads and is Propagate. Exact-action scanners must not
        // merge the adjacent graph classes.
        Automaton::from_raw(
            RawPlan {
                start: 0,
                roles: vec![
                    StateRole::Split,
                    StateRole::Consume,
                    StateRole::Consume,
                    StateRole::Accept,
                ],
                edge_offsets: vec![0, 2, 4, 6, 6],
                edge_targets: vec![1, 2, 1, 3, 2, 3],
                edge_kinds: vec![
                    EdgeKind::Epsilon,
                    EdgeKind::Epsilon,
                    EdgeKind::ByteRange,
                    EdgeKind::ByteRange,
                    EdgeKind::ByteRange,
                    EdgeKind::ByteRange,
                ],
                byte_starts: vec![0, 0, b'w', b'z', b'y', b'q'],
                byte_ends: vec![0, 0, b'y', b'z', b'y', b'q'],
            },
            CompileLimits::default(),
        )
        .unwrap()
    }

    fn full_byte_loop_class() -> Automaton {
        Automaton::from_raw(
            RawPlan {
                start: 0,
                roles: vec![StateRole::Consume, StateRole::Accept],
                edge_offsets: vec![0, 1, 1],
                edge_targets: vec![0],
                edge_kinds: vec![EdgeKind::ByteRange],
                byte_starts: vec![u8::MIN],
                byte_ends: vec![u8::MAX],
            },
            CompileLimits::default(),
        )
        .unwrap()
    }

    fn disjoint_ascii_and_high_loop_classes() -> Automaton {
        Automaton::from_raw(
            RawPlan {
                start: 0,
                roles: vec![StateRole::Consume, StateRole::Accept],
                edge_offsets: vec![0, 3, 3],
                edge_targets: vec![0, 0, 1],
                edge_kinds: vec![
                    EdgeKind::ByteRange,
                    EdgeKind::ByteRange,
                    EdgeKind::ByteRange,
                ],
                byte_starts: vec![b'a', 0x80, b'z'],
                byte_ends: vec![b'c', 0xff, b'z'],
            },
            CompileLimits::default(),
        )
        .unwrap()
    }

    fn contextual_high_loop_then_terminal(unicode: bool) -> Automaton {
        let assertions = if unicode {
            [
                EdgeKind::AssertWordUnicode,
                EdgeKind::AssertWordUnicodeNegate,
            ]
        } else {
            [
                EdgeKind::AssertWordAscii,
                EdgeKind::AssertWordAsciiNegate,
            ]
        };
        Automaton::from_raw(
            RawPlan {
                start: 0,
                roles: vec![StateRole::Consume, StateRole::Split, StateRole::Accept],
                edge_offsets: vec![0, 2, 4, 4],
                edge_targets: vec![1, 2, 0, 0],
                edge_kinds: vec![
                    EdgeKind::ByteRange,
                    EdgeKind::ByteRange,
                    assertions[0],
                    assertions[1],
                ],
                byte_starts: vec![0x80, b'z', 0, 0],
                byte_ends: vec![0xff, b'z', 0, 0],
            },
            CompileLimits::default(),
        )
        .unwrap()
    }

    fn contextual_high_loop_workspace(plan: &Automaton) -> K0Workspace {
        let mut workspace =
            K0Workspace::new_accelerated(plan, WorkspaceLimits::unlimited()).unwrap();
        let mut intern = WorkMeter::new(u64::MAX, 0);
        workspace.lazy.scratch[0] = 0;
        workspace.lazy.scratch_len = 1;
        assert_eq!(workspace.lazy.intern_initial(false, &mut intern, 0).unwrap(), 0);

        let dependencies = plan.boundary_context_classifier().assertions();
        let representative = 0x80_u8;
        let interior_assertions = super::enabled_assertion_mask_unmetered_for_dependencies(
            plan,
            dependencies,
            &[representative, representative],
            1,
        );
        let mut publish = WorkMeter::new(u64::MAX, 0);
        workspace
            .lazy
            .context
            .publish(
                Some(0),
                ContextTransitionSlot::populated(
                    0,
                    super::contextual_symbol_for_byte(plan, representative, interior_assertions),
                    1 | super::LazyStartAction::Propagate.cell_bits(),
                ),
                &mut publish,
                0,
                0,
            )
            .unwrap();
        workspace.lazy.context.hot[0].dependency_mask = dependencies;
        workspace.lazy.context_dependencies_analyzed = 1;
        workspace
    }

    fn direct_nonpending_loop_workspace(plan: &Automaton, cell: u32) -> K0Workspace {
        let mut workspace =
            K0Workspace::new_accelerated(plan, WorkspaceLimits::unlimited()).unwrap();
        let mut meter = WorkMeter::new(u64::MAX, 0);
        workspace.lazy.scratch[0] = 0;
        workspace.lazy.scratch_len = 1;
        assert_eq!(workspace.lazy.intern_initial(false, &mut meter, 0).unwrap(), 0);
        workspace.lazy.set_cell(0, 0, cell).unwrap();
        workspace
    }

    fn direct_equal_loop_cache_workspace(
        plan: &Automaton,
        discovery: [u32; 5],
        published_items: &[u32],
    ) -> (K0Workspace, [u32; 5]) {
        let mut workspace =
            K0Workspace::new_accelerated(plan, WorkspaceLimits::unlimited()).unwrap();
        let mut meter = WorkMeter::new(u64::MAX, 0);
        let mut states_by_item = [super::LAZY_NO_STATE; 5];
        for (ordinal, item) in discovery.into_iter().enumerate() {
            workspace.lazy.scratch[0] = item;
            workspace.lazy.scratch_len = 1;
            let state = if ordinal == 0 {
                workspace.lazy.intern_initial(false, &mut meter, 0).unwrap()
            } else {
                match workspace
                    .lazy
                    .intern_speculative(false, &mut meter, 0, 0)
                    .unwrap()
                {
                    super::LazyInterned::State(state) => state,
                    other => panic!("equal-loop state was not retained: {other:?}"),
                }
            };
            states_by_item[usize::try_from(item.checked_sub(1).unwrap()).unwrap()] = state;
        }
        let loop_bytes = [b'a', b'b', b'c', b'd', b'e'];
        for &item in published_items {
            let item_index = usize::try_from(item.checked_sub(1).unwrap()).unwrap();
            let state = states_by_item[item_index];
            let cell = workspace.lazy.encoded_state(state).unwrap()
                | super::LazyStartAction::Propagate.cell_bits();
            workspace
                .lazy
                .set_cell(state, byte_class(plan, loop_bytes[item_index]), cell)
                .unwrap();
        }
        (workspace, states_by_item)
    }

    fn direct_loop_cache_signature(
        workspace: &K0Workspace,
    ) -> Vec<(u32, super::LazyStartAction, [u64; 4])> {
        workspace
            .lazy
            .loop_skip_plans
            .entries
            .iter()
            .flatten()
            .map(|plan| {
                (
                    workspace.lazy.row_state(plan.row_offset),
                    plan.start_action,
                    plan.scanner.words(),
                )
            })
            .collect()
    }

    fn direct_loop_cache_items(workspace: &K0Workspace) -> Vec<u32> {
        let mut items = workspace
            .lazy
            .loop_skip_plans
            .entries
            .iter()
            .flatten()
            .map(|plan| {
                workspace
                    .lazy
                    .item(workspace.lazy.row_state(plan.row_offset), 0)
                    .unwrap()
            })
            .collect::<Vec<_>>();
        items.sort_unstable();
        items
    }

    fn direct_equal_loop_candidates(
        states_by_item: [u32; 5],
        items: [u32; super::LAZY_LOOP_SKIP_PLAN_CAPACITY],
    ) -> [Option<super::LazyLoopSkipCandidate>; super::LAZY_LOOP_SKIP_PLAN_CAPACITY] {
        let loop_bytes = [b'a', b'b', b'c', b'd', b'e'];
        let mut candidates = [None; super::LAZY_LOOP_SKIP_PLAN_CAPACITY];
        for (slot, item) in items.into_iter().enumerate() {
            let item_index = usize::try_from(item.checked_sub(1).unwrap()).unwrap();
            let mut members = [0_u64; 4];
            super::byte_bitmap_insert(&mut members, loop_bytes[item_index]);
            candidates[slot] = Some(super::LazyLoopSkipCandidate {
                state: states_by_item[item_index],
                members,
                start_action: super::LazyStartAction::Propagate,
            });
        }
        candidates
    }

    fn direct_loop_cache_slot_for_item(workspace: &K0Workspace, item: u32) -> usize {
        workspace
            .lazy
            .loop_skip_plans
            .entries
            .iter()
            .enumerate()
            .find_map(|(slot, plan)| {
                let state = workspace.lazy.row_state(plan.as_ref()?.row_offset);
                (workspace.lazy.item(state, 0).unwrap() == item).then_some(slot)
            })
            .expect("a retained direct loop item has one physical owner slot")
    }

    fn contextual_equal_loop_cache_workspace(
        plan: &Automaton,
        discovery: [u32; 5],
        published_items: &[u32],
    ) -> (K0Workspace, [u32; 5]) {
        let mut workspace =
            K0Workspace::new_accelerated(plan, WorkspaceLimits::unlimited()).unwrap();
        let mut meter = WorkMeter::new(u64::MAX, 0);
        let mut states_by_item = [super::LAZY_NO_STATE; 5];
        for (ordinal, item) in discovery.into_iter().enumerate() {
            workspace.lazy.scratch[0] = item;
            workspace.lazy.scratch_len = 1;
            let state = if ordinal == 0 {
                workspace.lazy.intern_initial(false, &mut meter, 0).unwrap()
            } else {
                match workspace
                    .lazy
                    .intern_speculative(false, &mut meter, 0, 0)
                    .unwrap()
                {
                    super::LazyInterned::State(state) => state,
                    other => panic!("equal contextual loop state was not retained: {other:?}"),
                }
            };
            states_by_item[usize::try_from(item.checked_sub(1).unwrap()).unwrap()] = state;
        }
        workspace.lazy.context.hot_initial.dependency_mask = 0;
        for state in 0..workspace.lazy.state_len {
            workspace.lazy.context.hot[state].dependency_mask = 0;
        }
        workspace.lazy.context_dependencies_analyzed = workspace.lazy.state_len;

        let loop_bytes = [b'a', b'b', b'c', b'd', b'e'];
        for &item in published_items {
            let item_index = usize::try_from(item.checked_sub(1).unwrap()).unwrap();
            let state = states_by_item[item_index];
            let symbol = super::contextual_symbol_for_byte(plan, loop_bytes[item_index], 0);
            let (cached, slot) = workspace
                .lazy
                .context
                .lookup(state, symbol, &mut meter, 0)
                .unwrap();
            assert!(cached.is_none());
            workspace
                .lazy
                .context
                .publish(
                    slot,
                    ContextTransitionSlot::populated(
                        state,
                        symbol,
                        state.checked_add(1).unwrap()
                            | super::LazyStartAction::Propagate.cell_bits(),
                    ),
                    &mut meter,
                    0,
                    0,
                )
                .unwrap();
        }
        (workspace, states_by_item)
    }

    fn contextual_loop_cache_signature(
        workspace: &K0Workspace,
    ) -> Vec<(u32, super::LazyStartAction, bool, [u64; 4])> {
        workspace
            .lazy
            .context_loop_skip_plans
            .entries
            .iter()
            .flatten()
            .map(|plan| {
                (
                    plan.state,
                    plan.start_action,
                    plan.leave_final_member,
                    plan.scanner.words(),
                )
            })
            .collect()
    }

    fn contextual_loop_cache_items(workspace: &K0Workspace) -> Vec<u32> {
        let mut items = workspace
            .lazy
            .context_loop_skip_plans
            .entries
            .iter()
            .flatten()
            .map(|plan| workspace.lazy.item(plan.state, 0).unwrap())
            .collect::<Vec<_>>();
        items.sort_unstable();
        items
    }

    fn contextual_equal_loop_candidates(
        states_by_item: [u32; 5],
        items: [u32; super::CONTEXT_LAZY_LOOP_SKIP_PLAN_CAPACITY],
    ) -> [Option<super::ContextLazyLoopSkipCandidate>;
        super::CONTEXT_LAZY_LOOP_SKIP_PLAN_CAPACITY] {
        let loop_bytes = [b'a', b'b', b'c', b'd', b'e'];
        let mut candidates = [None; super::CONTEXT_LAZY_LOOP_SKIP_PLAN_CAPACITY];
        for (slot, item) in items.into_iter().enumerate() {
            let item_index = usize::try_from(item.checked_sub(1).unwrap()).unwrap();
            let mut members = [0_u64; 4];
            super::byte_bitmap_insert(&mut members, loop_bytes[item_index]);
            candidates[slot] = Some(super::ContextLazyLoopSkipCandidate {
                state: states_by_item[item_index],
                members,
                start_action: super::LazyStartAction::Propagate,
                leave_final_member: false,
            });
        }
        candidates
    }

    fn contextual_loop_cache_slot_for_item(workspace: &K0Workspace, item: u32) -> usize {
        workspace
            .lazy
            .context_loop_skip_plans
            .entries
            .iter()
            .enumerate()
            .find_map(|(slot, plan)| {
                let state = plan.as_ref()?.state;
                (workspace.lazy.item(state, 0).unwrap() == item).then_some(slot)
            })
            .expect("a retained contextual loop item has one physical owner slot")
    }

    fn publish_contextual_equal_loop_item(
        plan: &Automaton,
        workspace: &mut K0Workspace,
        states_by_item: [u32; 5],
        item: u32,
    ) {
        let loop_bytes = [b'a', b'b', b'c', b'd', b'e'];
        let item_index = usize::try_from(item.checked_sub(1).unwrap()).unwrap();
        let state = states_by_item[item_index];
        let symbol = super::contextual_symbol_for_byte(plan, loop_bytes[item_index], 0);
        let mut meter = WorkMeter::new(u64::MAX, 0);
        let (cached, slot) = workspace
            .lazy
            .context
            .lookup(state, symbol, &mut meter, 0)
            .unwrap();
        assert!(cached.is_none());
        workspace
            .lazy
            .context
            .publish(
                slot,
                ContextTransitionSlot::populated(
                    state,
                    symbol,
                    state.checked_add(1).unwrap()
                        | super::LazyStartAction::Propagate.cell_bits(),
                ),
                &mut meter,
                0,
                0,
            )
            .unwrap();
    }

    fn direct_two_state_loop_workspace(plan: &Automaton) -> K0Workspace {
        let mut workspace =
            K0Workspace::new_accelerated(plan, WorkspaceLimits::unlimited()).unwrap();
        let mut meter = WorkMeter::new(u64::MAX, 0);
        workspace.lazy.scratch[0] = 0;
        workspace.lazy.scratch_len = 1;
        let initial = workspace.lazy.intern_initial(false, &mut meter, 0).unwrap();
        workspace.lazy.scratch[0] = 1;
        workspace.lazy.scratch_len = 1;
        let second = match workspace
            .lazy
            .intern_speculative(false, &mut meter, 0, 0)
            .unwrap()
        {
            super::LazyInterned::State(state) => state,
            other => panic!("second direct loop state was not retained: {other:?}"),
        };
        workspace.lazy.initial = initial;
        workspace.lazy.initial_kind = super::LazyInitialKind::Positive;
        workspace.lazy.initialized = true;

        let initial_loop = workspace.lazy.encoded_state(initial).unwrap()
            | super::LazyStartAction::Propagate.cell_bits();
        let enter_second = workspace.lazy.encoded_state(second).unwrap()
            | super::LazyStartAction::Propagate.cell_bits();
        let second_loop = workspace.lazy.encoded_state(second).unwrap()
            | super::LazyStartAction::Propagate.cell_bits();
        workspace
            .lazy
            .set_cell(initial, byte_class(plan, b'a'), initial_loop)
            .unwrap();
        workspace
            .lazy
            .set_cell(initial, byte_class(plan, b'x'), enter_second)
            .unwrap();
        workspace
            .lazy
            .set_cell(second, byte_class(plan, b'c'), second_loop)
            .unwrap();
        let mut derive = WorkMeter::new(u64::MAX, 0);
        super::try_derive_lazy_loop_skip(plan, &mut workspace, &mut derive).unwrap();
        assert_eq!(workspace.lazy.loop_skip_plans.len(), 2);
        workspace
    }

    fn narrow_then_high_loop_workspace(plan: &Automaton, cell: u32) -> K0Workspace {
        let mut workspace =
            K0Workspace::new_accelerated(plan, WorkspaceLimits::unlimited()).unwrap();
        let mut intern = WorkMeter::new(u64::MAX, 0);
        workspace.lazy.scratch[0] = 0;
        workspace.lazy.scratch_len = 1;
        assert_eq!(workspace.lazy.intern_initial(false, &mut intern, 0).unwrap(), 0);
        workspace
            .lazy
            .set_cell(0, byte_class(plan, b'a'), cell)
            .unwrap();
        let mut derive = WorkMeter::new(u64::MAX, 0);
        super::try_derive_lazy_loop_skip(plan, &mut workspace, &mut derive).unwrap();
        assert_eq!(
            workspace
                .lazy
                .loop_skip_plans
                .first()
                .expect("the narrow loop plan must be retained")
                .scanner
                .cardinality(),
            3
        );
        workspace
            .lazy
            .set_cell(0, byte_class(plan, 0x80), cell)
            .unwrap();
        workspace
    }

    fn contextual_nonpending_loop_then_terminal() -> Automaton {
        // State zero has an exact nonpending `a` self-loop and a terminal `z`
        // edge. The reachable `q`/`r` branch makes the automaton contextual,
        // but its assertion is beyond another Consume and is therefore not a
        // dependency of state zero or of its root closure.
        Automaton::from_raw(
            RawPlan {
                start: 0,
                roles: vec![
                    StateRole::Consume,
                    StateRole::Accept,
                    StateRole::Consume,
                    StateRole::Split,
                    StateRole::Accept,
                ],
                edge_offsets: vec![0, 3, 3, 4, 5, 5],
                edge_targets: vec![0, 1, 2, 3, 4],
                edge_kinds: vec![
                    EdgeKind::ByteRange,
                    EdgeKind::ByteRange,
                    EdgeKind::ByteRange,
                    EdgeKind::ByteRange,
                    EdgeKind::AssertLineEndLf,
                ],
                byte_starts: vec![b'a', b'z', b'q', b'r', 0],
                byte_ends: vec![b'a', b'z', b'q', b'r', 0],
            },
            CompileLimits::default(),
        )
        .unwrap()
    }

    fn contextual_split_loop_then_terminal() -> Automaton {
        // State zero has an assertion-independent `a`/`b` self-loop. The
        // reachable `q b` assertion branch makes the plan contextual and
        // splits the two loop members into distinct global byte classes,
        // without making that assertion a dependency of state zero.
        Automaton::from_raw(
            RawPlan {
                start: 0,
                roles: vec![
                    StateRole::Consume,
                    StateRole::Accept,
                    StateRole::Consume,
                    StateRole::Split,
                    StateRole::Accept,
                ],
                edge_offsets: vec![0, 3, 3, 4, 5, 5],
                edge_targets: vec![0, 1, 2, 3, 4],
                edge_kinds: vec![
                    EdgeKind::ByteRange,
                    EdgeKind::ByteRange,
                    EdgeKind::ByteRange,
                    EdgeKind::ByteRange,
                    EdgeKind::AssertLineEndLf,
                ],
                byte_starts: vec![b'a', b'z', b'q', b'b', 0],
                byte_ends: vec![b'b', b'z', b'q', b'b', 0],
            },
            CompileLimits::default(),
        )
        .unwrap()
    }

    fn contextual_word_loop_then_terminal() -> Automaton {
        // Both complementary word assertions return the `a` transition to
        // state zero. Its exact state transition is therefore a self-loop in
        // both interior and endpoint contexts, but the published symbols and
        // start-provenance actions remain context specific.
        Automaton::from_raw(
            RawPlan {
                start: 0,
                roles: vec![StateRole::Consume, StateRole::Split, StateRole::Accept],
                edge_offsets: vec![0, 2, 4, 4],
                edge_targets: vec![1, 2, 0, 0],
                edge_kinds: vec![
                    EdgeKind::ByteRange,
                    EdgeKind::ByteRange,
                    EdgeKind::AssertWordAscii,
                    EdgeKind::AssertWordAsciiNegate,
                ],
                byte_starts: vec![b'a', b'z', 0, 0],
                byte_ends: vec![b'a', b'z', 0, 0],
            },
            CompileLimits::default(),
        )
        .unwrap()
    }

    fn contextual_unicode_word_loop_then_terminal() -> Automaton {
        Automaton::from_raw(
            RawPlan {
                start: 0,
                roles: vec![StateRole::Consume, StateRole::Split, StateRole::Accept],
                edge_offsets: vec![0, 2, 4, 4],
                edge_targets: vec![1, 2, 0, 0],
                edge_kinds: vec![
                    EdgeKind::ByteRange,
                    EdgeKind::ByteRange,
                    EdgeKind::AssertWordUnicode,
                    EdgeKind::AssertWordUnicodeNegate,
                ],
                byte_starts: vec![b'a', b'z', 0, 0],
                byte_ends: vec![b'a', b'z', 0, 0],
            },
            CompileLimits::default(),
        )
        .unwrap()
    }

    fn anchored_unicode_negated_word_loop_then_terminals() -> Automaton {
        // The anchored `a` loop survives only while the destination boundary
        // has equal, valid Unicode-word sides. `z` and any high byte are
        // terminals. Consequently the final ASCII member must be evaluated
        // scalar when the following context is punctuation, malformed UTF-8,
        // a non-word scalar or the haystack endpoint.
        Automaton::from_raw(
            RawPlan {
                start: 0,
                roles: vec![
                    StateRole::Split,
                    StateRole::Consume,
                    StateRole::Split,
                    StateRole::Accept,
                ],
                edge_offsets: vec![0, 1, 4, 5, 5],
                edge_targets: vec![1, 2, 3, 3, 1],
                edge_kinds: vec![
                    EdgeKind::AssertHaystackStart,
                    EdgeKind::ByteRange,
                    EdgeKind::ByteRange,
                    EdgeKind::ByteRange,
                    EdgeKind::AssertWordUnicodeNegate,
                ],
                byte_starts: vec![0, b'a', b'z', 0x80, 0],
                byte_ends: vec![0, b'a', b'z', 0xff, 0],
            },
            CompileLimits::default(),
        )
        .unwrap()
    }

    fn contextual_unicode_drop_loop_then_terminal_byte(terminal: u8) -> Automaton {
        // The retained frontier is `[A, B]`. On `x`, A survives and B dies;
        // unanchored root injection restores B, returning to the exact same
        // ordered state but mixing provenance. The Unicode word-boundary edge
        // is false between ASCII word bytes, so the authenticated contextual
        // self-loop is Drop. A later `z` acceptance requires reverse recovery.
        Automaton::from_raw(
            RawPlan {
                start: 0,
                roles: vec![
                    StateRole::Split,
                    StateRole::Consume,
                    StateRole::Consume,
                    StateRole::Split,
                    StateRole::Accept,
                ],
                edge_offsets: vec![0, 2, 4, 5, 6, 6],
                edge_targets: vec![1, 2, 1, 4, 3, 4],
                edge_kinds: vec![
                    EdgeKind::Epsilon,
                    EdgeKind::Epsilon,
                    EdgeKind::ByteRange,
                    EdgeKind::ByteRange,
                    EdgeKind::ByteRange,
                    EdgeKind::AssertWordUnicode,
                ],
                byte_starts: vec![0, 0, b'x', terminal, b'q', 0],
                byte_ends: vec![0, 0, b'x', terminal, b'q', 0],
            },
            CompileLimits::default(),
        )
        .unwrap()
    }

    fn contextual_unicode_drop_loop_then_terminal() -> Automaton {
        contextual_unicode_drop_loop_then_terminal_byte(b'z')
    }

    fn contextual_word_loop_workspace(plan: &Automaton) -> K0Workspace {
        let mut workspace =
            K0Workspace::new_accelerated(plan, WorkspaceLimits::unlimited()).unwrap();
        let mut intern = WorkMeter::new(u64::MAX, 0);
        workspace.lazy.scratch[0] = 0;
        workspace.lazy.scratch_len = 1;
        assert_eq!(workspace.lazy.intern_initial(false, &mut intern, 0).unwrap(), 0);

        let dependencies = plan.boundary_context_classifier().assertions();
        let interior_assertions = super::enabled_assertion_mask_unmetered_for_dependencies(
            plan,
            dependencies,
            b"aa",
            1,
        );
        let endpoint_assertions = super::enabled_assertion_mask_unmetered_for_dependencies(
            plan,
            dependencies,
            b"a",
            1,
        );
        assert_ne!(interior_assertions, endpoint_assertions);
        let mut publish = WorkMeter::new(u64::MAX, 0);
        workspace
            .lazy
            .context
            .publish(
                Some(0),
                ContextTransitionSlot::populated(
                    0,
                    super::contextual_symbol_for_byte(plan, b'a', interior_assertions),
                    1 | super::LazyStartAction::Propagate.cell_bits(),
                ),
                &mut publish,
                0,
                0,
            )
            .unwrap();
        workspace
            .lazy
            .context
            .publish(
                Some(1),
                ContextTransitionSlot::populated(
                    0,
                    super::contextual_symbol_for_byte(plan, b'a', endpoint_assertions),
                    1 | super::LazyStartAction::Drop.cell_bits(),
                ),
                &mut publish,
                0,
                0,
            )
            .unwrap();
        workspace.lazy.context.hot[0].dependency_mask = dependencies;
        workspace.lazy.context_dependencies_analyzed = 1;
        workspace
    }

    fn contextual_pair_loop_workspace(
        plan: &Automaton,
        left_representatives: &[u8],
        right_representatives: &[u8],
        action: super::LazyStartAction,
        omitted: Option<(u8, u8)>,
    ) -> K0Workspace {
        let mut workspace =
            K0Workspace::new_accelerated(plan, WorkspaceLimits::unlimited()).unwrap();
        let mut meter = WorkMeter::new(u64::MAX, 0);
        workspace.lazy.scratch[0] = 0;
        workspace.lazy.scratch_len = 1;
        assert_eq!(workspace.lazy.intern_initial(false, &mut meter, 0).unwrap(), 0);
        let dependencies = plan.boundary_context_classifier().assertions();
        let value = 1 | action.cell_bits();
        for &left in left_representatives {
            for &right in right_representatives {
                if omitted == Some((left, right)) {
                    continue;
                }
                let assertions = super::enabled_assertion_mask_unmetered_for_dependencies(
                    plan,
                    dependencies,
                    &[left, right],
                    1,
                );
                let symbol = super::contextual_symbol_for_byte(plan, left, assertions);
                let (cached, slot) = workspace
                    .lazy
                    .context
                    .lookup(0, symbol, &mut meter, 0)
                    .unwrap();
                if let Some(cached) = cached {
                    assert_eq!(cached, value);
                    continue;
                }
                workspace
                    .lazy
                    .context
                    .publish(
                        slot,
                        ContextTransitionSlot::populated(0, symbol, value),
                        &mut meter,
                        0,
                        0,
                    )
                    .unwrap();
            }
        }
        workspace.lazy.context.hot[0].dependency_mask = dependencies;
        workspace.lazy.context_dependencies_analyzed = 1;
        workspace
    }

    fn a_question(greedy: bool) -> Automaton {
        let split_targets = if greedy { [1, 2] } else { [2, 1] };
        Automaton::from_raw(
            RawPlan {
                start: 0,
                roles: vec![StateRole::Split, StateRole::Consume, StateRole::Accept],
                edge_offsets: vec![0, 2, 3, 3],
                edge_targets: vec![split_targets[0], split_targets[1], 2],
                edge_kinds: vec![EdgeKind::Epsilon, EdgeKind::Epsilon, EdgeKind::ByteRange],
                byte_starts: vec![0, 0, b'a'],
                byte_ends: vec![0, 0, b'a'],
            },
            CompileLimits::default(),
        )
        .unwrap()
    }

