    #[test]
    fn unicode_context_loop_keeps_endpoint_and_nonascii_successors_scalar_after_mutation() {
        let plan = anchored_unicode_negated_word_loop_then_terminals();
        let run_len = super::LAZY_LOOP_SKIP_MIN_BYTES * 3;
        let mut haystack = vec![b'a'; run_len + 4];
        haystack[run_len..].copy_from_slice(b"z!!!");
        let address = haystack.as_ptr();
        let mut workspace =
            K0Workspace::new_bidirectional(&plan, WorkspaceLimits::unlimited()).unwrap();

        let learned = plan
            .prepare::<Span>()
            .search_with_workspace(&haystack, &mut workspace, SearchLimits::unlimited())
            .unwrap();
        assert_eq!(learned.output(), &Some(MatchSpan::new(0, run_len + 1)));
        let loop_plan = workspace
            .lazy
            .context_loop_skip_plans
            .first()
            .expect("the warmed ASCII Unicode-word loop must retain a scanner");
        assert!(loop_plan.leave_final_member);
        assert!(loop_plan.scanner.contains(b'a'));
        assert!(!loop_plan.scanner.contains(b'!'));

        let (skipped, skipped_work) = {
            let mut meter = WorkMeter::new(u64::MAX, 0);
            let mut adaptive = super::AdaptiveStartProbe::default();
            let result = super::execute_context_lazy_loop::<true>(
                &plan,
                &haystack,
                SearchWindow::full(&haystack),
                &mut workspace,
                &mut meter,
                OutputContract::Span,
                0,
                None,
                None,
                None,
                false,
                false,
                &mut adaptive,
            )
            .unwrap()
            .unwrap();
            (result, meter.consumed)
        };
        let (scalar, scalar_work) = {
            let mut meter = WorkMeter::new(u64::MAX, 0);
            let mut adaptive = super::AdaptiveStartProbe::default();
            let result = super::execute_context_lazy_loop::<false>(
                &plan,
                &haystack,
                SearchWindow::full(&haystack),
                &mut workspace,
                &mut meter,
                OutputContract::Span,
                0,
                None,
                None,
                None,
                false,
                false,
                &mut adaptive,
            )
            .unwrap()
            .unwrap();
            (result, meter.consumed)
        };
        assert_eq!(skipped.0, scalar.0);
        assert!(
            skipped_work < scalar_work,
            "the retained plan must execute the long interior through its run scanner"
        );

        let suffixes = [
            [b'z', b'!', b'!', b'!'],
            [b'!', b'z', b'!', b'!'],
            [0xc3, 0xa9, b'z', b'!'],
            [0xf0, 0x9f, 0x92, 0xa9],
            [0xf0, 0x28, 0x8c, 0xbc],
            [0xc3, b'z', b'!', b'!'],
            [0x80, b'z', b'!', b'!'],
        ];
        for suffix in suffixes {
            haystack[run_len..].copy_from_slice(&suffix);
            assert_eq!(haystack.as_ptr(), address);
            let mut reference = K0Workspace::new(&plan, WorkspaceLimits::unlimited()).unwrap();
            let expected = plan
                .prepare::<Span>()
                .search_with_workspace(&haystack, &mut reference, SearchLimits::unlimited())
                .unwrap()
                .into_output();
            let actual = plan
                .prepare::<Span>()
                .search_with_workspace(&haystack, &mut workspace, SearchLimits::unlimited())
                .unwrap()
                .into_output();
            assert_eq!(
                actual, expected,
                "same-address Unicode successor mismatch suffix={suffix:?}"
            );
        }

        let endpoint = &haystack[..run_len];
        let mut reference = K0Workspace::new(&plan, WorkspaceLimits::unlimited()).unwrap();
        let expected = plan
            .prepare::<Span>()
            .search_with_workspace(endpoint, &mut reference, SearchLimits::unlimited())
            .unwrap()
            .into_output();
        let actual = plan
            .prepare::<Span>()
            .search_with_workspace(endpoint, &mut workspace, SearchLimits::unlimited())
            .unwrap()
            .into_output();
        assert_eq!(actual, expected, "the real haystack endpoint must remain scalar");

        haystack[run_len..].copy_from_slice(&[0xf0, 0x9f, 0x92, 0xa9]);
        let clipped = SearchWindow::new(0, run_len);
        let mut reference = K0Workspace::new(&plan, WorkspaceLimits::unlimited()).unwrap();
        let expected = plan
            .prepare::<Span>()
            .search_window_with_workspace(
                &haystack,
                clipped,
                &mut reference,
                SearchLimits::unlimited(),
            )
            .unwrap()
            .into_output();
        let actual = plan
            .prepare::<Span>()
            .search_window_with_workspace(
                &haystack,
                clipped,
                &mut workspace,
                SearchLimits::unlimited(),
            )
            .unwrap()
            .into_output();
        assert_eq!(actual, expected);
    }

    #[test]
    fn contextual_pending_loop_plan_handles_context_stable_interior_runs() {
        let plan = absolute_a_greedy_any_star_z();
        let mut workspace =
            K0Workspace::new_bidirectional(&plan, WorkspaceLimits::unlimited()).unwrap();
        let mut haystack = vec![b'!'; 4_096];
        haystack[0] = b'a';
        haystack[1] = b'z';
        let address = haystack.as_ptr();

        let first = plan
            .prepare::<Span>()
            .search_with_workspace(&haystack, &mut workspace, SearchLimits::unlimited())
            .unwrap();
        let scalar_boundaries = first.accounting().boundaries();
        assert_eq!(first.into_output(), Some(MatchSpan::new(0, 2)));
        let loop_plan = workspace
            .lazy
            .context_loop_skip_plans
            .first()
            .expect("the assertion-free pending suffix must retain a contextual scanner");
        assert_eq!(
            workspace.lazy.context.hot_initial.dependency_mask,
            EdgeKind::AssertHaystackStart.assertion_bit().unwrap()
        );
        assert_eq!(
            workspace
                .lazy
                .exact_context_dependency_mask(loop_plan.state)
                .unwrap(),
            Some(0),
            "pending continuation dependencies must exclude the asserted root"
        );
        assert!(loop_plan.scanner.contains(b'!'));
        assert!(loop_plan.scanner.contains(b'b'));

        let assertions = super::enabled_assertion_mask_unmetered(&plan, &haystack, 3);
        let inferred_symbol = super::contextual_symbol_for_byte(&plan, b'b', assertions);
        assert_eq!(
            workspace
                .lazy
                .context
                .lookup_existing_prevalidated(loop_plan.state, inferred_symbol)
                .unwrap(),
            None,
            "graph equivalence must not impersonate contextual publication"
        );
        let published = workspace.lazy.context.published;

        haystack[2..].fill(b'b');
        assert_eq!(address, haystack.as_ptr());
        let second = plan
            .prepare::<Span>()
            .search_with_workspace(&haystack, &mut workspace, SearchLimits::unlimited())
            .unwrap();
        assert_eq!(second.into_output(), Some(MatchSpan::new(0, 2)));
        assert_eq!(workspace.lazy.context.published, published);
        assert_eq!(
            workspace
                .lazy
                .context
                .lookup_existing_prevalidated(loop_plan.state, inferred_symbol)
                .unwrap(),
            None
        );

        let measured = plan
            .prepare::<Span>()
            .search_with_workspace(&haystack, &mut workspace, SearchLimits::unlimited())
            .unwrap();
        assert_eq!(measured.into_output(), Some(MatchSpan::new(0, 2)));
        assert_eq!(
            measured.accounting().boundaries(),
            scalar_boundaries,
            "contextual bulk scanning must retain scalar boundary accounting"
        );

        // Contextual loop plans are deliberately unlimited-only. A finite
        // report retains the original assertion and associative-lookup work.
        let retained = workspace.retained_bytes();
        let finite = SearchLimits {
            max_work: u64::MAX - 1,
            max_scratch_bytes: retained,
        };
        let finite_report = plan
            .prepare::<Span>()
            .search_with_workspace(&haystack, &mut workspace, finite)
            .unwrap();
        assert_eq!(finite_report.output(), &Some(MatchSpan::new(0, 2)));
        assert_eq!(finite_report.accounting().boundaries(), scalar_boundaries);

        let asserted = asserted_pending_a_greedy_any_star_z();
        let mut asserted_workspace =
            K0Workspace::new_bidirectional(&asserted, WorkspaceLimits::unlimited()).unwrap();
        assert_eq!(
            asserted
                .prepare::<Span>()
                .search_with_workspace(
                    &haystack,
                    &mut asserted_workspace,
                    SearchLimits::unlimited(),
                )
                .unwrap()
                .into_output(),
            Some(MatchSpan::new(0, 2))
        );
        let asserted_loop = asserted_workspace
            .lazy
            .context_loop_skip_plans
            .first()
            .expect("a context-stable interior must retain a loop scanner");
        assert!(asserted_loop.leave_final_member);
        assert!(asserted_loop.scanner.contains(b'b'));
        assert!(!asserted_loop.scanner.contains(b'!'));
        assert!(
            asserted_workspace.lazy.context.hot[..asserted_workspace.lazy.state_len]
                .iter()
                .zip(&asserted_workspace.lazy.modes)
                .any(|(hot, &pending)| pending != 0
                    && hot.dependency_mask != super::CONTEXT_DEPENDENCY_UNCOMPUTED
                    && hot.dependency_mask != 0),
            "the asserted pending state must retain its contextual dependency"
        );
    }

    #[test]
    fn direct_drop_loop_skip_preserves_reverse_finite_limits_and_source_mutation() {
        let plan = direct_drop_loop_then_terminal();
        pin_without_start_filter(&plan);
        let run_len = super::LAZY_LOOP_SKIP_MIN_BYTES * 3;
        let mut haystack = vec![b'x'; run_len];
        haystack.push(b'z');
        let address = haystack.as_ptr();
        let window = SearchWindow::full(&haystack);
        let mut workspace =
            K0Workspace::new_bidirectional(&plan, WorkspaceLimits::unlimited()).unwrap();

        assert_eq!(
            plan.prepare::<SelectedEnd>()
                .search_with_workspace(
                    &haystack,
                    &mut workspace,
                    SearchLimits::unlimited(),
                )
                .unwrap()
                .into_output(),
            Some(haystack.len())
        );
        let loop_plan = workspace
            .lazy
            .loop_skip_plans
            .first()
            .expect("the direct nonpending Drop self-loop must retain a scanner");
        assert_eq!(loop_plan.start_action, super::LazyStartAction::Drop);
        assert!(loop_plan.scanner.contains(b'x'));
        assert!(!loop_plan.scanner.contains(b'z'));
        assert!(!workspace.reverse.initialized);

        let mut scalar_meter = WorkMeter::new(u64::MAX, 0);
        let mut scalar_adaptive = super::AdaptiveStartProbe::default();
        let scalar = super::execute_lazy_span_loop::<true, false>(
            &plan,
            &haystack,
            window,
            &mut workspace,
            &mut scalar_meter,
            OutputContract::Span,
            0,
            None,
            None,
            None,
            &mut scalar_adaptive,
            super::DirectLazyReady,
        )
        .unwrap()
        .unwrap();
        let mut skipped_meter = WorkMeter::new(u64::MAX, 0);
        let mut skipped_adaptive = super::AdaptiveStartProbe::default();
        let skipped = super::execute_lazy_span_loop::<true, true>(
            &plan,
            &haystack,
            window,
            &mut workspace,
            &mut skipped_meter,
            OutputContract::Span,
            0,
            None,
            None,
            None,
            &mut skipped_adaptive,
            super::DirectLazyReady,
        )
        .unwrap()
        .unwrap();
        assert_eq!(skipped.0, scalar.0);
        assert_eq!(skipped.1, scalar.1);
        assert!(!scalar.2);
        assert!(!skipped.2, "Drop scanning must not invent start provenance");
        assert_eq!(skipped_meter.consumed, scalar_meter.consumed);

        assert_eq!(
            plan.prepare::<Span>()
                .search_with_workspace(
                    &haystack,
                    &mut workspace,
                    SearchLimits::unlimited(),
                )
                .unwrap()
                .into_output(),
            Some(MatchSpan::new(0, haystack.len()))
        );
        assert!(workspace.reverse.initialized);

        let measured = plan
            .prepare::<Span>()
            .search_with_workspace(
                &haystack,
                &mut workspace,
                SearchLimits::unlimited(),
            )
            .unwrap();
        assert_eq!(measured.output(), &Some(MatchSpan::new(0, haystack.len())));
        let exact_work = measured.accounting().work();
        let retained = workspace.retained_bytes();
        assert_eq!(
            plan.prepare::<Span>()
                .search_with_workspace(
                    &haystack,
                    &mut workspace,
                    SearchLimits {
                        max_work: exact_work,
                        max_scratch_bytes: retained,
                    },
                )
                .unwrap()
                .into_output(),
            Some(MatchSpan::new(0, haystack.len()))
        );
        assert!(matches!(
            plan.prepare::<Span>().search_with_workspace(
                &haystack,
                &mut workspace,
                SearchLimits {
                    max_work: exact_work.checked_sub(1).unwrap(),
                    max_scratch_bytes: retained,
                },
            ),
            Err(SearchError::WorkLimitExceeded { limit, .. })
                if limit == exact_work.checked_sub(1).unwrap()
        ));

        let reset_at = run_len / 2;
        haystack[reset_at] = b'!';
        assert_eq!(haystack.as_ptr(), address);
        let mut reference = K0Workspace::new(&plan, WorkspaceLimits::unlimited()).unwrap();
        let expected = plan
            .prepare::<Span>()
            .search_with_workspace(
                &haystack,
                &mut reference,
                SearchLimits::unlimited(),
            )
            .unwrap()
            .into_output();
        let actual = plan
            .prepare::<Span>()
            .search_with_workspace(
                &haystack,
                &mut workspace,
                SearchLimits::unlimited(),
            )
            .unwrap()
            .into_output();
        assert_eq!(expected, Some(MatchSpan::new(reset_at + 1, haystack.len())));
        assert_eq!(actual, expected);
    }

    #[test]
    fn contextual_drop_loop_skip_preserves_later_reverse_recovery() {
        let plan = contextual_unicode_drop_loop_then_terminal();
        let mut haystack = vec![b'x'; super::LAZY_LOOP_SKIP_MIN_BYTES * 3];
        haystack.push(b'z');
        let window = SearchWindow::full(&haystack);
        let mut workspace =
            K0Workspace::new_bidirectional(&plan, WorkspaceLimits::unlimited()).unwrap();

        let mut meter = WorkMeter::new(u64::MAX, 0);
        let mut adaptive = super::AdaptiveStartProbe::default();
        let learned = super::execute_context_lazy_loop::<false>(
            &plan,
            &haystack,
            window,
            &mut workspace,
            &mut meter,
            OutputContract::Span,
            0,
            None,
            None,
            None,
            false,
            false,
            &mut adaptive,
        )
        .unwrap()
        .unwrap();
        assert_eq!(learned.0, Some(MatchSpan::new(0, haystack.len())));
        assert!(!learned.2);
        super::try_learn_context_dependency_masks(&plan, &mut workspace, &mut meter).unwrap();
        super::try_derive_context_lazy_loop_skip(&plan, &mut workspace, &mut meter).unwrap();
        let loop_plan = workspace
            .lazy
            .context_loop_skip_plans
            .first()
            .expect("the Unicode-dependent nonpending Drop self-loop must retain a scanner");
        assert_eq!(loop_plan.start_action, super::LazyStartAction::Drop);
        assert!(loop_plan.leave_final_member);
        assert!(loop_plan.scanner.contains(b'x'));
        assert_ne!(
            workspace
                .lazy
                .exact_context_dependency_mask(loop_plan.state)
                .unwrap()
                .unwrap()
                & plan.boundary_context_classifier().unicode_word(),
            0
        );
        assert!(!workspace.reverse.initialized);

        let mut meter = WorkMeter::new(u64::MAX, 0);
        let mut adaptive = super::AdaptiveStartProbe::default();
        let skipped = super::execute_context_lazy_loop::<true>(
            &plan,
            &haystack,
            window,
            &mut workspace,
            &mut meter,
            OutputContract::Span,
            0,
            None,
            None,
            None,
            false,
            false,
            &mut adaptive,
        )
        .unwrap()
        .unwrap();
        assert_eq!(skipped.0, learned.0);
        assert!(!skipped.2, "Drop scanning must not invent start provenance");

        assert_eq!(
            plan.prepare::<Span>()
                .search_with_workspace(
                    &haystack,
                    &mut workspace,
                    SearchLimits::unlimited(),
                )
                .unwrap()
                .into_output(),
            Some(MatchSpan::new(0, haystack.len()))
        );
        assert!(workspace.reverse.initialized);
    }

    #[test]
    fn singleton_start_certificate_is_exhaustive_and_never_reads_reverse_rows() {
        let plans = [
            ("one-byte", byte_chain(&[(b'a', b'a')])),
            ("greedy-plus", a_plus(true)),
            ("lazy-plus", a_plus(false)),
        ];
        let haystacks = bounded_words(&[b'a', b'b', 0xff], 4);
        let mut checked = 0usize;

        for (name, plan) in &plans {
            pin_without_start_filter(plan);
            let mut pike = K0Workspace::new(plan, WorkspaceLimits::unlimited()).unwrap();
            let mut direct =
                K0Workspace::new_bidirectional(plan, WorkspaceLimits::unlimited()).unwrap();
            for haystack in &haystacks {
                for start in 0..=haystack.len() {
                    for end in start..=haystack.len() {
                        let window = SearchWindow::new(start, end);
                        let want = plan
                            .prepare::<Span>()
                            .search_window_with_workspace(
                                haystack,
                                window,
                                &mut pike,
                                SearchLimits::unlimited(),
                            )
                            .unwrap();
                        let got = plan
                            .prepare::<Span>()
                            .search_window_with_workspace(
                                haystack,
                                window,
                                &mut direct,
                                SearchLimits::unlimited(),
                            )
                            .unwrap();
                        assert_eq!(
                            got.output(),
                            want.output(),
                            "{name}: source={haystack:?} window={window:?}"
                        );
                        checked = checked.checked_add(1).unwrap();
                    }
                }
            }
            assert_eq!(
                direct.lazy.initial_kind,
                super::LazyInitialKind::PositiveSingle,
                "{name}"
            );
            assert!(direct.reverse.initialized, "{name}");
            assert!(
                direct
                    .reverse
                    .rows
                    .iter()
                    .all(|&cell| cell == super::LAZY_CELL_UNFILLED),
                "{name}: a certified span must not execute reverse recovery"
            );
        }
        assert!(checked > 1_000);
    }

    #[test]
    fn uniform_multi_item_start_certificate_is_exhaustive_and_drops_on_mixed_provenance() {
        let plans = [
            ("greedy-plus-or-a", greedy_a_plus_or_a(), true),
            ("long-a-or-ab", ordered_a_or_ab(true), true),
            ("ab-or-ac", ordered_ab_or_ac(), false),
        ];
        let haystacks = bounded_words(&[b'a', b'b', b'c', 0xff], 4);
        let mut checked = 0usize;

        for (name, plan, remains_uniform) in &plans {
            pin_without_start_filter(plan);
            let mut pike = K0Workspace::new(plan, WorkspaceLimits::unlimited()).unwrap();
            let mut direct =
                K0Workspace::new_bidirectional(plan, WorkspaceLimits::unlimited()).unwrap();
            for haystack in &haystacks {
                for start in 0..=haystack.len() {
                    for end in start..=haystack.len() {
                        let window = SearchWindow::new(start, end);
                        let want = plan
                            .prepare::<Span>()
                            .search_window_with_workspace(
                                haystack,
                                window,
                                &mut pike,
                                SearchLimits::unlimited(),
                            )
                            .unwrap();
                        let got = plan
                            .prepare::<Span>()
                            .search_window_with_workspace(
                                haystack,
                                window,
                                &mut direct,
                                SearchLimits::unlimited(),
                            )
                            .unwrap();
                        assert_eq!(
                            got.output(),
                            want.output(),
                            "{name}: source={haystack:?} window={window:?}"
                        );
                        checked = checked.checked_add(1).unwrap();
                    }
                }
            }
            assert_eq!(
                direct.lazy.initial_kind,
                super::LazyInitialKind::Positive,
                "{name}: the initial closure must contain multiple consuming items"
            );
            assert!(direct.reverse.initialized, "{name}");
            let reverse_untouched = direct
                .reverse
                .rows
                .iter()
                .all(|&cell| cell == super::LAZY_CELL_UNFILLED);
            assert_eq!(
                reverse_untouched, *remains_uniform,
                "{name}: reverse execution must follow the provenance certificate"
            );
        }
        assert!(checked > 10_000);
    }

    #[test]
    fn certified_span_preserves_exact_finite_work_and_boundary_accounting() {
        let plan = a_plus(true);
        pin_without_start_filter(&plan);
        let haystack = b"baaaa";
        let mut workspace =
            K0Workspace::new_bidirectional(&plan, WorkspaceLimits::unlimited()).unwrap();
        let retained = workspace.retained_bytes();

        let span = plan
            .prepare::<Span>()
            .search_with_workspace(haystack, &mut workspace, SearchLimits::unlimited())
            .unwrap();
        assert_eq!(span.output(), &Some(MatchSpan::new(1, haystack.len())));
        assert!(workspace
            .reverse
            .rows
            .iter()
            .all(|&cell| cell == super::LAZY_CELL_UNFILLED));
        let selected = plan
            .prepare::<SelectedEnd>()
            .search_with_workspace(haystack, &mut workspace, SearchLimits::unlimited())
            .unwrap();
        assert_eq!(
            span.accounting().boundaries(),
            selected.accounting().boundaries()
        );

        let measured = plan
            .prepare::<Span>()
            .search_with_workspace(haystack, &mut workspace, SearchLimits::unlimited())
            .unwrap()
            .accounting()
            .work();
        assert_eq!(
            plan.prepare::<Span>()
                .search_with_workspace(
                    haystack,
                    &mut workspace,
                    SearchLimits {
                        max_work: measured,
                        max_scratch_bytes: retained,
                    },
                )
                .unwrap()
                .into_output(),
            Some(MatchSpan::new(1, haystack.len()))
        );
        assert!(matches!(
            plan.prepare::<Span>().search_with_workspace(
                haystack,
                &mut workspace,
                SearchLimits {
                    max_work: measured - 1,
                    max_scratch_bytes: retained,
                },
            ),
            Err(SearchError::WorkLimitExceeded { limit, .. }) if limit == measured - 1
        ));
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "nullable priority needs all four contracts over the same exhaustive windows"
    )]
    fn nullable_ordered_lazy_dfa_matches_pike_for_every_contract_and_window() {
        let plans = [
            ("greedy-star", a_star(true), false),
            ("lazy-star", a_star(false), true),
            ("greedy-question", a_question(true), false),
            ("lazy-question", a_question(false), true),
            ("empty-first-greedy-plus", empty_or_a_plus(true, true), true),
            ("empty-first-lazy-plus", empty_or_a_plus(true, false), true),
            (
                "positive-first-greedy-plus",
                empty_or_a_plus(false, true),
                false,
            ),
            (
                "positive-first-lazy-plus",
                empty_or_a_plus(false, false),
                false,
            ),
            ("empty-first-ab", empty_or_ab(true), true),
            ("positive-first-ab", empty_or_ab(false), false),
        ];
        let haystacks = bounded_words(&[0x00, b'a', b'b', 0x80, 0xff], 3);
        let mut checked = 0usize;
        let mut positive_spans = 0usize;

        for (name, plan, _terminal_initial) in &plans {
            pin_without_start_filter(plan);
            let mut pike = K0Workspace::new(plan, WorkspaceLimits::unlimited()).unwrap();
            let mut endpoint =
                K0Workspace::new_accelerated(plan, WorkspaceLimits::unlimited()).unwrap();
            let mut bidirectional =
                K0Workspace::new_bidirectional(plan, WorkspaceLimits::unlimited()).unwrap();

            for haystack in &haystacks {
                for start in 0..=haystack.len() {
                    for end in start..=haystack.len() {
                        let window = SearchWindow::new(start, end);
                        let want_exists = plan
                            .prepare::<Exists>()
                            .search_window_with_workspace(
                                haystack,
                                window,
                                &mut pike,
                                SearchLimits::unlimited(),
                            )
                            .unwrap();
                        let got_exists = plan
                            .prepare::<Exists>()
                            .search_window_with_workspace(
                                haystack,
                                window,
                                &mut endpoint,
                                SearchLimits::unlimited(),
                            )
                            .unwrap();
                        assert_eq!(
                            got_exists.output(),
                            want_exists.output(),
                            "{name}: Exists source={haystack:?} window={window:?}"
                        );
                        assert_eq!(
                            got_exists.accounting().boundaries(),
                            want_exists.accounting().boundaries(),
                            "{name}: Exists boundary accounting"
                        );

                        let want_earliest = plan
                            .prepare::<EarliestEnd>()
                            .search_window_with_workspace(
                                haystack,
                                window,
                                &mut pike,
                                SearchLimits::unlimited(),
                            )
                            .unwrap();
                        let got_earliest = plan
                            .prepare::<EarliestEnd>()
                            .search_window_with_workspace(
                                haystack,
                                window,
                                &mut endpoint,
                                SearchLimits::unlimited(),
                            )
                            .unwrap();
                        assert_eq!(
                            got_earliest.output(),
                            want_earliest.output(),
                            "{name}: EarliestEnd source={haystack:?} window={window:?}"
                        );
                        assert_eq!(
                            got_earliest.accounting().boundaries(),
                            want_earliest.accounting().boundaries(),
                            "{name}: EarliestEnd boundary accounting"
                        );

                        let want_selected = plan
                            .prepare::<SelectedEnd>()
                            .search_window_with_workspace(
                                haystack,
                                window,
                                &mut pike,
                                SearchLimits::unlimited(),
                            )
                            .unwrap();
                        let got_selected = plan
                            .prepare::<SelectedEnd>()
                            .search_window_with_workspace(
                                haystack,
                                window,
                                &mut endpoint,
                                SearchLimits::unlimited(),
                            )
                            .unwrap();
                        assert_eq!(
                            got_selected.output(),
                            want_selected.output(),
                            "{name}: SelectedEnd source={haystack:?} window={window:?}"
                        );
                        assert_eq!(
                            got_selected.accounting().boundaries(),
                            want_selected.accounting().boundaries(),
                            "{name}: SelectedEnd boundary accounting"
                        );

                        let want_span = plan
                            .prepare::<Span>()
                            .search_window_with_workspace(
                                haystack,
                                window,
                                &mut pike,
                                SearchLimits::unlimited(),
                            )
                            .unwrap();
                        let got_span = plan
                            .prepare::<Span>()
                            .search_window_with_workspace(
                                haystack,
                                window,
                                &mut endpoint,
                                SearchLimits::unlimited(),
                            )
                            .unwrap();
                        let got_full_span = plan
                            .prepare::<Span>()
                            .search_window_with_workspace(
                                haystack,
                                window,
                                &mut bidirectional,
                                SearchLimits::unlimited(),
                            )
                            .unwrap();
                        assert_eq!(
                            got_span.output(),
                            want_span.output(),
                            "{name}: endpoint Span source={haystack:?} window={window:?}"
                        );
                        assert_eq!(
                            got_full_span.output(),
                            want_span.output(),
                            "{name}: full Span source={haystack:?} window={window:?}"
                        );
                        assert_eq!(
                            got_span.accounting().boundaries(),
                            want_span.accounting().boundaries(),
                            "{name}: start-known endpoint Span boundary accounting"
                        );
                        assert_eq!(
                            got_full_span.accounting().boundaries(),
                            want_span.accounting().boundaries(),
                            "{name}: start-known full Span boundary accounting"
                        );
                        if let Some(selected) = want_span.output() {
                            assert_eq!(
                                selected.start(),
                                window.start(),
                                "{name}: nullable selected start proof"
                            );
                            if selected.end() > selected.start() {
                                positive_spans = positive_spans.checked_add(1).unwrap();
                            }
                        }
                        checked = checked.checked_add(1).unwrap();
                    }
                }
            }

            assert!(endpoint.lazy.initialized, "{name}: endpoint initialized");
            assert!(!endpoint.lazy.declined, "{name}: endpoint accepted");
            assert!(
                !endpoint.lazy.saturated,
                "{name}: exhaustive nullable identities fit their proven capacity"
            );
            assert!(endpoint.lazy.state_len <= endpoint.layout.lazy_state_capacity);
            assert!(endpoint.lazy.item_len <= endpoint.layout.lazy_item_capacity);
            assert!(bidirectional.lazy.initialized, "{name}: span initialized");
            assert!(
                !bidirectional.reverse.initialized,
                "{name}: start-known span must not prepare reverse"
            );
            assert!(
                !bidirectional.lazy.declined,
                "{name}: span forward accepted"
            );
            assert!(
                !bidirectional.lazy.saturated,
                "{name}: full-session forward identities fit their proven capacity"
            );
            assert!(bidirectional.lazy.state_len <= bidirectional.layout.lazy_state_capacity);
            assert!(bidirectional.lazy.item_len <= bidirectional.layout.lazy_item_capacity);
        }
        assert!(checked > 10_000);
        assert!(positive_spans > 100);
    }

    #[test]
    fn contextual_assertion_masks_match_the_canonical_edge_evaluator() {
        let mut haystacks = bounded_words(&[0, b'\r', b'\n', b';', b'a', b'_', 0x80], 3);
        haystacks.extend([
            "é".as_bytes().to_vec(),
            "α_".as_bytes().to_vec(),
            vec![0xf0, 0x9f, 0x92, 0xa9],
            vec![0xf0, 0x28, 0x8c, 0xbc],
            vec![0xc3],
            vec![0x80, b'a'],
        ]);
        for kind in super::ASSERTION_KINDS {
            let plan = assertion_or_colon(kind).with_line_terminator(b';');
            let bit = kind.assertion_bit().unwrap();
            assert_eq!(plan.stats().assertion_kinds(), bit);
            for haystack in &haystacks {
                for position in 0..=haystack.len() {
                    let mut meter = WorkMeter::new(u64::MAX, 0);
                    let mask = super::enabled_assertion_mask(&plan, haystack, position, &mut meter)
                        .unwrap();
                    let expected =
                        super::zero_width_edge_enabled(&plan, kind, haystack, position).unwrap();
                    assert_eq!(
                        mask & bit != 0,
                        expected,
                        "mask mismatch kind={kind:?} source={haystack:?} position={position}"
                    );
                    assert_eq!(mask & !bit, 0);
                    assert_eq!(meter.consumed, 1);
                }
            }
        }
    }

    #[test]
    fn ordinary_boundary_strategy_requires_dense_exact_kind_reuse() {
        fn check(assertions: &[EdgeKind], expected: super::OrdinaryPikeBoundaryStrategy) {
            let plan = boundary_strategy_assertions(assertions);
            assert_eq!(super::ordinary_pike_boundary_strategy(&plan), expected);
            assert_eq!(
                super::boundary_fact_reuse_is_profitable(&plan),
                expected == super::OrdinaryPikeBoundaryStrategy::Cached,
            );
        }

        check(&[], super::OrdinaryPikeBoundaryStrategy::AssertionFree);
        check(
            &[EdgeKind::AssertLineStartLf],
            super::OrdinaryPikeBoundaryStrategy::Direct,
        );
        check(
            &[
                EdgeKind::AssertHaystackStart,
                EdgeKind::AssertHaystackEnd,
            ],
            super::OrdinaryPikeBoundaryStrategy::Direct,
        );
        check(
            &[
                EdgeKind::AssertLineStartLf,
                EdgeKind::AssertWordAscii,
            ],
            super::OrdinaryPikeBoundaryStrategy::Direct,
        );
        check(
            &[
                EdgeKind::AssertLineStartLf,
                EdgeKind::AssertLineStartCrlf,
                EdgeKind::AssertWordAscii,
            ],
            super::OrdinaryPikeBoundaryStrategy::Direct,
        );
        check(
            &[
                EdgeKind::AssertHaystackStart,
                EdgeKind::AssertWordUnicode,
            ],
            super::OrdinaryPikeBoundaryStrategy::Direct,
        );
        check(
            &[
                EdgeKind::AssertWordUnicode,
                EdgeKind::AssertWordUnicode,
            ],
            super::OrdinaryPikeBoundaryStrategy::Direct,
        );
        check(
            &[
                EdgeKind::AssertWordUnicode,
                EdgeKind::AssertWordUnicode,
                EdgeKind::AssertWordUnicode,
            ],
            super::OrdinaryPikeBoundaryStrategy::Direct,
        );
        check(
            &[
                EdgeKind::AssertWordUnicode,
                EdgeKind::AssertWordUnicode,
                EdgeKind::AssertWordUnicode,
                EdgeKind::AssertWordUnicode,
            ],
            super::OrdinaryPikeBoundaryStrategy::Cached,
        );
        check(
            &[
                EdgeKind::AssertHaystackStart,
                EdgeKind::AssertHaystackStart,
                EdgeKind::AssertHaystackEnd,
                EdgeKind::AssertWordUnicode,
            ],
            super::OrdinaryPikeBoundaryStrategy::Direct,
        );
        check(
            &[
                EdgeKind::AssertHaystackStart,
                EdgeKind::AssertHaystackStart,
                EdgeKind::AssertHaystackEnd,
                EdgeKind::AssertHaystackEnd,
            ],
            super::OrdinaryPikeBoundaryStrategy::Cached,
        );
    }

