    #[test]
    fn prepared_boundary_observation_prepares_only_requested_families_once() {
        let plan = every_assertion().with_line_terminator(b';');
        let global_dependencies = plan.boundary_context_classifier().assertions();
        let unicode_dependencies = plan.boundary_context_classifier().unicode_word();
        let raw_dependencies = global_dependencies & !unicode_dependencies;
        let haystack = "aβ!".as_bytes();
        let position = 1;
        let mut observation = super::PreparedBoundaryObservation::new(
            plan.line_terminator(),
            haystack,
            position,
            global_dependencies,
        );

        assert_eq!(observation.raw_preparations(), 0);
        assert_eq!(observation.unicode_classifications(), 0);
        assert_eq!(observation.project(0), 0);
        assert_eq!(observation.raw_preparations(), 0);
        assert_eq!(observation.unicode_classifications(), 0);
        assert_eq!(
            observation.project(unicode_dependencies),
            super::enabled_assertion_mask_unmetered_for_dependencies(
                &plan,
                unicode_dependencies,
                haystack,
                position,
            )
        );
        assert_eq!(observation.raw_preparations(), 0);
        assert_eq!(observation.unicode_classifications(), 1);
        assert_eq!(
            observation.project(raw_dependencies),
            super::enabled_assertion_mask_unmetered_for_dependencies(
                &plan,
                raw_dependencies,
                haystack,
                position,
            )
        );
        assert_eq!(observation.raw_preparations(), 1);
        assert_eq!(observation.unicode_classifications(), 1);
        assert_eq!(
            observation.project(raw_dependencies),
            super::enabled_assertion_mask_unmetered_for_dependencies(
                &plan,
                raw_dependencies,
                haystack,
                position,
            )
        );
        assert_eq!(observation.raw_preparations(), 1);
        assert_eq!(observation.unicode_classifications(), 1);
        assert_eq!(
            observation.project(global_dependencies),
            super::enabled_assertion_mask_unmetered_for_dependencies(
                &plan,
                global_dependencies,
                haystack,
                position,
            )
        );
        assert_eq!(observation.raw_preparations(), 1);
        assert_eq!(observation.unicode_classifications(), 1);
    }

    #[test]
    fn warm_dependency_projection_retries_raw_initial_and_transition_keys() {
        let plan = contextual_unicode_word_loop_or_haystack_end();
        let global_dependencies = plan.boundary_context_classifier().assertions();
        let dependencies = EdgeKind::AssertWordUnicode.assertion_bit().unwrap();
        let haystack = b"a";
        let position = 1;
        let mut observation = super::PreparedBoundaryObservation::new(
            plan.line_terminator(),
            haystack,
            position,
            global_dependencies,
        );
        let normalized_assertions = observation.project(dependencies);
        assert_eq!(observation.raw_preparations(), 0);
        assert_eq!(observation.unicode_classifications(), 1);
        let exact_assertions = observation.project(global_dependencies);
        assert_ne!(normalized_assertions, exact_assertions);
        assert_eq!(observation.raw_preparations(), 1);
        assert_eq!(observation.unicode_classifications(), 1);

        let mut workspace =
            K0Workspace::new_accelerated(&plan, WorkspaceLimits::unlimited()).unwrap();
        let initial_value = 1 | super::LAZY_CELL_RESTART;
        publish_context_record(
            &mut workspace.lazy.context,
            super::CONTEXT_INITIAL_SOURCE,
            super::contextual_initial_symbol(exact_assertions),
            initial_value,
        );
        workspace.lazy.context.hot_initial.dependency_mask = dependencies;
        assert_eq!(
            workspace
                .lazy
                .context
                .lookup_existing_prevalidated(
                    super::CONTEXT_INITIAL_SOURCE,
                    super::contextual_initial_symbol(normalized_assertions),
                )
                .unwrap(),
            None
        );
        assert_eq!(
            super::warm_context_initial_state_for_dependencies(
                &plan,
                haystack,
                position,
                &workspace.lazy,
                dependencies,
                global_dependencies,
            )
            .unwrap(),
            Some(0)
        );

        let byte = b'a';
        let transition_value = 1 | super::LAZY_CELL_START_PROPAGATE;
        publish_context_record(
            &mut workspace.lazy.context,
            0,
            super::contextual_symbol_for_byte(&plan, byte, exact_assertions),
            transition_value,
        );
        workspace.lazy.context.hot[0].dependency_mask = dependencies;
        let hot = workspace.lazy.context.hot_transition(0).unwrap();
        assert_eq!(
            workspace
                .lazy
                .context
                .lookup_existing_with_hot_prevalidated(
                    0,
                    hot,
                    super::contextual_symbol_for_byte(&plan, byte, normalized_assertions),
                )
                .unwrap(),
            None
        );
        assert_eq!(
            super::warm_context_transition_for_dependencies(
                &plan,
                haystack,
                position,
                &workspace.lazy,
                0,
                hot,
                byte,
                global_dependencies,
            )
            .unwrap(),
            Some(transition_value)
        );
    }

    #[test]
    fn compiled_context_classifier_matches_every_canonical_assertion_together() {
        fn check(plan: &Automaton, haystack: &[u8], position: usize) {
            let expected = super::ASSERTION_KINDS
                .into_iter()
                .filter(|&kind| {
                    super::zero_width_edge_enabled(plan, kind, haystack, position).unwrap()
                })
                .fold(0_u32, |mask, kind| mask | kind.assertion_bit().unwrap());
            let mut meter = WorkMeter::new(u64::MAX, 0);
            let got = super::enabled_assertion_mask(plan, haystack, position, &mut meter).unwrap();
            assert_eq!(
                got,
                expected,
                "source={haystack:?} position={position} terminator={}",
                plan.line_terminator()
            );
            assert_eq!(
                meter.consumed,
                u64::try_from(super::ASSERTION_KIND_COUNT).unwrap()
            );
        }

        for line_terminator in u8::MIN..=u8::MAX {
            let plan = every_assertion().with_line_terminator(line_terminator);
            let haystacks = [
                vec![],
                vec![line_terminator],
                vec![b'\r', line_terminator, b'\n'],
                vec![line_terminator, b'\r', b'\n', line_terminator],
            ];
            for haystack in haystacks {
                for position in 0..=haystack.len() {
                    check(&plan, &haystack, position);
                }
            }
        }

        let plan = every_assertion().with_line_terminator(b';');
        check(&plan, &[], 0);
        for byte in u8::MIN..=u8::MAX {
            check(&plan, &[byte], 0);
            check(&plan, &[byte], 1);
        }
        for left in u8::MIN..=u8::MAX {
            for right in u8::MIN..=u8::MAX {
                check(&plan, &[left, right], 1);
            }
        }

        let mut haystacks = bounded_words(&[0, b'\r', b'\n', b';', b'a', b'_', 0x80], 3);
        haystacks.extend([
            "é".as_bytes().to_vec(),
            "α_".as_bytes().to_vec(),
            " aβ\u{200C}!".as_bytes().to_vec(),
            vec![0xf0, 0x9f, 0x92, 0xa9],
            vec![0xf0, 0x28, 0x8c, 0xbc],
            vec![0xc3],
            vec![0x80, b'a'],
            vec![b'a', 0xed, 0xa0, 0x80, b'_'],
            vec![0xf4, 0x90, 0x80, 0x80],
        ]);
        for haystack in haystacks {
            for position in 0..=haystack.len() {
                check(&plan, &haystack, position);
            }
        }
    }

    #[test]
    fn compiled_context_classifier_preserves_finite_work_failure_timing() {
        let plan = every_assertion();
        let haystack = b"a_b";
        let checks = u64::try_from(super::ASSERTION_KIND_COUNT).unwrap();
        for limit in 0..checks {
            let mut meter = WorkMeter::new(limit, 0);
            assert_eq!(
                super::enabled_assertion_mask(&plan, haystack, 1, &mut meter),
                Err(SearchError::WorkLimitExceeded {
                    limit,
                    consumed: limit,
                    requested: 1,
                    position: 1,
                })
            );
            assert_eq!(meter.consumed, limit);
        }
        let mut meter = WorkMeter::new(checks, 0);
        super::enabled_assertion_mask(&plan, haystack, 1, &mut meter).unwrap();
        assert_eq!(meter.consumed, checks);
    }

    #[test]
    fn contextual_cache_keys_distinguish_the_same_state_and_byte_by_mask() {
        let kind = EdgeKind::AssertLineEndLf;
        let plan = trailing_assertion_or_bang(kind);
        let mut workspace =
            K0Workspace::new_accelerated(&plan, WorkspaceLimits::unlimited()).unwrap();
        let mut meter = WorkMeter::new(u64::MAX, 0);
        let (state, _) = super::context_lazy_initial(&plan, 0, &mut workspace, &mut meter, 0, 0)
            .unwrap()
            .unwrap();
        let super::LazyState::Cached(source) = state else {
            panic!("unlimited initial state must be retained");
        };
        let bit = kind.assertion_bit().unwrap();
        let disabled_symbol = super::contextual_symbol_for_byte(&plan, b'a', 0);
        let enabled_symbol = super::contextual_symbol_for_byte(&plan, b'a', bit);
        let disabled = super::build_context_lazy_cached_transition(
            &plan,
            source,
            b'a',
            disabled_symbol,
            0,
            &mut workspace,
            &mut meter,
            0,
            1,
        )
        .unwrap();
        let enabled = super::build_context_lazy_cached_transition(
            &plan,
            source,
            b'a',
            enabled_symbol,
            bit,
            &mut workspace,
            &mut meter,
            0,
            1,
        )
        .unwrap();
        let super::ContextLazyTransition::Ready(disabled) = disabled else {
            panic!("unlimited transition must be retained");
        };
        let super::ContextLazyTransition::Ready(enabled) = enabled else {
            panic!("unlimited transition must be retained");
        };
        assert_eq!(disabled & super::LAZY_CELL_ACCEPT, 0);
        assert_ne!(enabled & super::LAZY_CELL_ACCEPT, 0);
        assert!(workspace.lazy.context.slots.iter().any(|slot| {
            slot.source == source && slot.symbol == disabled_symbol && slot.value == disabled
        }));
        assert!(workspace.lazy.context.slots.iter().any(|slot| {
            slot.source == source && slot.symbol == enabled_symbol && slot.value == enabled
        }));
    }

    #[test]
    fn contextual_forward_and_reverse_keys_alias_only_the_same_class_and_mask() {
        let kind = EdgeKind::AssertLineEndLf;
        let bit = kind.assertion_bit().unwrap();
        let plan = trailing_range_assertion_or_bang(kind);
        assert_eq!(byte_class(&plan, b'a'), byte_class(&plan, b'b'));
        assert_ne!(byte_class(&plan, b'a'), byte_class(&plan, b'!'));
        assert_eq!(
            super::contextual_symbol_for_byte(&plan, b'a', bit),
            super::contextual_symbol_for_byte(&plan, b'b', bit)
        );
        assert_ne!(
            super::contextual_symbol_for_byte(&plan, b'a', bit),
            super::contextual_symbol_for_byte(&plan, b'a', 0)
        );
        assert_ne!(
            super::contextual_symbol_for_byte(&plan, b'a', bit),
            super::contextual_symbol_for_byte(&plan, b'!', bit)
        );

        let mut workspace =
            K0Workspace::new_bidirectional(&plan, WorkspaceLimits::unlimited()).unwrap();
        let mut meter = WorkMeter::new(u64::MAX, 0);
        let (forward, _) =
            super::context_lazy_initial(&plan, 0, &mut workspace, &mut meter, 0, 0)
                .unwrap()
                .unwrap();
        let super::LazyState::Cached(forward) = forward else {
            panic!("unlimited contextual forward state must be retained");
        };
        let forward_before = workspace.lazy.context.published;
        let forward_symbol = super::contextual_symbol_for_byte(&plan, b'a', bit);
        let first = super::build_context_lazy_cached_transition(
            &plan,
            forward,
            b'a',
            forward_symbol,
            bit,
            &mut workspace,
            &mut meter,
            0,
            1,
        )
        .unwrap();
        assert_eq!(workspace.lazy.context.published, forward_before + 1);
        let aliased = super::build_context_lazy_cached_transition(
            &plan,
            forward,
            b'b',
            super::contextual_symbol_for_byte(&plan, b'b', bit),
            bit,
            &mut workspace,
            &mut meter,
            0,
            1,
        )
        .unwrap();
        assert_eq!(aliased, first);
        assert_eq!(workspace.lazy.context.published, forward_before + 1);

        let _different_mask = super::build_context_lazy_cached_transition(
            &plan,
            forward,
            b'b',
            super::contextual_symbol_for_byte(&plan, b'b', 0),
            0,
            &mut workspace,
            &mut meter,
            0,
            1,
        )
        .unwrap();
        assert_eq!(workspace.lazy.context.published, forward_before + 2);
        let _different_class = super::build_context_lazy_cached_transition(
            &plan,
            forward,
            b'!',
            super::contextual_symbol_for_byte(&plan, b'!', bit),
            bit,
            &mut workspace,
            &mut meter,
            0,
            1,
        )
        .unwrap();
        assert_eq!(workspace.lazy.context.published, forward_before + 3);

        let reverse = super::context_reverse_initial(
            &plan,
            bit,
            &mut workspace,
            &mut meter,
            0,
            1,
        )
        .unwrap()
        .unwrap();
        let super::ReverseState::Cached(reverse) = reverse else {
            panic!("unlimited contextual reverse state must be retained");
        };
        let reverse_before = workspace.reverse.context.published;
        let reverse_symbol = super::contextual_symbol_for_byte(&plan, b'a', 0);
        let first = super::build_context_reverse_cached_transition(
            &plan,
            reverse,
            b'a',
            reverse_symbol,
            0,
            &mut workspace,
            &mut meter,
            0,
            0,
        )
        .unwrap();
        assert_eq!(workspace.reverse.context.published, reverse_before + 1);
        let reverse_hot =
            workspace.reverse.context.hot[usize::try_from(reverse).unwrap()];
        let super::ReverseTransition::Ready(first_cell) = first else {
            panic!("unlimited contextual reverse transition must be retained");
        };
        assert_eq!(reverse_hot.symbol, reverse_symbol);
        assert_eq!(reverse_hot.value, first_cell);
        let backing = workspace
            .reverse
            .context
            .slots
            .iter()
            .position(|slot| {
                slot.source == reverse
                    && slot.symbol == reverse_symbol
                    && slot.value == first_cell
            })
            .expect("published reverse hot transition must retain associative backing");
        let backing_record = workspace.reverse.context.slots[backing];
        workspace.reverse.context.slots[backing] = super::ContextTransitionSlot::EMPTY;

        let exact_work = u64::from(reverse_hot.lookup_work);
        let mut exact = WorkMeter::new(exact_work, 0);
        let aliased = super::build_context_reverse_cached_transition(
            &plan,
            reverse,
            b'b',
            super::contextual_symbol_for_byte(&plan, b'b', 0),
            0,
            &mut workspace,
            &mut exact,
            0,
            0,
        )
        .unwrap();
        assert_eq!(aliased, first);
        assert_eq!(exact.consumed, exact_work);
        assert_eq!(workspace.reverse.context.published, reverse_before + 1);
        let one_below_limit = exact_work.checked_sub(1).unwrap();
        let mut one_below = WorkMeter::new(one_below_limit, 0);
        assert!(matches!(
            super::build_context_reverse_cached_transition(
                &plan,
                reverse,
                b'b',
                super::contextual_symbol_for_byte(&plan, b'b', 0),
                0,
                &mut workspace,
                &mut one_below,
                0,
                0,
            ),
            Err(SearchError::WorkLimitExceeded {
                limit,
                consumed: 0,
                requested,
                position: 0,
            }) if limit == one_below_limit && requested == exact_work
        ));
        workspace.reverse.context.slots[backing] = backing_record;

        let _different_mask = super::build_context_reverse_cached_transition(
            &plan,
            reverse,
            b'b',
            super::contextual_symbol_for_byte(&plan, b'b', bit),
            bit,
            &mut workspace,
            &mut meter,
            0,
            0,
        )
        .unwrap();
        assert_eq!(workspace.reverse.context.published, reverse_before + 2);
        let _different_class = super::build_context_reverse_cached_transition(
            &plan,
            reverse,
            b'!',
            super::contextual_symbol_for_byte(&plan, b'!', 0),
            0,
            &mut workspace,
            &mut meter,
            0,
            0,
        )
        .unwrap();
        assert_eq!(workspace.reverse.context.published, reverse_before + 3);
    }

    #[test]
    fn contextual_class_255_remains_distinct_from_the_initial_sentinel() {
        let bytes: Vec<_> = (u8::MIN..=u8::MAX).collect();
        let plan = ascii_root_bytes(&bytes);
        assert_eq!(plan.byte_classes().count(), super::BYTE_ALPHABET);
        let class = byte_class(&plan, u8::MAX);
        assert_eq!(class, u8::MAX);
        let assertions = EdgeKind::AssertLineEndLf.assertion_bit().unwrap();
        let transition = super::contextual_class_symbol(class, assertions);
        let initial = super::contextual_initial_symbol(assertions);
        assert_eq!(transition & super::CONTEXT_SYMBOL_CLASS_MASK, u32::from(u8::MAX));
        assert_eq!(initial & super::CONTEXT_SYMBOL_CLASS_MASK, super::CONTEXT_INITIAL_CLASS);
        assert_ne!(transition, initial);
    }

    #[test]
    fn contextual_loop_derivation_decodes_a_real_member_of_a_cross_category_class() {
        let plan = full_byte_contextual_word_loop();
        assert_eq!(plan.byte_classes().count(), 1);
        assert_eq!(plan.byte_classes().representative(0), Some(0));
        let dependencies = plan.boundary_context_classifier().assertions();
        let word_assertions = super::enabled_assertion_mask_unmetered_for_dependencies(
            &plan,
            dependencies,
            b"aa",
            1,
        );
        let raw_representative_assertions =
            super::enabled_assertion_mask_unmetered_for_dependencies(
                &plan,
                dependencies,
                &[0, 0],
                1,
            );
        assert_ne!(word_assertions, raw_representative_assertions);

        let mut workspace =
            K0Workspace::new_accelerated(&plan, WorkspaceLimits::unlimited()).unwrap();
        let mut meter = WorkMeter::new(u64::MAX, 0);
        workspace.lazy.scratch[0] = 0;
        workspace.lazy.scratch_len = 1;
        assert_eq!(workspace.lazy.intern_initial(false, &mut meter, 0).unwrap(), 0);
        workspace
            .lazy
            .context
            .publish(
                Some(0),
                ContextTransitionSlot::populated(
                    0,
                    super::contextual_symbol_for_byte(&plan, b'a', word_assertions),
                    1 | super::LazyStartAction::Propagate.cell_bits(),
                ),
                &mut meter,
                0,
                0,
            )
            .unwrap();
        workspace.lazy.context.hot[0].dependency_mask = dependencies;
        workspace.lazy.context_dependencies_analyzed = 1;
        super::try_derive_context_lazy_loop_skip(&plan, &mut workspace, &mut meter).unwrap();
        let retained = workspace
            .lazy
            .context_loop_skip_plans
            .first()
            .expect("the class must be decoded through its word-category member");
        assert!(retained.scanner.contains(b'a'));
        assert!(retained.scanner.contains(b'_'));
        assert!(!retained.scanner.contains(0));
        assert!(!retained.scanner.contains(b'!'));
    }

    #[test]
    fn contextual_pair_closed_union_covers_every_ordered_word_pair_and_drop_action() {
        let plan = full_byte_contextual_word_loop();
        let representatives = [b'a', b'!'];
        for action in [
            super::LazyStartAction::Propagate,
            super::LazyStartAction::Drop,
        ] {
            let mut workspace = contextual_pair_loop_workspace(
                &plan,
                &representatives,
                &representatives,
                action,
                None,
            );
            let published = workspace.lazy.context.published;
            let mut meter = WorkMeter::new(u64::MAX, 0);
            super::try_derive_context_lazy_loop_skip(&plan, &mut workspace, &mut meter).unwrap();
            let retained = workspace
                .lazy
                .context_loop_skip_plans
                .first()
                .expect("the complete ordered-pair matrix must retain its union");
            assert_eq!(retained.start_action, action);
            assert!(retained.leave_final_member);
            assert_eq!(retained.scanner.cardinality(), 256);
            assert!(matches!(retained.scanner, super::LazyLoopScanner::All));
            assert_eq!(workspace.lazy.context.published, published);

            let dependencies = plan.boundary_context_classifier().assertions();
            let value = 1 | action.cell_bits();
            for left in u8::MIN..=u8::MAX {
                for right in u8::MIN..=u8::MAX {
                    let assertions =
                        super::enabled_assertion_mask_unmetered_for_dependencies(
                            &plan,
                            dependencies,
                            &[left, right],
                            1,
                        );
                    let symbol =
                        super::contextual_symbol_for_byte(&plan, left, assertions);
                    assert_eq!(
                        workspace
                            .lazy
                            .context
                            .lookup_existing_prevalidated(0, symbol)
                            .unwrap(),
                        Some(value),
                        "action={action:?} left={left:#04x} right={right:#04x}"
                    );
                }
            }
        }
    }

    #[test]
    fn contextual_pair_closed_union_rejects_one_missing_cross_category_record() {
        let plan = full_byte_contextual_word_loop();
        let representatives = [b'a', b'!'];
        let mut workspace = contextual_pair_loop_workspace(
            &plan,
            &representatives,
            &representatives,
            super::LazyStartAction::Propagate,
            Some((b'a', b'!')),
        );
        let published = workspace.lazy.context.published;
        let mut meter = WorkMeter::new(u64::MAX, 0);
        super::try_derive_context_lazy_loop_skip(&plan, &mut workspace, &mut meter).unwrap();
        let retained = workspace
            .lazy
            .context_loop_skip_plans
            .first()
            .expect("a complete diagonal category still retains the original narrow proof");
        assert_eq!(retained.scanner.cardinality(), 193);
        assert!(retained.scanner.contains(b'!'));
        assert!(!retained.scanner.contains(b'a'));
        assert_eq!(workspace.lazy.context.published, published);
    }

    #[test]
    fn contextual_pair_closed_union_rejects_one_different_cross_category_value() {
        let plan = full_byte_contextual_word_loop();
        let representatives = [b'a', b'!'];
        let mut workspace = contextual_pair_loop_workspace(
            &plan,
            &representatives,
            &representatives,
            super::LazyStartAction::Propagate,
            None,
        );
        let dependencies = plan.boundary_context_classifier().assertions();
        let assertions = super::enabled_assertion_mask_unmetered_for_dependencies(
            &plan,
            dependencies,
            b"a!",
            1,
        );
        let symbol = super::contextual_symbol_for_byte(&plan, b'a', assertions);
        let different = 1 | super::LazyStartAction::Drop.cell_bits();
        let slot = workspace
            .lazy
            .context
            .slots
            .iter_mut()
            .find(|slot| slot.source == 0 && slot.symbol == symbol)
            .expect("the complete matrix must retain the word-to-nonword key");
        slot.value = different;
        if workspace.lazy.context.hot[0].symbol == symbol {
            workspace.lazy.context.hot[0].value = different;
        }

        let published = workspace.lazy.context.published;
        let mut meter = WorkMeter::new(u64::MAX, 0);
        super::try_derive_context_lazy_loop_skip(&plan, &mut workspace, &mut meter).unwrap();
        let retained = workspace
            .lazy
            .context_loop_skip_plans
            .first()
            .expect("the unchanged nonword diagonal still retains a narrow proof");
        assert_eq!(retained.start_action, super::LazyStartAction::Propagate);
        assert_eq!(retained.scanner.cardinality(), 193);
        assert!(retained.scanner.contains(b'!'));
        assert!(!retained.scanner.contains(b'a'));
        assert_eq!(workspace.lazy.context.published, published);
    }

