    #[test]
    fn span_cursor_recomputes_nullable_start_known_mode_after_initialization() {
        let plan = empty_or_ab(false);
        plan.start_filter_proof
            .set(&StartFilterProof {
                scanner: None,
                filter: None,
                force_haystack_start: false,
                relaxed_nullable: true,
            })
            .expect("fresh nullable automaton");
        let limits = SearchLimits::unlimited();

        let mut endpoint =
            K0Workspace::new_accelerated(&plan, WorkspaceLimits::unlimited()).unwrap();
        let endpoint_cursor = super::prepare_span_cursor(&plan, &mut endpoint, limits).unwrap();
        assert!(endpoint_cursor.capabilities.lazy);
        assert!(!endpoint_cursor.capabilities.reverse);
        assert_eq!(
            super::effective_lazy_mode(&plan, &endpoint, true, endpoint_cursor.capabilities,)
                .unwrap(),
            super::EffectiveLazyMode {
                lazy: true,
                reverse: false,
            }
        );
        let endpoint_report =
            super::search_span_with_workspace_cursor(&plan, b"abxx", 0, &mut endpoint, limits)
                .unwrap();
        assert_eq!(endpoint_report.found, Some(MatchSpan::new(0, 2)));
        assert!(endpoint.lazy.initialized);
        assert!(super::lazy_initial_has_pending(&endpoint).unwrap());

        let mut full = K0Workspace::new_bidirectional(&plan, WorkspaceLimits::unlimited()).unwrap();
        let cold_cursor = super::prepare_span_cursor(&plan, &mut full, limits).unwrap();
        assert!(cold_cursor.capabilities.lazy);
        assert!(cold_cursor.capabilities.reverse);
        assert_eq!(
            super::effective_lazy_mode(&plan, &full, true, cold_cursor.capabilities).unwrap(),
            super::EffectiveLazyMode {
                lazy: true,
                reverse: true,
            }
        );
        let full_report =
            super::search_span_with_workspace_cursor(&plan, b"abxx", 0, &mut full, limits).unwrap();
        assert_eq!(full_report.found, Some(MatchSpan::new(0, 2)));
        assert!(full.lazy.initialized);
        assert!(!full.reverse.initialized);

        let warm_cursor = super::prepare_span_cursor(&plan, &mut full, limits).unwrap();
        assert_eq!(warm_cursor.capabilities, cold_cursor.capabilities);
        assert_eq!(
            super::effective_lazy_mode(&plan, &full, true, warm_cursor.capabilities).unwrap(),
            super::EffectiveLazyMode {
                lazy: true,
                reverse: false,
            }
        );
        let warm_report =
            super::search_span_with_workspace_cursor(&plan, b"xxab", 2, &mut full, limits).unwrap();
        assert_eq!(warm_report.found, Some(MatchSpan::new(2, 4)));
        assert!(!full.reverse.initialized);
    }

    #[test]
    fn transient_learning_budget_refusal_preserves_cached_rows_and_can_retry() {
        let plan = a_plus(true);
        let certified = plan.conservative_reused_work_bound(2).unwrap();
        let mut fresh = K0Workspace::new_accelerated(&plan, WorkspaceLimits::unlimited()).unwrap();
        let fresh_retained = fresh.retained_bytes();
        let certified_report = plan
            .prepare::<SelectedEnd>()
            .search_with_workspace(
                b"aa",
                &mut fresh,
                SearchLimits {
                    max_work: certified,
                    max_scratch_bytes: fresh_retained,
                },
            )
            .unwrap();
        assert_eq!(certified_report.output(), &Some(2));
        assert!(certified_report.accounting().work() <= certified);
        assert!(
            !fresh.lazy.initialized,
            "a fresh cache must leave the ordinary certificate reserved"
        );

        let mut workspace =
            K0Workspace::new_accelerated(&plan, WorkspaceLimits::unlimited()).unwrap();

        assert_eq!(
            plan.prepare::<SelectedEnd>()
                .search_with_workspace(b"a", &mut workspace, SearchLimits::unlimited())
                .unwrap()
                .into_output(),
            Some(1)
        );
        let initial = workspace.lazy.initial;
        let class = byte_class(&plan, b'a');
        let pending = workspace.lazy.cell(initial, class).unwrap() & super::LAZY_CELL_STATE_MASK;
        let pending = workspace.lazy.row_state(pending.checked_sub(1).unwrap());
        assert_eq!(
            workspace.lazy.cell(pending, class).unwrap(),
            super::LAZY_CELL_UNFILLED
        );

        let retained = workspace.retained_bytes();
        assert_eq!(
            plan.prepare::<SelectedEnd>()
                .search_with_workspace(
                    b"aa",
                    &mut workspace,
                    SearchLimits {
                        max_work: certified,
                        max_scratch_bytes: retained,
                    },
                )
                .unwrap()
                .into_output(),
            Some(2)
        );
        assert!(!workspace.lazy.saturated);
        assert_eq!(
            workspace.lazy.cell(pending, class).unwrap(),
            super::LAZY_CELL_UNFILLED,
            "a bound-certified call must decline optional learning"
        );

        assert_eq!(
            plan.prepare::<SelectedEnd>()
                .search_with_workspace(b"aa", &mut workspace, SearchLimits::unlimited())
                .unwrap()
                .into_output(),
            Some(2)
        );
        assert_ne!(
            workspace.lazy.cell(pending, class).unwrap(),
            super::LAZY_CELL_UNFILLED,
            "a later call with surplus work must retry and publish the row"
        );
    }

    #[test]
    fn warmed_lazy_rows_remove_repeated_dense_pike_closure_work() {
        let plan = a_plus(true);
        let haystack = vec![b'a'; 4_096];
        let mut pike = K0Workspace::new(&plan, WorkspaceLimits::unlimited()).unwrap();
        let mut accelerated =
            K0Workspace::new_accelerated(&plan, WorkspaceLimits::unlimited()).unwrap();

        let _ = plan
            .prepare::<SelectedEnd>()
            .search_with_workspace(&haystack, &mut accelerated, SearchLimits::unlimited())
            .unwrap();
        let pike = plan
            .prepare::<SelectedEnd>()
            .search_with_workspace(&haystack, &mut pike, SearchLimits::unlimited())
            .unwrap();
        let accelerated = plan
            .prepare::<SelectedEnd>()
            .search_with_workspace(&haystack, &mut accelerated, SearchLimits::unlimited())
            .unwrap();
        assert_eq!(accelerated.output(), pike.output());
        assert!(
            accelerated.accounting().transition_work() * 2 < pike.accounting().transition_work(),
            "warmed rows should replace repeated ordered closure"
        );
    }

    #[test]
    fn authenticated_direct_row_offsets_keep_physical_bounds_checked() {
        let plan = a_plus(true);
        let mut forward =
            K0Workspace::new_accelerated(&plan, WorkspaceLimits::unlimited()).unwrap();
        plan.prepare::<SelectedEnd>()
            .search_with_workspace(b"aa", &mut forward, SearchLimits::unlimited())
            .unwrap();
        let forward_initial = forward.lazy.initial;
        assert!(forward.lazy.state_len > 0);
        let forward_outside = u32::try_from(forward.lazy.state_len).unwrap();
        assert_eq!(
            forward.lazy.cell(forward_outside, b'a').unwrap_err(),
            SearchError::InternalInvariant {
                detail: "lazy DFA transition state is outside the cache",
            }
        );
        let forward_row = forward.lazy.row_offset(forward_initial).unwrap();
        forward.lazy.rows.clear();
        assert_eq!(
            forward
                .lazy
                .direct_cell(forward_row, byte_class(&plan, b'a'))
                .unwrap_err(),
            SearchError::InternalInvariant {
                detail: "lazy DFA transition cell is outside the direct table",
            }
        );

        let mut reverse =
            K0Workspace::new_bidirectional(&plan, WorkspaceLimits::unlimited()).unwrap();
        plan.prepare::<Span>()
            .search_with_workspace(b"aa", &mut reverse, SearchLimits::unlimited())
            .unwrap();
        let reverse_initial = reverse.reverse.initial;
        assert!(reverse.reverse.state_len > 0);
        let reverse_outside = u32::try_from(reverse.reverse.state_len).unwrap();
        assert_eq!(
            reverse.reverse.cell(reverse_outside, b'a').unwrap_err(),
            SearchError::InternalInvariant {
                detail: "reverse DFA transition state is outside the cache",
            }
        );
        let reverse_row = reverse.reverse.row_offset(reverse_initial).unwrap();
        reverse.reverse.rows.clear();
        assert_eq!(
            reverse
                .reverse
                .direct_cell(reverse_row, byte_class(&plan, b'a'))
                .unwrap_err(),
            SearchError::InternalInvariant {
                detail: "reverse DFA transition cell is outside the direct table",
            }
        );
    }

    #[test]
    fn accelerated_workspace_limits_and_optional_preparation_are_pre_source_exact() {
        let plan = a_plus(true);
        let layout = plan.accelerated_workspace_layout().unwrap();
        let setup_error = K0Workspace::new_accelerated(
            &plan,
            WorkspaceLimits {
                max_setup_work: layout.construction_work() - 1,
                max_scratch_bytes: usize::MAX,
            },
        )
        .unwrap_err();
        assert_eq!(
            setup_error,
            SearchError::WorkspaceSetupWorkLimitExceeded {
                limit: layout.construction_work() - 1,
                needed: layout.construction_work(),
            }
        );
        let scratch_error = K0Workspace::new_accelerated(
            &plan,
            WorkspaceLimits {
                max_setup_work: u64::MAX,
                max_scratch_bytes: layout.logical_bytes() - 1,
            },
        )
        .unwrap_err();
        assert!(matches!(
            scratch_error,
            SearchError::ResourceLimit {
                resource: ResourceKind::ScratchBytes,
                needed,
                limit,
            } if needed == layout.logical_bytes() && limit == layout.logical_bytes() - 1
        ));

        let mut workspace =
            K0Workspace::new_accelerated(&plan, WorkspaceLimits::unlimited()).unwrap();
        pin_without_start_filter(&plan);
        let states = u64::try_from(plan.stats().states()).unwrap();
        let epsilon = u64::try_from(plan.stats().zero_width_edges()).unwrap();
        let initial_upper = states * 2 + epsilon * 2 + 2;
        let limits = SearchLimits {
            max_work: INVOCATION_RESET_WORK + initial_upper - 1,
            max_scratch_bytes: workspace.retained_bytes(),
        };
        let mut setup = crate::SetupAccounting::empty(workspace.retained_bytes(), true);
        let (mut meter, _) = super::prepare_invocation(
            &plan,
            &mut workspace,
            SearchWindow::new(0, 4),
            limits,
            &mut setup,
            true,
            false,
        )
        .unwrap();
        assert!(!super::prepare_lazy(&plan, &mut workspace, &mut meter, 0, 0).unwrap());
        assert_eq!(meter.consumed, INVOCATION_RESET_WORK);
        assert!(!workspace.lazy.initialized);
        assert!(!workspace.lazy.declined);
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "all accelerated endpoint contracts share the same exact-limit matrix"
    )]
    fn warmed_lazy_contracts_enforce_exact_and_one_below_work_limits() {
        let plan = a_plus(true);
        let haystack = b"baaaaa";
        let mut workspace =
            K0Workspace::new_accelerated(&plan, WorkspaceLimits::unlimited()).unwrap();
        let retained = workspace.retained_bytes();

        let _ = plan
            .prepare::<SelectedEnd>()
            .search_with_workspace(haystack, &mut workspace, SearchLimits::unlimited())
            .unwrap();

        let exists_work = plan
            .prepare::<Exists>()
            .search_with_workspace(haystack, &mut workspace, SearchLimits::unlimited())
            .unwrap()
            .accounting()
            .work();
        assert!(plan
            .prepare::<Exists>()
            .search_with_workspace(
                haystack,
                &mut workspace,
                SearchLimits {
                    max_work: exists_work,
                    max_scratch_bytes: retained,
                },
            )
            .unwrap()
            .into_output());
        assert!(matches!(
            plan.prepare::<Exists>().search_with_workspace(
                haystack,
                &mut workspace,
                SearchLimits {
                    max_work: exists_work - 1,
                    max_scratch_bytes: retained,
                },
            ),
            Err(SearchError::WorkLimitExceeded { limit, .. }) if limit == exists_work - 1
        ));

        let earliest_work = plan
            .prepare::<EarliestEnd>()
            .search_with_workspace(haystack, &mut workspace, SearchLimits::unlimited())
            .unwrap()
            .accounting()
            .work();
        assert_eq!(
            plan.prepare::<EarliestEnd>()
                .search_with_workspace(
                    haystack,
                    &mut workspace,
                    SearchLimits {
                        max_work: earliest_work,
                        max_scratch_bytes: retained,
                    },
                )
                .unwrap()
                .into_output(),
            Some(2)
        );
        assert!(matches!(
            plan.prepare::<EarliestEnd>().search_with_workspace(
                haystack,
                &mut workspace,
                SearchLimits {
                    max_work: earliest_work - 1,
                    max_scratch_bytes: retained,
                },
            ),
            Err(SearchError::WorkLimitExceeded { limit, .. }) if limit == earliest_work - 1
        ));

        let selected_work = plan
            .prepare::<SelectedEnd>()
            .search_with_workspace(haystack, &mut workspace, SearchLimits::unlimited())
            .unwrap()
            .accounting()
            .work();
        assert_eq!(
            plan.prepare::<SelectedEnd>()
                .search_with_workspace(
                    haystack,
                    &mut workspace,
                    SearchLimits {
                        max_work: selected_work,
                        max_scratch_bytes: retained,
                    },
                )
                .unwrap()
                .into_output(),
            Some(haystack.len())
        );
        assert!(matches!(
            plan.prepare::<SelectedEnd>().search_with_workspace(
                haystack,
                &mut workspace,
                SearchLimits {
                    max_work: selected_work - 1,
                    max_scratch_bytes: retained,
                },
            ),
            Err(SearchError::WorkLimitExceeded { limit, .. }) if limit == selected_work - 1
        ));

        assert!(matches!(
            plan.prepare::<SelectedEnd>().search_with_workspace(
                haystack,
                &mut workspace,
                SearchLimits {
                    max_work: u64::MAX,
                    max_scratch_bytes: retained - 1,
                },
            ),
            Err(SearchError::ResourceLimit {
                resource: ResourceKind::ScratchBytes,
                needed,
                limit,
            }) if needed == retained && limit == retained - 1
        ));
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "all four nullable contracts need independent exact and one-below ledgers"
    )]
    fn warmed_nullable_lazy_contracts_enforce_exact_limits_and_pike_fallback_accounting() {
        let plan = a_star(true);
        pin_without_start_filter(&plan);
        let haystack = b"aaaa";
        let mut endpoint =
            K0Workspace::new_accelerated(&plan, WorkspaceLimits::unlimited()).unwrap();
        let mut span = K0Workspace::new_accelerated(&plan, WorkspaceLimits::unlimited()).unwrap();
        let endpoint_retained = endpoint.retained_bytes();
        let span_retained = span.retained_bytes();

        let _ = plan
            .prepare::<SelectedEnd>()
            .search_with_workspace(haystack, &mut endpoint, SearchLimits::unlimited())
            .unwrap();
        let _ = plan
            .prepare::<Span>()
            .search_with_workspace(haystack, &mut span, SearchLimits::unlimited())
            .unwrap();

        let exists_work = plan
            .prepare::<Exists>()
            .search_with_workspace(haystack, &mut endpoint, SearchLimits::unlimited())
            .unwrap()
            .accounting()
            .work();
        assert!(plan
            .prepare::<Exists>()
            .search_with_workspace(
                haystack,
                &mut endpoint,
                SearchLimits {
                    max_work: exists_work,
                    max_scratch_bytes: endpoint_retained,
                },
            )
            .unwrap()
            .into_output());
        assert!(matches!(
            plan.prepare::<Exists>().search_with_workspace(
                haystack,
                &mut endpoint,
                SearchLimits {
                    max_work: exists_work - 1,
                    max_scratch_bytes: endpoint_retained,
                },
            ),
            Err(SearchError::WorkLimitExceeded { limit, .. }) if limit == exists_work - 1
        ));

        let earliest_work = plan
            .prepare::<EarliestEnd>()
            .search_with_workspace(haystack, &mut endpoint, SearchLimits::unlimited())
            .unwrap()
            .accounting()
            .work();
        assert_eq!(
            plan.prepare::<EarliestEnd>()
                .search_with_workspace(
                    haystack,
                    &mut endpoint,
                    SearchLimits {
                        max_work: earliest_work,
                        max_scratch_bytes: endpoint_retained,
                    },
                )
                .unwrap()
                .into_output(),
            Some(0)
        );
        assert!(matches!(
            plan.prepare::<EarliestEnd>().search_with_workspace(
                haystack,
                &mut endpoint,
                SearchLimits {
                    max_work: earliest_work - 1,
                    max_scratch_bytes: endpoint_retained,
                },
            ),
            Err(SearchError::WorkLimitExceeded { limit, .. }) if limit == earliest_work - 1
        ));

        let selected_work = plan
            .prepare::<SelectedEnd>()
            .search_with_workspace(haystack, &mut endpoint, SearchLimits::unlimited())
            .unwrap()
            .accounting()
            .work();
        assert_eq!(
            plan.prepare::<SelectedEnd>()
                .search_with_workspace(
                    haystack,
                    &mut endpoint,
                    SearchLimits {
                        max_work: selected_work,
                        max_scratch_bytes: endpoint_retained,
                    },
                )
                .unwrap()
                .into_output(),
            Some(haystack.len())
        );
        assert!(matches!(
            plan.prepare::<SelectedEnd>().search_with_workspace(
                haystack,
                &mut endpoint,
                SearchLimits {
                    max_work: selected_work - 1,
                    max_scratch_bytes: endpoint_retained,
                },
            ),
            Err(SearchError::WorkLimitExceeded { limit, .. }) if limit == selected_work - 1
        ));

        let span_work = plan
            .prepare::<Span>()
            .search_with_workspace(haystack, &mut span, SearchLimits::unlimited())
            .unwrap()
            .accounting()
            .work();
        assert_eq!(
            plan.prepare::<Span>()
                .search_with_workspace(
                    haystack,
                    &mut span,
                    SearchLimits {
                        max_work: span_work,
                        max_scratch_bytes: span_retained,
                    },
                )
                .unwrap()
                .into_output(),
            Some(MatchSpan::new(0, haystack.len()))
        );
        assert!(matches!(
            plan.prepare::<Span>().search_with_workspace(
                haystack,
                &mut span,
                SearchLimits {
                    max_work: span_work - 1,
                    max_scratch_bytes: span_retained,
                },
            ),
            Err(SearchError::WorkLimitExceeded { limit, .. }) if limit == span_work - 1
        ));
        assert!(matches!(
            plan.prepare::<Span>().search_with_workspace(
                haystack,
                &mut span,
                SearchLimits {
                    max_work: u64::MAX,
                    max_scratch_bytes: span_retained - 1,
                },
            ),
            Err(SearchError::ResourceLimit {
                resource: ResourceKind::ScratchBytes,
                needed,
                limit,
            }) if needed == span_retained && limit == span_retained - 1
        ));

        let fallback_plan = empty_or_ab(false);
        pin_without_start_filter(&fallback_plan);
        let fallback_haystack = b"ab";
        let mut pike = K0Workspace::new(&fallback_plan, WorkspaceLimits::unlimited()).unwrap();
        let pike_report = fallback_plan
            .prepare::<SelectedEnd>()
            .search_with_workspace(fallback_haystack, &mut pike, SearchLimits::unlimited())
            .unwrap();
        let certificate = fallback_plan
            .conservative_reused_work_bound(fallback_haystack.len())
            .unwrap();
        let mut fresh =
            K0Workspace::new_accelerated(&fallback_plan, WorkspaceLimits::unlimited()).unwrap();
        let fresh_retained = fresh.retained_bytes();
        let fallback = fallback_plan
            .prepare::<SelectedEnd>()
            .search_with_workspace(
                fallback_haystack,
                &mut fresh,
                SearchLimits {
                    max_work: certificate,
                    max_scratch_bytes: fresh_retained,
                },
            )
            .unwrap();
        assert_eq!(fallback.output(), pike_report.output());
        assert_eq!(
            fallback.accounting().transition_work(),
            pike_report.accounting().transition_work()
        );
        assert_eq!(
            fallback.accounting().boundaries(),
            pike_report.accounting().boundaries()
        );
        assert!(!fresh.lazy.initialized);
        assert!(!fresh.lazy.declined);

        let terminal = a_star(false);
        pin_without_start_filter(&terminal);
        let mut terminal_span =
            K0Workspace::new_bidirectional(&terminal, WorkspaceLimits::unlimited()).unwrap();
        let _ = terminal
            .prepare::<Span>()
            .search_with_workspace(haystack, &mut terminal_span, SearchLimits::unlimited())
            .unwrap();
        let warm = terminal
            .prepare::<Span>()
            .search_with_workspace(haystack, &mut terminal_span, SearchLimits::unlimited())
            .unwrap();
        assert_eq!(warm.output(), &Some(MatchSpan::new(0, 0)));
        assert_eq!(warm.accounting().boundaries(), 1);
        assert!(!terminal_span.reverse.initialized);
        let terminal_retained = terminal_span.retained_bytes();
        let exact = terminal
            .prepare::<Span>()
            .search_with_workspace(
                haystack,
                &mut terminal_span,
                SearchLimits {
                    max_work: warm.accounting().work(),
                    max_scratch_bytes: terminal_retained,
                },
            )
            .unwrap();
        assert_eq!(exact.output(), warm.output());
        assert!(matches!(
            terminal.prepare::<Span>().search_with_workspace(
                haystack,
                &mut terminal_span,
                SearchLimits {
                    max_work: warm.accounting().work() - 1,
                    max_scratch_bytes: terminal_retained,
                },
            ),
            Err(SearchError::WorkLimitExceeded { .. })
        ));
    }

    #[test]
    fn lazy_cache_is_bound_to_the_exact_immutable_automaton() {
        let first = byte_chain(&[(b'a', b'a'), (b'b', b'b')]);
        let second = byte_chain(&[(b'a', b'a'), (b'c', b'c')]);
        assert_eq!(first.workspace_layout(), second.workspace_layout());
        let mut workspace =
            K0Workspace::new_accelerated(&first, WorkspaceLimits::unlimited()).unwrap();

        assert_eq!(
            second
                .prepare::<SelectedEnd>()
                .search_with_workspace(b"zac", &mut workspace, SearchLimits::unlimited())
                .unwrap()
                .into_output(),
            Some(3)
        );
        assert!(!workspace.lazy.initialized);
        assert!(workspace.lazy.is_bound_to(&first));

        assert_eq!(
            first
                .prepare::<SelectedEnd>()
                .search_with_workspace(b"zab", &mut workspace, SearchLimits::unlimited())
                .unwrap()
                .into_output(),
            Some(3)
        );
        assert!(workspace.lazy.initialized);

        let state_len = workspace.lazy.state_len;
        let item_len = workspace.lazy.item_len;
        let offsets = workspace.lazy.offsets.clone();
        let lengths = workspace.lazy.lengths.clone();
        let modes = workspace.lazy.modes.clone();
        let hashes = workspace.lazy.hashes.clone();
        let index = workspace.lazy.index.clone();
        let items = workspace.lazy.items.clone();
        assert_eq!(
            second
                .prepare::<SelectedEnd>()
                .search_with_workspace(b"zac", &mut workspace, SearchLimits::unlimited())
                .unwrap()
                .into_output(),
            Some(3)
        );
        assert!(workspace.lazy.is_bound_to(&first));
        assert!(!workspace.lazy.is_bound_to(&second));
        assert_eq!(workspace.lazy.state_len, state_len);
        assert_eq!(workspace.lazy.item_len, item_len);
        assert_eq!(workspace.lazy.offsets, offsets);
        assert_eq!(workspace.lazy.lengths, lengths);
        assert_eq!(workspace.lazy.modes, modes);
        assert_eq!(workspace.lazy.hashes, hashes);
        assert_eq!(workspace.lazy.index, index);
        assert_eq!(workspace.lazy.items, items);
    }

    #[test]
    fn warm_proved_start_end_matches_exact_execution_across_plans_and_windows() {
        let plans = [
            byte_chain(&[(b'a', b'a'), (b'b', b'b')]),
            ordered_ab_or_ac(),
            ordered_a_or_ab(true),
            ordered_a_or_ab(false),
            greedy_a_star_b(),
            lazy_a_star_b(),
            a_plus(true),
            a_plus(false),
            empty_or_ab(true),
            empty_or_ab(false),
            asserted_line_a(),
        ];
        let haystacks = bounded_words(b"abcx", 3);
        let mut comparisons = 0usize;
        let mut direct = 0usize;

        for plan in &plans {
            let mut session =
                K0SearchSession::new_selected(plan, WorkspaceLimits::unlimited(), true, true)
                    .unwrap();
            for haystack in &haystacks {
                for start in 0..=haystack.len() {
                    for end in start..=haystack.len() {
                        let window = SearchWindow::new(start, end);
                        let exact = super::search_prevalidated_exact_start_with_authenticated_workspace(
                            plan,
                            haystack,
                            window,
                            &mut session.workspace,
                            SearchLimits::unlimited(),
                            OutputContract::SelectedEnd,
                        )
                        .unwrap()
                        .found
                        .map(MatchSpan::end);
                        let Some(expected) = exact else {
                            continue;
                        };
                        let reported = super::search_prevalidated_proved_exact_start_with_authenticated_workspace(
                            plan,
                            haystack,
                            window,
                            &mut session.workspace,
                            SearchLimits::unlimited(),
                            OutputContract::SelectedEnd,
                        )
                        .unwrap()
                        .found
                        .map(MatchSpan::end);
                        assert_eq!(reported, Some(expected));

                        let optimistic = if plan.stats().assertion_edges() == 0 {
                            super::try_warm_proved_start_selected_end(
                                plan,
                                haystack,
                                window,
                                &session.workspace.lazy,
                            )
                            .unwrap()
                        } else {
                            None
                        };
                        let rows = session.workspace.lazy.rows.clone();
                        let generation = session.workspace.generation;
                        let actual = plan
                            .prepare::<SelectedEnd>()
                            .search_prevalidated_proved_exact_start_selected_end_value_with_authenticated_workspace(
                                haystack,
                                window,
                                &mut session.workspace,
                                SearchLimits::unlimited(),
                            )
                            .unwrap();
                        assert_eq!(actual, Some(expected));
                        if optimistic.is_some() {
                            assert_eq!(optimistic, Some(expected));
                            assert_eq!(session.workspace.lazy.rows, rows);
                            assert_eq!(session.workspace.generation, generation);
                            direct = direct.saturating_add(1);
                        }
                        comparisons = comparisons.saturating_add(1);
                    }
                }
            }
        }
        assert!(comparisons > 500);
        assert!(direct > 250);
    }

    #[test]
    fn warm_proved_start_end_is_read_only_and_declines_to_ordinary_limits() {
        let plan = byte_chain(&[(b'a', b'a'), (b'b', b'b')]);
        let haystack = b"abx";
        let window = SearchWindow::full(haystack);
        let expected = Some(2);
        let mut session =
            K0SearchSession::new_selected(&plan, WorkspaceLimits::unlimited(), true, true)
                .unwrap();

        assert_eq!(
            plan.prepare::<SelectedEnd>()
                .search_prevalidated_proved_exact_start_selected_end_value_with_authenticated_workspace(
                    haystack,
                    window,
                    &mut session.workspace,
                    SearchLimits::unlimited(),
                )
                .unwrap(),
            expected
        );
        assert_eq!(
            super::try_warm_proved_start_selected_end(
                &plan,
                haystack,
                window,
                &session.workspace.lazy,
            ),
            Ok(expected)
        );

        let rows = session.workspace.lazy.rows.clone();
        let generation = session.workspace.generation;
        let current_len = session.workspace.current_len;
        let roots_len = session.workspace.roots_len;
        let stack_len = session.workspace.stack_len;
        assert_eq!(
            plan.prepare::<SelectedEnd>()
                .search_prevalidated_proved_exact_start_selected_end_value_with_authenticated_workspace(
                    haystack,
                    window,
                    &mut session.workspace,
                    SearchLimits::unlimited(),
                )
                .unwrap(),
            expected
        );
        assert_eq!(session.workspace.lazy.rows, rows);
        assert_eq!(session.workspace.generation, generation);
        assert_eq!(session.workspace.current_len, current_len);
        assert_eq!(session.workspace.roots_len, roots_len);
        assert_eq!(session.workspace.stack_len, stack_len);

        let initial_row = usize::try_from(
            session
                .workspace
                .lazy
                .row_offset(session.workspace.lazy.initial)
                .unwrap(),
        )
        .unwrap();
        let first_cell = initial_row + usize::from(byte_class(&plan, b'a'));
        session.workspace.lazy.rows[first_cell] = super::LAZY_CELL_UNFILLED;
        assert_eq!(
            super::try_warm_proved_start_selected_end(
                &plan,
                haystack,
                window,
                &session.workspace.lazy,
            ),
            Ok(None)
        );
        assert_eq!(
            plan.prepare::<SelectedEnd>()
                .search_prevalidated_proved_exact_start_selected_end_value_with_authenticated_workspace(
                    haystack,
                    window,
                    &mut session.workspace,
                    SearchLimits::unlimited(),
                )
                .unwrap(),
            expected
        );
        assert_ne!(
            session.workspace.lazy.rows[first_cell],
            super::LAZY_CELL_UNFILLED
        );

        let measured = plan
            .prepare::<SelectedEnd>()
            .search_prevalidated_proved_exact_start_with_authenticated_workspace(
                haystack,
                window,
                &mut session.workspace,
                SearchLimits::unlimited(),
            )
            .unwrap()
            .accounting()
            .work();
        assert_eq!(
            plan.prepare::<SelectedEnd>()
                .search_prevalidated_proved_exact_start_selected_end_value_with_authenticated_workspace(
                    haystack,
                    window,
                    &mut session.workspace,
                    SearchLimits {
                        max_work: measured,
                        max_scratch_bytes: usize::MAX,
                    },
                )
                .unwrap(),
            expected
        );
        let one_below = measured.checked_sub(1).unwrap();
        assert!(matches!(
            plan.prepare::<SelectedEnd>()
                .search_prevalidated_proved_exact_start_selected_end_value_with_authenticated_workspace(
                    haystack,
                    window,
                    &mut session.workspace,
                    SearchLimits {
                        max_work: one_below,
                        max_scratch_bytes: usize::MAX,
                    },
                ),
            Err(SearchError::WorkLimitExceeded { limit, .. }) if limit == one_below
        ));
    }

    #[test]
    fn warm_value_selected_end_matches_reported_execution_across_scanners_and_windows() {
        let plans = [
            ascii_root_bytes(b"a"),
            ascii_root_bytes(b"ac"),
            ascii_root_bytes(b"abc"),
            ascii_root_bytes(b"aceg"),
            ascii_root_bytes(&[0x00, 0x80, 0xff]),
            byte_chain(&[(b'A', b'Z'), (b'a', b'z'), (b'0', b'9')]),
            a_star(true),
            empty_or_ab(false),
            asserted_line_a(),
        ];
        let haystacks = bounded_words(&[0x00, b'A', b'a', b'b', b'1', b'z', 0x80, 0xff], 3);
        let mut comparisons = 0usize;

        for plan in &plans {
            let mut value =
                K0SearchSession::new_selected(plan, WorkspaceLimits::unlimited(), true, true)
                    .unwrap();
            let mut reported =
                K0SearchSession::new_selected(plan, WorkspaceLimits::unlimited(), true, true)
                    .unwrap();
            for haystack in &haystacks {
                for start in 0..=haystack.len() {
                    for end in start..=haystack.len() {
                        let window = SearchWindow::new(start, end);
                        let warm_value = value
                            .search_window::<SelectedEnd>(
                                haystack,
                                window,
                                SearchLimits::unlimited(),
                            )
                            .unwrap()
                            .into_output();
                        let expected = reported
                            .search_window::<SelectedEnd>(
                                haystack,
                                window,
                                SearchLimits::unlimited(),
                            )
                            .unwrap()
                            .into_output();
                        assert_eq!(warm_value, expected);

                        let actual = value
                            .search_selected_end_value(
                                haystack,
                                window,
                                SearchLimits::unlimited(),
                            )
                            .unwrap();
                        assert_eq!(actual, expected);

                        let after_value = value
                            .search_window::<SelectedEnd>(
                                haystack,
                                window,
                                SearchLimits::unlimited(),
                            )
                            .unwrap();
                        let after_reported = reported
                            .search_window::<SelectedEnd>(
                                haystack,
                                window,
                                SearchLimits::unlimited(),
                            )
                            .unwrap();
                        assert_eq!(after_value.output(), after_reported.output());
                        assert_eq!(after_value.accounting(), after_reported.accounting());
                        comparisons = comparisons.saturating_add(1);
                    }
                }
            }
        }
        assert!(comparisons > 40_000);
    }

    #[test]
    fn scanner_selected_warm_end_is_read_only_and_finite_calls_fall_back() {
        let plan = byte_chain(&[
            (b'A', b'Z'),
            (b'a', b'z'),
            (b'a', b'z'),
            (b'0', b'9'),
        ]);
        let haystack = b".Abc7~";
        let window = SearchWindow::full(haystack);
        let absent = b".Abcx~";
        let absent_window = SearchWindow::full(absent);
        let expected = Some(5);
        let mut session =
            K0SearchSession::new_selected(&plan, WorkspaceLimits::unlimited(), true, true)
                .unwrap();
        assert_eq!(
            session
                .search_window::<SelectedEnd>(haystack, window, SearchLimits::unlimited())
                .unwrap()
                .into_output(),
            expected
        );
        assert_eq!(
            session
                .search_window::<SelectedEnd>(
                    absent,
                    absent_window,
                    SearchLimits::unlimited(),
                )
                .unwrap()
                .into_output(),
            None
        );
        let proof = plan.start_filter_proof.get().unwrap();
        assert_eq!(
            super::try_warm_direct_selected_end(
                &plan,
                haystack,
                window,
                &mut session.workspace,
                proof,
            ),
            Ok(super::WarmDirectSelectedEnd::Complete(expected)),
        );
        assert_eq!(
            super::try_warm_direct_selected_end(
                &plan,
                absent,
                absent_window,
                &mut session.workspace,
                proof,
            ),
            Ok(super::WarmDirectSelectedEnd::Complete(None)),
        );

        let before_generation = session.workspace.generation;
        let before_current = session.workspace.current_len;
        let before_roots = session.workspace.roots_len;
        let before_stack = session.workspace.stack_len;
        let before_frontier = session.workspace.lazy.frontier_len;
        let before_rows = session.workspace.lazy.rows.clone();
        assert_eq!(
            session
                .search_selected_end_value(haystack, window, SearchLimits::unlimited())
                .unwrap(),
            expected
        );
        assert_eq!(
            session
                .search_selected_end_value(
                    absent,
                    absent_window,
                    SearchLimits::unlimited(),
                )
                .unwrap(),
            None
        );
        assert_eq!(session.workspace.generation, before_generation);
        assert_eq!(session.workspace.current_len, before_current);
        assert_eq!(session.workspace.roots_len, before_roots);
        assert_eq!(session.workspace.stack_len, before_stack);
        assert_eq!(session.workspace.lazy.frontier_len, before_frontier);
        assert_eq!(session.workspace.lazy.rows, before_rows);

        let initial_row = usize::try_from(
            session
                .workspace
                .lazy
                .row_offset(session.workspace.lazy.initial)
                .unwrap(),
        )
        .unwrap();
        let first_cell = initial_row + usize::from(byte_class(&plan, b'A'));
        session.workspace.lazy.rows[first_cell] = super::LAZY_CELL_UNFILLED;
        assert_eq!(
            session
                .search_selected_end_value(haystack, window, SearchLimits::unlimited())
                .unwrap(),
            expected
        );
        assert_ne!(
            session.workspace.lazy.rows[first_cell],
            super::LAZY_CELL_UNFILLED
        );

        let measured = session
            .search_window::<SelectedEnd>(haystack, window, SearchLimits::unlimited())
            .unwrap()
            .accounting()
            .work();
        let one_below_measured = measured.checked_sub(1).unwrap();
        assert_eq!(
            session
                .search_selected_end_value(
                    haystack,
                    window,
                    SearchLimits {
                        max_work: measured,
                        max_scratch_bytes: usize::MAX,
                    },
                )
                .unwrap(),
            expected
        );
        assert!(matches!(
            session.search_selected_end_value(
                haystack,
                window,
                SearchLimits {
                    max_work: one_below_measured,
                    max_scratch_bytes: usize::MAX,
                },
            ),
            Err(SearchError::WorkLimitExceeded { limit, .. }) if limit == one_below_measured
        ));

        let before_invalid_rows = session.workspace.lazy.rows.clone();
        let before_invalid_generation = session.workspace.generation;
        assert!(matches!(
            session.search_selected_end_value(
                haystack,
                SearchWindow::new(5, 3),
                SearchLimits::unlimited(),
            ),
            Err(SearchError::InvalidWindow { start: 5, end: 3, .. })
        ));
        assert_eq!(session.workspace.generation, before_invalid_generation);
        assert_eq!(session.workspace.lazy.rows, before_invalid_rows);
    }

    #[test]
    fn warm_value_selected_end_hands_off_without_prefix_replay_and_keeps_pending() {
        let match_len = WARM_EXISTS_INLINE_BYTES.checked_add(4).unwrap();
        let plan = byte_chain(&vec![(b'a', b'a'); match_len]);
        let warm = vec![b'a'; match_len];
        let mut novel = warm.clone();
        *novel.last_mut().unwrap() = b'x';
        let window = SearchWindow::full(&novel);
        let branch_row = |workspace: &K0Workspace| {
            let mut row = workspace.lazy.row_offset(workspace.lazy.initial).unwrap();
            for _ in 0..match_len - 1 {
                let cell = workspace
                    .lazy
                    .direct_cell(row, byte_class(&plan, b'a'))
                    .unwrap();
                row = (cell & super::LAZY_CELL_STATE_MASK)
                    .checked_sub(1)
                    .expect("the warmed selected-end prefix remains live");
            }
            row
        };

        let mut direct =
            K0SearchSession::new_selected(&plan, WorkspaceLimits::unlimited(), true, true)
                .unwrap();
        assert_eq!(
            direct
                .search_window::<SelectedEnd>(
                    &warm,
                    SearchWindow::full(&warm),
                    SearchLimits::unlimited(),
                )
                .unwrap()
                .into_output(),
            Some(match_len),
        );
        let proof = plan.start_filter_proof.get().unwrap();
        let initial_row = direct
            .workspace
            .lazy
            .row_offset(direct.workspace.lazy.initial)
            .unwrap();
        let row = branch_row(&direct.workspace);
        let novel_class = byte_class(&plan, b'x');
        assert_eq!(
            direct.workspace.lazy.direct_cell(row, novel_class).unwrap(),
            super::LAZY_CELL_UNFILLED,
        );
        let consumed_prefix_cell = usize::try_from(initial_row)
            .unwrap()
            .checked_add(usize::from(byte_class(&plan, b'a')))
            .unwrap();
        direct.workspace.lazy.rows[consumed_prefix_cell] = super::LAZY_CELL_UNFILLED;
        assert_eq!(
            super::continue_mutable_warm_direct_selected_end(
                &plan,
                &novel,
                window,
                &mut direct.workspace,
                proof,
                super::WarmDirectSelectedEndContinuation {
                    initial_row,
                    state: row,
                    position: match_len - 1,
                    work: INVOCATION_RESET_WORK,
                    direct_steps: match_len - 1,
                    ..super::WarmDirectSelectedEndContinuation::default()
                },
            )
            .unwrap(),
            None,
        );
        assert_ne!(
            direct.workspace.lazy.direct_cell(row, novel_class).unwrap(),
            super::LAZY_CELL_UNFILLED,
            "selected-end continuation did not publish its first missing cell",
        );
        assert_eq!(
            direct.workspace.lazy.rows[consumed_prefix_cell],
            super::LAZY_CELL_UNFILLED,
            "selected-end continuation replayed an already-consumed prefix edge",
        );

        let pending_plan = greedy_a_plus_or_a();
        let pending_warm = b"aaaa";
        let pending_novel = b"aaax";
        let pending_window = SearchWindow::full(pending_novel);
        let mut pending = K0SearchSession::new_selected(
            &pending_plan,
            WorkspaceLimits::unlimited(),
            true,
            true,
        )
        .unwrap();
        assert_eq!(
            pending
                .search_window::<SelectedEnd>(
                    pending_warm,
                    SearchWindow::full(pending_warm),
                    SearchLimits::unlimited(),
                )
                .unwrap()
                .into_output(),
            Some(4),
        );
        assert!(pending.workspace.lazy.loop_skip_plans.is_empty());
        assert_eq!(
            pending
                .search_selected_end_value(
                    pending_novel,
                    pending_window,
                    SearchLimits::unlimited(),
                )
                .unwrap(),
            Some(3),
        );
        let rows = pending.workspace.lazy.rows.clone();
        let generation = pending.workspace.generation;
        assert_eq!(
            pending
                .search_selected_end_value(
                    pending_novel,
                    pending_window,
                    SearchLimits::unlimited(),
                )
                .unwrap(),
            Some(3),
        );
        assert_eq!(pending.workspace.lazy.rows, rows);
        assert_eq!(pending.workspace.generation, generation);
    }

    #[test]
    fn warm_value_selected_end_public_handoff_publishes_loop_plan_without_replay() {
        let plan = ascii_loop_class(1);
        pin_without_start_filter(&plan);
        let run_len = super::LAZY_LOOP_SKIP_MIN_BYTES * 2;
        let warm = vec![0_u8; run_len];
        let mut novel = warm.clone();
        novel.push(1);
        let finite = SearchLimits {
            max_work: u64::MAX - 1,
            max_scratch_bytes: usize::MAX,
        };
        let mut value =
            K0SearchSession::new_selected(&plan, WorkspaceLimits::unlimited(), true, true)
                .unwrap();
        let mut ordinary =
            K0SearchSession::new_selected(&plan, WorkspaceLimits::unlimited(), true, true)
                .unwrap();

        for session in [&mut value, &mut ordinary] {
            assert_eq!(
                session
                    .search_window::<SelectedEnd>(
                        &warm,
                        SearchWindow::full(&warm),
                        finite,
                    )
                    .unwrap()
                    .into_output(),
                None,
            );
            assert!(session.workspace.lazy.loop_skip_plans.is_empty());
            let initial_row = session
                .workspace
                .lazy
                .row_offset(session.workspace.lazy.initial)
                .unwrap();
            assert_ne!(
                session
                    .workspace
                    .lazy
                    .direct_cell(initial_row, byte_class(&plan, 0))
                    .unwrap(),
                super::LAZY_CELL_UNFILLED,
            );
            assert_eq!(
                session
                    .workspace
                    .lazy
                    .direct_cell(initial_row, byte_class(&plan, 1))
                    .unwrap(),
                super::LAZY_CELL_UNFILLED,
            );
        }

        super::WARM_DIRECT_SELECTED_END_HANDOFF.with(|slot| slot.set(None));
        assert_eq!(
            value
                .search_selected_end_value(
                    &novel,
                    SearchWindow::full(&novel),
                    SearchLimits::unlimited(),
                )
                .unwrap(),
            Some(run_len + 1),
        );
        let handoff = super::WARM_DIRECT_SELECTED_END_HANDOFF
            .with(std::cell::Cell::get)
            .expect("the public value facade must continue its exact first missing transition");
        assert_eq!(handoff.position, run_len);
        assert_eq!(handoff.direct_steps, run_len);
        assert_eq!(handoff.pending_end, None);
        assert_eq!(
            ordinary
                .search_window::<SelectedEnd>(
                    &novel,
                    SearchWindow::full(&novel),
                    SearchLimits::unlimited(),
                )
                .unwrap()
                .into_output(),
            Some(run_len + 1),
        );

        assert_resume_cache_equivalent(&value.workspace, &ordinary.workspace);
        assert_eq!(
            value.workspace.lazy.loop_skip_analyzed_at_cells,
            ordinary.workspace.lazy.loop_skip_analyzed_at_cells,
        );
        assert_eq!(
            direct_loop_cache_signature(&value.workspace),
            direct_loop_cache_signature(&ordinary.workspace),
        );
        assert!(!value.workspace.lazy.loop_skip_plans.is_empty());
        assert_eq!(
            value.workspace.lazy.loop_skip_analyzed_at_cells,
            value.workspace.lazy.direct_cells_published,
        );
    }

    #[test]
    fn warm_value_selected_end_matches_reports_after_same_address_source_changes() {
        let plans = [
            ascii_root_bytes(b"a"),
            ascii_root_bytes(b"ac"),
            ascii_root_bytes(b"abc"),
            ascii_root_bytes(b"aceg"),
            byte_chain(&[(b'A', b'Z'), (b'a', b'z'), (b'0', b'9')]),
            a_star(true),
            empty_or_ab(false),
            asserted_line_a(),
        ];
        let haystacks = bounded_words(&[0x00, b'A', b'a', b'b', b'1', 0x80, 0xff], 3);
        let mut mutable_handoffs = 0usize;
        let mut comparisons = 0usize;

        for plan in &plans {
            let mut value =
                K0SearchSession::new_selected(plan, WorkspaceLimits::unlimited(), true, true)
                    .unwrap();
            let mut reported =
                K0SearchSession::new_selected(plan, WorkspaceLimits::unlimited(), true, true)
                    .unwrap();
            for haystack in &haystacks {
                let mut source = haystack.clone();
                for byte in &mut source {
                    *byte = byte.wrapping_add(1);
                }
                let address = source.as_ptr();
                for start in 0..=source.len() {
                    for end in start..=source.len() {
                        let window = SearchWindow::new(start, end);
                        value
                            .search_window::<SelectedEnd>(
                                &source,
                                window,
                                SearchLimits::unlimited(),
                            )
                            .unwrap();
                        source.copy_from_slice(haystack);
                        assert_eq!(source.as_ptr(), address);
                        let published = value.workspace.lazy.direct_cells_published;
                        let actual = value
                            .search_selected_end_value(
                                &source,
                                window,
                                SearchLimits::unlimited(),
                            )
                            .unwrap();
                        mutable_handoffs = mutable_handoffs.saturating_add(usize::from(
                            value.workspace.lazy.direct_cells_published > published,
                        ));
                        let expected = reported
                            .search_window::<SelectedEnd>(
                                haystack,
                                window,
                                SearchLimits::unlimited(),
                            )
                            .unwrap()
                            .into_output();
                        assert_eq!(actual, expected);
                        comparisons = comparisons.saturating_add(1);
                        for byte in &mut source {
                            *byte = byte.wrapping_add(1);
                        }
                    }
                }
            }
        }
        assert!(mutable_handoffs != 0);
        assert!(comparisons > 29_000);
    }

    #[test]
    fn warm_value_selected_end_first_miss_matches_ordinary_cache_mutation() {
        let assert_equivalent = |left: &K0Workspace, right: &K0Workspace| {
            assert_resume_cache_equivalent(left, right);
            assert_eq!(
                left.lazy.loop_skip_analyzed_at_cells,
                right.lazy.loop_skip_analyzed_at_cells,
            );
            assert_eq!(
                left.lazy.loop_skip_plans.state_members,
                right.lazy.loop_skip_plans.state_members,
            );
            assert_eq!(
                direct_loop_cache_signature(left),
                direct_loop_cache_signature(right),
            );
        };

        let match_len = WARM_EXISTS_INLINE_BYTES.checked_add(4).unwrap();
        let plan = byte_chain(&vec![(b'a', b'a'); match_len]);
        let warm = vec![b'a'; match_len];
        let mut novel = warm.clone();
        *novel.last_mut().unwrap() = b'x';
        let mut proof_owner =
            K0SearchSession::new_selected(&plan, WorkspaceLimits::unlimited(), true, true)
                .unwrap();
        proof_owner
            .search_window::<SelectedEnd>(
                &warm,
                SearchWindow::full(&warm),
                SearchLimits::unlimited(),
            )
            .unwrap();
        let mut value =
            K0SearchSession::new_selected(&plan, WorkspaceLimits::unlimited(), true, true)
                .unwrap();
        let mut ordinary =
            K0SearchSession::new_selected(&plan, WorkspaceLimits::unlimited(), true, true)
                .unwrap();
        for session in [&mut value, &mut ordinary] {
            assert_eq!(
                session
                    .search_window::<SelectedEnd>(
                        &warm,
                        SearchWindow::full(&warm),
                        SearchLimits::unlimited(),
                    )
                    .unwrap()
                    .into_output(),
                Some(match_len),
            );
        }
        assert_eq!(
            value
                .search_selected_end_value(
                    &novel,
                    SearchWindow::full(&novel),
                    SearchLimits::unlimited(),
                )
                .unwrap(),
            None,
        );
        assert_eq!(
            ordinary
                .search_window::<SelectedEnd>(
                    &novel,
                    SearchWindow::full(&novel),
                    SearchLimits::unlimited(),
                )
                .unwrap()
                .into_output(),
            None,
        );
        assert_equivalent(&value.workspace, &ordinary.workspace);

        let mut retained_states = 0usize;
        let mut retained_items = 0usize;
        loop {
            let next_states = retained_states.checked_add(1).unwrap();
            let next_items = retained_items.checked_add(next_states).unwrap();
            if next_states > super::LAZY_MAX_STATES || next_items > super::LAZY_MAX_ITEMS {
                break;
            }
            retained_states = next_states;
            retained_items = next_items;
        }
        let depth = retained_states.checked_add(1).unwrap();
        let plan = byte_chain(&vec![(b'a', b'a'); depth]);
        let warm = vec![b'a'; retained_states.checked_sub(1).unwrap()];
        let novel = vec![b'a'; retained_states];
        let mut proof_owner =
            K0SearchSession::new_selected(&plan, WorkspaceLimits::unlimited(), true, true)
                .unwrap();
        proof_owner
            .search_window::<SelectedEnd>(
                &warm,
                SearchWindow::full(&warm),
                SearchLimits::unlimited(),
            )
            .unwrap();
        let mut value =
            K0SearchSession::new_selected(&plan, WorkspaceLimits::unlimited(), true, true)
                .unwrap();
        let mut ordinary =
            K0SearchSession::new_selected(&plan, WorkspaceLimits::unlimited(), true, true)
                .unwrap();
        for session in [&mut value, &mut ordinary] {
            assert_eq!(
                session
                    .search_window::<SelectedEnd>(
                        &warm,
                        SearchWindow::full(&warm),
                        SearchLimits::unlimited(),
                    )
                    .unwrap()
                    .into_output(),
                None,
            );
            assert_eq!(session.workspace.lazy.state_len, retained_states);
            assert_eq!(session.workspace.lazy.item_len, retained_items);
            assert!(!session.workspace.lazy.saturated);
        }
        assert_eq!(
            value
                .search_selected_end_value(
                    &novel,
                    SearchWindow::full(&novel),
                    SearchLimits::unlimited(),
                )
                .unwrap(),
            None,
        );
        assert_eq!(
            ordinary
                .search_window::<SelectedEnd>(
                    &novel,
                    SearchWindow::full(&novel),
                    SearchLimits::unlimited(),
                )
                .unwrap()
                .into_output(),
            None,
        );
        assert!(value.workspace.lazy.saturated);
        assert!(ordinary.workspace.lazy.saturated);
        assert_equivalent(&value.workspace, &ordinary.workspace);
    }

    #[test]
    fn warm_value_exists_matches_reported_execution_across_scanners_and_windows() {
        let plans = [
            ascii_root_bytes(b"a"),
            ascii_root_bytes(b"ac"),
            ascii_root_bytes(b"abc"),
            ascii_root_bytes(b"aceg"),
            ascii_root_bytes(&[0x00, 0x80, 0xff]),
            byte_chain(&[(b'A', b'Z'), (b'a', b'z'), (b'0', b'9')]),
            a_star(true),
            empty_or_ab(false),
            asserted_line_a(),
        ];
        let haystacks = bounded_words(&[0x00, b'A', b'a', b'b', b'1', b'z', 0x80, 0xff], 3);
        let mut comparisons = 0usize;

        for plan in &plans {
            let mut value =
                K0SearchSession::new_selected(plan, WorkspaceLimits::unlimited(), true, true)
                    .unwrap();
            let mut reported =
                K0SearchSession::new_selected(plan, WorkspaceLimits::unlimited(), true, true)
                    .unwrap();
            for haystack in &haystacks {
                for start in 0..=haystack.len() {
                    for end in start..=haystack.len() {
                        let window = SearchWindow::new(start, end);
                        let warm_value = value
                            .search_window::<Exists>(haystack, window, SearchLimits::unlimited())
                            .unwrap()
                            .into_output();
                        let expected = reported
                            .search_window::<Exists>(haystack, window, SearchLimits::unlimited())
                            .unwrap()
                            .into_output();
                        assert_eq!(warm_value, expected);

                        let actual = value
                            .search_exists_value(haystack, window, SearchLimits::unlimited())
                            .unwrap();
                        assert_eq!(actual, expected);

                        let after_value = value
                            .search_window::<Exists>(haystack, window, SearchLimits::unlimited())
                            .unwrap();
                        let after_reported = reported
                            .search_window::<Exists>(haystack, window, SearchLimits::unlimited())
                            .unwrap();
                        assert_eq!(after_value.output(), after_reported.output());
                        assert_eq!(after_value.accounting(), after_reported.accounting());
                        comparisons = comparisons.saturating_add(1);
                    }
                }
            }
        }
        assert!(comparisons > 40_000);
    }

