    fn resume_cache_owners_remain_send_and_sync() {
        fn assert_send_sync<T: Send + Sync>() {}

        assert_send_sync::<K0Workspace>();
        assert_send_sync::<K0ResumeSet>();
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "the regression keeps retained-byte accounting, many unrelated hints, and the exact failed seed transaction together"
    )]
    fn failed_workspace_switch_does_not_clear_many_unrelated_resume_hints() {
        const FRONTIERS: usize = 64;
        let plan = byte_chain(&[(b'a', b'a'), (b'b', b'b')]);
        let haystack = b"zzabzzab";
        let window = SearchWindow::full(haystack);
        let frontier = [1_u32];
        let mut resume = K0ResumeSet::new(
            &plan,
            FRONTIERS,
            FRONTIERS,
            core::iter::repeat((&frontier[..], false)).take(FRONTIERS),
        )
        .unwrap();
        assert!(
            resume
                .cached_workspace_identities
                .iter()
                .all(|&identity| identity == super::PRISTINE_RESUME_CACHE_ID)
        );
        let retained = resume
            .offsets
            .capacity()
            .checked_mul(size_of::<usize>())
            .and_then(|bytes| {
                resume
                    .lengths
                    .capacity()
                    .checked_mul(size_of::<u32>())
                    .and_then(|more| bytes.checked_add(more))
            })
            .and_then(|bytes| bytes.checked_add(resume.modes.capacity()))
            .and_then(|bytes| {
                resume
                    .cached_states
                    .capacity()
                    .checked_mul(size_of::<u32>())
                    .and_then(|more| bytes.checked_add(more))
            })
            .and_then(|bytes| {
                resume
                    .cached_workspace_identities
                    .capacity()
                    .checked_mul(size_of::<u64>())
                    .and_then(|more| bytes.checked_add(more))
            })
            .and_then(|bytes| {
                resume
                    .items
                    .capacity()
                    .checked_mul(size_of::<u32>())
                    .and_then(|more| bytes.checked_add(more))
            })
            .unwrap();
        assert_eq!(resume.retained_bytes(), retained);

        let mut first =
            K0Workspace::new_accelerated(&plan, WorkspaceLimits::unlimited()).unwrap();
        for state in 0..FRONTIERS {
            super::search_from_resume_with_workspace(
                &plan,
                haystack,
                window,
                &mut first,
                &mut resume,
                state,
                3,
                None,
                SearchLimits::unlimited(),
                OutputContract::SelectedEnd,
            )
            .unwrap();
        }
        assert!(
            resume
                .cached_states
                .iter()
                .all(|&state| state != super::LAZY_NO_STATE)
        );
        assert!(
            resume
                .cached_workspace_identities
                .iter()
                .all(|&identity| identity == first.lazy.cache_identity)
        );
        let states_before = resume.cached_states.clone();
        let identities_before = resume.cached_workspace_identities.clone();

        let mut second =
            K0Workspace::new_accelerated(&plan, WorkspaceLimits::unlimited()).unwrap();
        assert_ne!(first.lazy.cache_identity, second.lazy.cache_identity);
        let mut meter = super::WorkMeter::new(0, 0);
        let error = super::seed_lazy_resume_state(
            &plan,
            &mut second,
            &mut resume,
            0,
            &mut meter,
            0,
            3,
            false,
        )
        .unwrap_err();
        assert!(matches!(
            error,
            SearchError::WorkLimitExceeded {
                limit: 0,
                consumed: 0,
                requested: 1,
                position: 3,
            }
        ));
        assert_eq!(resume.cached_states, states_before);
        assert_eq!(resume.cached_workspace_identities, identities_before);
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "the regression follows two independently tagged frontiers through immutable warm probes and a workspace round trip"
    )]
    fn per_frontier_cache_identities_preserve_unrelated_and_returned_workspace_hints() {
        let plan = byte_chain(&[(b'a', b'a'), (b'b', b'b')]);
        let haystack = b"zzabzzab";
        let window = SearchWindow::full(haystack);
        let frontier = [1_u32];
        let mut resume = K0ResumeSet::new(
            &plan,
            2,
            2,
            [(&frontier[..], false), (&frontier[..], false)],
        )
        .unwrap();
        let mut first =
            K0Workspace::new_accelerated(&plan, WorkspaceLimits::unlimited()).unwrap();
        let mut expected = None;
        for state in 0..2 {
            expected = Some(
                super::search_from_resume_with_workspace(
                    &plan,
                    haystack,
                    window,
                    &mut first,
                    &mut resume,
                    state,
                    3,
                    None,
                    SearchLimits::unlimited(),
                    OutputContract::SelectedEnd,
                )
                .unwrap()
                .found,
            );
        }
        let expected = expected.unwrap();
        let first_identity = first.lazy.cache_identity;
        let unrelated_state = resume.cached_states[1];

        let mut second =
            K0Workspace::new_accelerated(&plan, WorkspaceLimits::unlimited()).unwrap();
        let second_identity = second.lazy.cache_identity;
        let second_result = super::search_from_resume_with_workspace(
            &plan,
            haystack,
            window,
            &mut second,
            &mut resume,
            0,
            3,
            None,
            SearchLimits::unlimited(),
            OutputContract::SelectedEnd,
        )
        .unwrap()
        .found;
        assert_eq!(second_result, expected);
        assert_eq!(
            resume.cached_workspace_identities,
            [second_identity, first_identity]
        );
        assert_eq!(resume.cached_states[1], unrelated_state);

        let states_before_probe = resume.cached_states.clone();
        let identities_before_probe = resume.cached_workspace_identities.clone();
        let (trusted_found, trusted_work) = match super::try_accounted_warm_ordered_resume_endpoint(
            &plan,
            haystack,
            window,
            &first,
            &resume,
            1,
            3,
            None,
            false,
        )
        .unwrap()
        {
            super::AccountedWarmResumeEndpoint::Complete { found, work } => (found, work),
            outcome => panic!("returned-workspace warm hint did not complete: {outcome:?}"),
        };
        assert_eq!(trusted_found, expected.map(MatchSpan::end));

        // Identity exhaustion preserves correctness by checking the retained
        // mode and frontier. Its accounting differs from the trusted path by
        // exactly one work unit per frontier item.
        first.lazy.cache_identity = 0;
        let (checked_found, checked_work) = match super::try_accounted_warm_ordered_resume_endpoint(
            &plan,
            haystack,
            window,
            &first,
            &resume,
            1,
            3,
            None,
            false,
        )
        .unwrap()
        {
            super::AccountedWarmResumeEndpoint::Complete { found, work } => (found, work),
            outcome => panic!("zero-identity warm hint did not content-authenticate: {outcome:?}"),
        };
        first.lazy.cache_identity = first_identity;
        assert_eq!(checked_found, trusted_found);
        assert_eq!(
            checked_work,
            trusted_work + u64::try_from(frontier.len()).unwrap()
        );
        assert_eq!(resume.cached_states, states_before_probe);
        assert_eq!(
            resume.cached_workspace_identities,
            identities_before_probe
        );

        // The public value path may consume the still-valid entry for `first`
        // without disturbing entry zero, which is tagged for `second`.
        assert_eq!(
            plan.prepare::<SelectedEnd>()
                .search_prevalidated_selected_end_value_from_ordered_resume_with_authenticated_workspace(
                    haystack,
                    window,
                    &mut first,
                    &mut resume,
                    1,
                    3,
                    None,
                    SearchLimits::unlimited(),
                )
                .unwrap(),
            expected.map(MatchSpan::end)
        );
        assert_eq!(resume.cached_states, states_before_probe);
        assert_eq!(
            resume.cached_workspace_identities,
            identities_before_probe
        );

        // Both caches happened to assign the identical semantic frontier the
        // same in-bounds numeric state ID. The different nonzero entry tag is
        // nevertheless authoritative: the immutable probe must decline and
        // leave publication to the mutable seed path.
        assert_eq!(resume.cached_states[0], resume.cached_states[1]);
        assert!(usize::try_from(resume.cached_states[1])
            .ok()
            .is_some_and(|state| state < second.lazy.state_len));
        assert_eq!(
            super::try_accounted_warm_ordered_resume_endpoint(
                &plan,
                haystack,
                window,
                &second,
                &resume,
                1,
                3,
                None,
                false,
            )
            .unwrap(),
            super::AccountedWarmResumeEndpoint::Declined
        );
        assert_eq!(resume.cached_states, states_before_probe);
        assert_eq!(
            resume.cached_workspace_identities,
            identities_before_probe
        );

        let mut meter = super::WorkMeter::new(1, 0);
        assert!(matches!(
            super::seed_lazy_resume_state(
                &plan,
                &mut first,
                &mut resume,
                1,
                &mut meter,
                0,
                3,
                true,
            )
            .unwrap(),
            super::LazyState::Cached(_)
        ));
        assert_eq!(meter.consumed, 1);

        let returned = super::search_from_resume_with_workspace(
            &plan,
            haystack,
            window,
            &mut first,
            &mut resume,
            0,
            3,
            None,
            SearchLimits::unlimited(),
            OutputContract::SelectedEnd,
        )
        .unwrap()
        .found;
        assert_eq!(returned, expected);
        assert_eq!(
            resume.cached_workspace_identities,
            [first_identity, first_identity]
        );
        let mut meter = super::WorkMeter::new(1, 0);
        assert!(matches!(
            super::seed_lazy_resume_state(
                &plan,
                &mut first,
                &mut resume,
                0,
                &mut meter,
                0,
                3,
                true,
            )
            .unwrap(),
            super::LazyState::Cached(_)
        ));
        assert_eq!(meter.consumed, 1);
    }

    #[test]
    fn exhausted_zero_cache_identity_authenticates_hint_contents() {
        let plan = byte_chain(&[(b'a', b'a'), (b'b', b'b')]);
        let haystack = b"zzabzzab";
        let window = SearchWindow::full(haystack);
        let frontier = [1_u32];
        let mut resume = K0ResumeSet::new(&plan, 1, 1, [(&frontier[..], false)]).unwrap();
        let mut first =
            K0Workspace::new_accelerated(&plan, WorkspaceLimits::unlimited()).unwrap();
        first.lazy.cache_identity = 0;
        let expected = super::search_from_resume_with_workspace(
            &plan,
            haystack,
            window,
            &mut first,
            &mut resume,
            0,
            3,
            None,
            SearchLimits::unlimited(),
            OutputContract::SelectedEnd,
        )
        .unwrap()
        .found;
        let stale_hint = resume.cached_states[0];

        let mut second =
            K0Workspace::new_accelerated(&plan, WorkspaceLimits::unlimited()).unwrap();
        second.lazy.cache_identity = 0;
        let mut pending_resume =
            K0ResumeSet::new(&plan, 1, 1, [(&frontier[..], true)]).unwrap();
        super::search_from_resume_with_workspace(
            &plan,
            haystack,
            window,
            &mut second,
            &mut pending_resume,
            0,
            3,
            Some(2),
            SearchLimits::unlimited(),
            OutputContract::SelectedEnd,
        )
        .unwrap();
        assert_eq!(pending_resume.cached_states[0], stale_hint);
        assert!(super::resume_lazy_state_bounds(&second.lazy, stale_hint)
            .unwrap()
            .2);

        let actual = super::search_from_resume_with_workspace(
            &plan,
            haystack,
            window,
            &mut second,
            &mut resume,
            0,
            3,
            None,
            SearchLimits::unlimited(),
            OutputContract::SelectedEnd,
        )
        .unwrap()
        .found;
        assert_eq!(actual, expected);
        assert_ne!(resume.cached_states[0], stale_hint);
        assert!(!super::resume_lazy_state_bounds(&second.lazy, resume.cached_states[0])
            .unwrap()
            .2);
    }

    fn assert_resume_batch_exit_shape(
        plan: &Automaton,
        haystack: &[u8],
        window: SearchWindow,
        workspace: &K0Workspace,
        resume: &K0ResumeSet,
        exit: ResumeBatchExit,
    ) {
        let ready = usize::from(super::RESUME_DIRECT_BATCH_MIN_READY) + 2;
        let mut row = workspace.lazy.row_offset(resume.cached_states[0]).unwrap();
        let prefix_end = window.start().checked_add(ready).unwrap();
        for &byte in haystack.get(window.start()..prefix_end).unwrap() {
            assert_eq!(byte, b'a');
            let cell = workspace
                .lazy
                .direct_cell(row, byte_class(plan, byte))
                .unwrap();
            assert_ne!(cell, super::LAZY_CELL_UNFILLED);
            assert_eq!(cell & super::LAZY_CELL_ACCEPT, 0);
            let encoded = cell & super::LAZY_CELL_STATE_MASK;
            assert_ne!(encoded, 0);
            row = encoded.checked_sub(1).unwrap();
        }
        let exit_position = prefix_end;
        match exit {
            ResumeBatchExit::WindowEnd => assert_eq!(exit_position, window.end()),
            ResumeBatchExit::Accept => {
                let byte = *haystack.get(exit_position).unwrap();
                let cell = workspace
                    .lazy
                    .direct_cell(row, byte_class(plan, byte))
                    .unwrap();
                assert_ne!(cell, super::LAZY_CELL_UNFILLED);
                assert_ne!(cell & super::LAZY_CELL_ACCEPT, 0);
            }
            ResumeBatchExit::Dead => {
                let byte = *haystack.get(exit_position).unwrap();
                let cell = workspace
                    .lazy
                    .direct_cell(row, byte_class(plan, byte))
                    .unwrap();
                assert_eq!(
                    cell & (super::LAZY_CELL_STATE_MASK | super::LAZY_CELL_ACCEPT),
                    0,
                );
            }
            ResumeBatchExit::FirstUnfilled => {
                let byte = *haystack.get(exit_position).unwrap();
                assert_eq!(
                    workspace
                        .lazy
                        .direct_cell(row, byte_class(plan, byte))
                        .unwrap(),
                    super::LAZY_CELL_UNFILLED,
                );
            }
        }
    }

    fn assert_resume_cache_equivalent(left: &K0Workspace, right: &K0Workspace) {
        assert_eq!(left.generation, right.generation);
        assert_eq!(left.current_len, right.current_len);
        assert_eq!(left.roots_len, right.roots_len);
        assert_eq!(left.stack_len, right.stack_len);
        assert_eq!(left.lazy.scratch, right.lazy.scratch);
        assert_eq!(left.lazy.scratch_len, right.lazy.scratch_len);
        assert_eq!(left.lazy.frontier, right.lazy.frontier);
        assert_eq!(left.lazy.frontier_len, right.lazy.frontier_len);
        assert_eq!(left.lazy.rows, right.lazy.rows);
        assert_eq!(left.lazy.offsets, right.lazy.offsets);
        assert_eq!(left.lazy.lengths, right.lazy.lengths);
        assert_eq!(left.lazy.modes, right.lazy.modes);
        assert_eq!(left.lazy.hashes, right.lazy.hashes);
        assert_eq!(left.lazy.index, right.lazy.index);
        assert_eq!(left.lazy.items, right.lazy.items);
        assert_eq!(left.lazy.state_len, right.lazy.state_len);
        assert_eq!(left.lazy.item_len, right.lazy.item_len);
        assert_eq!(left.lazy.initial, right.lazy.initial);
        assert_eq!(
            left.lazy.direct_cells_published,
            right.lazy.direct_cells_published,
        );
        assert_eq!(left.lazy.initialized, right.lazy.initialized);
        assert_eq!(left.lazy.declined, right.lazy.declined);
        assert_eq!(left.lazy.saturated, right.lazy.saturated);
    }

    #[allow(
        clippy::too_many_arguments,
        reason = "the differential keeps warmup and tested exit windows explicit"
    )]
    fn assert_warmed_resume_batch_case(
        plan: &Automaton,
        frontier: &[u32],
        warm_haystack: &[u8],
        warm_window: SearchWindow,
        haystack: &[u8],
        window: SearchWindow,
        pending_end: Option<usize>,
        contract: OutputContract,
        exit: ResumeBatchExit,
        expected: Option<MatchSpan>,
    ) -> u64 {
        let (mut batched_workspace, mut batched_resume) = warm_resume_batch_fixture(
            plan,
            frontier,
            warm_haystack,
            warm_window,
            pending_end,
            contract,
        );
        let (mut scalar_workspace, mut scalar_resume) = warm_resume_batch_fixture(
            plan,
            frontier,
            warm_haystack,
            warm_window,
            pending_end,
            contract,
        );
        assert_resume_batch_exit_shape(
            plan,
            haystack,
            window,
            &batched_workspace,
            &batched_resume,
            exit,
        );
        assert_resume_cache_equivalent(&batched_workspace, &scalar_workspace);
        assert_eq!(batched_resume.cached_states, scalar_resume.cached_states);

        // Unlimited dispatches the `BATCH_WARM=true` monomorph while every
        // finite work limit dispatches the scalar `BATCH_WARM=false` path.
        let batched = super::search_from_resume_with_workspace(
            plan,
            haystack,
            window,
            &mut batched_workspace,
            &mut batched_resume,
            0,
            window.start(),
            pending_end,
            SearchLimits::unlimited(),
            contract,
        )
        .unwrap_or_else(|error| {
            panic!("batched {contract:?} {exit:?} continuation failed: {error:?}")
        });
        let scalar = super::search_from_resume_with_workspace(
            plan,
            haystack,
            window,
            &mut scalar_workspace,
            &mut scalar_resume,
            0,
            window.start(),
            pending_end,
            SearchLimits {
                max_work: u64::MAX - 1,
                max_scratch_bytes: usize::MAX,
            },
            contract,
        )
        .unwrap_or_else(|error| {
            panic!("scalar {contract:?} {exit:?} continuation failed: {error:?}")
        });
        assert_eq!(batched.found, expected);
        assert_eq!(scalar.found, expected);
        assert_eq!(batched.accounting, scalar.accounting);
        assert_resume_cache_equivalent(&batched_workspace, &scalar_workspace);
        assert_eq!(batched_resume.cached_states, scalar_resume.cached_states);
        batched.accounting.work()
    }

    #[test]
    #[allow(clippy::too_many_lines)]
    fn warmed_resume_batch_matches_scalar_at_every_exit_and_contract() {
        let endpoint_plan = greedy_a_star_b();
        // Exact ordered closure of the `a*b` split.
        let endpoint_frontier = [1_u32, 2_u32];
        let span_plan = byte_chain(&[
            (b'a', b'a'),
            (b'a', b'a'),
            (b'a', b'a'),
            (b'a', b'a'),
            (b'a', b'a'),
            (b'a', b'a'),
            (b'b', b'b'),
        ]);
        let span_frontier = [0_u32];
        let window_end = b"aaaaaa";
        let accept = b"aaaaaab";
        let first_unfilled = b"aaaaaax";

        for contract in [OutputContract::Exists, OutputContract::SelectedEnd] {
            assert_warmed_resume_batch_case(
                &endpoint_plan,
                &endpoint_frontier,
                window_end,
                SearchWindow::full(window_end),
                window_end,
                SearchWindow::full(window_end),
                None,
                contract,
                ResumeBatchExit::WindowEnd,
                None,
            );
            assert_warmed_resume_batch_case(
                &endpoint_plan,
                &endpoint_frontier,
                accept,
                SearchWindow::full(accept),
                accept,
                SearchWindow::full(accept),
                None,
                contract,
                ResumeBatchExit::Accept,
                Some(MatchSpan::new(0, accept.len())),
            );
            assert_warmed_resume_batch_case(
                &endpoint_plan,
                &endpoint_frontier,
                window_end,
                SearchWindow::full(window_end),
                first_unfilled,
                SearchWindow::full(first_unfilled),
                None,
                contract,
                ResumeBatchExit::FirstUnfilled,
                None,
            );
        }
        assert_warmed_resume_batch_case(
            &span_plan,
            &span_frontier,
            window_end,
            SearchWindow::full(window_end),
            window_end,
            SearchWindow::full(window_end),
            None,
            OutputContract::Span,
            ResumeBatchExit::WindowEnd,
            None,
        );
        assert_warmed_resume_batch_case(
            &span_plan,
            &span_frontier,
            accept,
            SearchWindow::full(accept),
            accept,
            SearchWindow::full(accept),
            None,
            OutputContract::Span,
            ResumeBatchExit::Accept,
            Some(MatchSpan::new(0, accept.len())),
        );
        assert_warmed_resume_batch_case(
            &span_plan,
            &span_frontier,
            window_end,
            SearchWindow::full(window_end),
            first_unfilled,
            SearchWindow::full(first_unfilled),
            None,
            OutputContract::Span,
            ResumeBatchExit::FirstUnfilled,
            None,
        );
        assert_warmed_resume_batch_case(
            &endpoint_plan,
            &endpoint_frontier,
            first_unfilled,
            SearchWindow::full(first_unfilled),
            first_unfilled,
            SearchWindow::full(first_unfilled),
            Some(0),
            OutputContract::SelectedEnd,
            ResumeBatchExit::Dead,
            Some(MatchSpan::new(0, 0)),
        );
        let exact_work = assert_warmed_resume_batch_case(
            &span_plan,
            &span_frontier,
            accept,
            SearchWindow::full(accept),
            accept,
            SearchWindow::full(accept),
            None,
            OutputContract::Span,
            ResumeBatchExit::Accept,
            Some(MatchSpan::new(0, accept.len())),
        );
        let (mut exact_workspace, mut exact_resume) = warm_resume_batch_fixture(
            &span_plan,
            &span_frontier,
            accept,
            SearchWindow::full(accept),
            None,
            OutputContract::Span,
        );
        let exact = super::search_from_resume_with_workspace(
            &span_plan,
            accept,
            SearchWindow::full(accept),
            &mut exact_workspace,
            &mut exact_resume,
            0,
            0,
            None,
            SearchLimits {
                max_work: exact_work,
                max_scratch_bytes: usize::MAX,
            },
            OutputContract::Span,
        )
        .unwrap();
        assert_eq!(exact.found, Some(MatchSpan::new(0, accept.len())));
        assert_eq!(exact.accounting.work(), exact_work);

        let (mut refused_workspace, mut refused_resume) = warm_resume_batch_fixture(
            &span_plan,
            &span_frontier,
            accept,
            SearchWindow::full(accept),
            None,
            OutputContract::Span,
        );
        assert!(matches!(
            super::search_from_resume_with_workspace(
                &span_plan,
                accept,
                SearchWindow::full(accept),
                &mut refused_workspace,
                &mut refused_resume,
                0,
                0,
                None,
                SearchLimits {
                    max_work: exact_work - 1,
                    max_scratch_bytes: usize::MAX,
                },
                OutputContract::Span,
            ),
            Err(SearchError::WorkLimitExceeded { limit, .. }) if limit == exact_work - 1
        ));
    }

    #[allow(
        clippy::too_many_arguments,
        reason = "the direct differential names every authenticated continuation boundary"
    )]
    fn run_warmed_resume_loop<const BATCH_WARM: bool>(
        plan: &Automaton,
        haystack: &[u8],
        window: SearchWindow,
        workspace: &mut K0Workspace,
        resume: &K0ResumeSet,
        pending_end: Option<usize>,
        contract: OutputContract,
    ) -> ((Option<MatchSpan>, usize), u64) {
        let state = super::LazyState::Cached(
            workspace.lazy.row_offset(resume.cached_states[0]).unwrap(),
        );
        let mut meter = WorkMeter::new(u64::MAX, 0);
        let result = super::execute_lazy_resume_loop::<BATCH_WARM>(
            plan,
            haystack,
            window,
            workspace,
            &mut meter,
            contract,
            0,
            state,
            window.start(),
            pending_end,
        )
        .unwrap();
        (result, meter.consumed)
    }

    #[test]
    fn warmed_resume_batch_randomized_differential_is_exact() {
        let plan = greedy_a_star_b();
        let frontier = [1_u32, 2_u32];
        let mut random = 0x9e37_79b9_7f4a_7c15_u64;
        for case in 0..48 {
            random = random
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            let prefix_len = 5 + usize::try_from(random % 12).unwrap();
            let start = usize::try_from((random >> 8) % 4).unwrap();
            let suffix = match (random >> 16) % 3 {
                0 => None,
                1 => Some(b'b'),
                _ => Some(b'x'),
            };
            let contract = match (random >> 24) % 3 {
                0 => OutputContract::Exists,
                1 => OutputContract::SelectedEnd,
                _ => OutputContract::Span,
            };
            let pending = contract != OutputContract::Exists && (random >> 32) & 1 != 0;
            let pending_end = pending.then_some(start);
            let mut haystack = vec![b'q'; start];
            haystack.extend(core::iter::repeat_n(b'a', prefix_len));
            haystack.extend(suffix);
            let end = haystack.len();
            haystack.push(b'!');
            let window = SearchWindow::new(start, end);

            let warm_contract = if contract == OutputContract::Span {
                OutputContract::SelectedEnd
            } else {
                contract
            };
            let (mut batched_workspace, batched_resume) = warm_resume_batch_fixture(
                &plan,
                &frontier,
                &haystack,
                window,
                pending_end,
                warm_contract,
            );
            let (mut scalar_workspace, scalar_resume) = warm_resume_batch_fixture(
                &plan,
                &frontier,
                &haystack,
                window,
                pending_end,
                warm_contract,
            );
            assert_resume_cache_equivalent(&batched_workspace, &scalar_workspace);
            assert_eq!(batched_resume.cached_states, scalar_resume.cached_states);
            let batched = run_warmed_resume_loop::<true>(
                &plan,
                &haystack,
                window,
                &mut batched_workspace,
                &batched_resume,
                pending_end,
                contract,
            );
            let scalar = run_warmed_resume_loop::<false>(
                &plan,
                &haystack,
                window,
                &mut scalar_workspace,
                &scalar_resume,
                pending_end,
                contract,
            );
            assert_eq!(batched, scalar, "randomized resume case {case}");
            if contract != OutputContract::Span {
                let expected_end = batched.0.0.map(MatchSpan::end);
                assert_eq!(
                    super::try_warm_ordered_resume_endpoint(
                        &plan,
                        &haystack,
                        window,
                        &batched_workspace,
                        &batched_resume,
                        0,
                        window.start(),
                        pending_end,
                        contract == OutputContract::Exists,
                    )
                    .unwrap(),
                    super::WarmResumeEndpoint::Complete(expected_end),
                    "randomized report-free resume case {case}"
                );
            }
            assert_resume_cache_equivalent(&batched_workspace, &scalar_workspace);
        }
    }

    #[test]
    #[allow(clippy::too_many_lines)]
    fn warmed_resume_value_paths_are_read_only_and_handoff_at_first_unfilled() {
        let plan = greedy_a_star_b();
        let frontier = [1_u32, 2_u32];
        let accepted = b"aaaaaab";
        let accepted_window = SearchWindow::full(accepted);

        let (mut selected_workspace, mut selected_resume) = warm_resume_batch_fixture(
            &plan,
            &frontier,
            accepted,
            accepted_window,
            None,
            OutputContract::SelectedEnd,
        );
        let (selected_reference, selected_reference_resume) = warm_resume_batch_fixture(
            &plan,
            &frontier,
            accepted,
            accepted_window,
            None,
            OutputContract::SelectedEnd,
        );
        assert_eq!(
            super::try_warm_ordered_resume_endpoint(
                &plan,
                accepted,
                accepted_window,
                &selected_workspace,
                &selected_resume,
                0,
                0,
                None,
                false,
            )
            .unwrap(),
            super::WarmResumeEndpoint::Complete(Some(accepted.len()))
        );
        assert_eq!(
            plan.prepare::<SelectedEnd>()
                .search_prevalidated_selected_end_value_from_ordered_resume_with_authenticated_workspace(
                    accepted,
                    accepted_window,
                    &mut selected_workspace,
                    &mut selected_resume,
                    0,
                    0,
                    None,
                    SearchLimits::unlimited(),
                )
                .unwrap(),
            Some(accepted.len())
        );
        assert_resume_cache_equivalent(&selected_workspace, &selected_reference);
        assert_eq!(
            selected_resume.cached_states,
            selected_reference_resume.cached_states
        );

        let (mut exists_workspace, mut exists_resume) = warm_resume_batch_fixture(
            &plan,
            &frontier,
            accepted,
            accepted_window,
            None,
            OutputContract::Exists,
        );
        assert!(
            plan.prepare::<Exists>()
                .search_prevalidated_exists_value_from_ordered_resume_with_authenticated_workspace(
                    accepted,
                    accepted_window,
                    &mut exists_workspace,
                    &mut exists_resume,
                    0,
                    0,
                    None,
                    SearchLimits::unlimited(),
                )
                .unwrap()
        );

        let (mut span_workspace, mut span_resume) = warm_resume_batch_fixture(
            &plan,
            &frontier,
            accepted,
            accepted_window,
            None,
            OutputContract::Span,
        );
        let reverse_rows = span_workspace.reverse.rows.clone();
        let reverse_offsets = span_workspace.reverse.offsets.clone();
        let reverse_lengths = span_workspace.reverse.lengths.clone();
        let reverse_hashes = span_workspace.reverse.hashes.clone();
        let reverse_items = span_workspace.reverse.items.clone();
        let reverse_shape = (
            span_workspace.reverse.state_len,
            span_workspace.reverse.item_len,
            span_workspace.reverse.initial,
            span_workspace.reverse.initialized,
            span_workspace.reverse.declined,
            span_workspace.reverse.saturated,
        );
        assert_eq!(
            plan.prepare::<Span>()
                .search_prevalidated_span_value_from_ordered_resume_with_authenticated_workspace(
                    accepted,
                    accepted_window,
                    &mut span_workspace,
                    &mut span_resume,
                    0,
                    0,
                    None,
                    SearchLimits::unlimited(),
                )
                .unwrap(),
            Some(MatchSpan::new(0, accepted.len()))
        );
        assert_eq!(span_workspace.reverse.rows, reverse_rows);
        assert_eq!(span_workspace.reverse.offsets, reverse_offsets);
        assert_eq!(span_workspace.reverse.lengths, reverse_lengths);
        assert_eq!(span_workspace.reverse.hashes, reverse_hashes);
        assert_eq!(span_workspace.reverse.items, reverse_items);
        assert_eq!(
            (
                span_workspace.reverse.state_len,
                span_workspace.reverse.item_len,
                span_workspace.reverse.initial,
                span_workspace.reverse.initialized,
                span_workspace.reverse.declined,
                span_workspace.reverse.saturated,
            ),
            reverse_shape
        );

        let warmed = b"aaaaaa";
        let unfilled = b"aaaaaax";
        let (mut decline_workspace, mut decline_resume) = warm_resume_batch_fixture(
            &plan,
            &frontier,
            warmed,
            SearchWindow::full(warmed),
            None,
            OutputContract::SelectedEnd,
        );
        let continuation = match super::try_warm_ordered_resume_endpoint(
            &plan,
            unfilled,
            SearchWindow::full(unfilled),
            &decline_workspace,
            &decline_resume,
            0,
            0,
            None,
            false,
        )
        .unwrap()
        {
            super::WarmResumeEndpoint::Continue(continuation) => continuation,
            outcome => {
                panic!("novel suffix did not hand off at its first unfilled cell: {outcome:?}")
            }
        };
        assert_eq!(continuation.position, warmed.len());
        assert_eq!(continuation.pending_end, None);
        assert_eq!(
            decline_workspace
                .lazy
                .direct_cell(continuation.row, byte_class(&plan, b'x'))
                .unwrap(),
            super::LAZY_CELL_UNFILLED
        );
        assert_eq!(
            plan.prepare::<SelectedEnd>()
                .search_prevalidated_selected_end_value_from_ordered_resume_with_authenticated_workspace(
                    unfilled,
                    SearchWindow::full(unfilled),
                    &mut decline_workspace,
                    &mut decline_resume,
                    0,
                    0,
                    None,
                    SearchLimits::unlimited(),
                )
                .unwrap(),
            None
        );
        assert_ne!(
            decline_workspace
                .lazy
                .direct_cell(continuation.row, byte_class(&plan, b'x'))
                .unwrap(),
            super::LAZY_CELL_UNFILLED,
            "the mutable fallback did not continue at the handed-off cell"
        );

        // Exercise the continuation itself with an earlier filled edge
        // deliberately removed after the immutable probe. Exact handoff must
        // neither read nor republish that consumed-prefix edge.
        let (mut no_replay_workspace, no_replay_resume) = warm_resume_batch_fixture(
            &plan,
            &frontier,
            warmed,
            SearchWindow::full(warmed),
            None,
            OutputContract::SelectedEnd,
        );
        let no_replay = match super::try_warm_ordered_resume_endpoint(
            &plan,
            unfilled,
            SearchWindow::full(unfilled),
            &no_replay_workspace,
            &no_replay_resume,
            0,
            0,
            None,
            false,
        )
        .unwrap()
        {
            super::WarmResumeEndpoint::Continue(continuation) => continuation,
            outcome => panic!("no-replay fixture did not return a continuation: {outcome:?}"),
        };
        let seed_row = no_replay_workspace
            .lazy
            .row_offset(no_replay_resume.cached_states[0])
            .unwrap();
        let consumed_prefix_cell = usize::try_from(seed_row)
            .unwrap()
            .checked_add(usize::from(byte_class(&plan, b'a')))
            .unwrap();
        assert_ne!(
            no_replay_workspace.lazy.rows[consumed_prefix_cell],
            super::LAZY_CELL_UNFILLED
        );
        no_replay_workspace.lazy.rows[consumed_prefix_cell] = super::LAZY_CELL_UNFILLED;
        assert_eq!(
            super::continue_warm_ordered_resume_forward(
                &plan,
                unfilled,
                SearchWindow::full(unfilled),
                &mut no_replay_workspace,
                &no_replay_resume,
                no_replay,
                OutputContract::SelectedEnd,
            )
            .unwrap(),
            None
        );
        assert_eq!(
            no_replay_workspace.lazy.rows[consumed_prefix_cell],
            super::LAZY_CELL_UNFILLED,
            "forward continuation replayed a consumed prefix edge"
        );

        assert!(matches!(
            plan.prepare::<SelectedEnd>()
                .search_prevalidated_selected_end_value_from_ordered_resume_with_authenticated_workspace(
                    accepted,
                    accepted_window,
                    &mut selected_workspace,
                    &mut selected_resume,
                    0,
                    0,
                    None,
                    SearchLimits {
                        max_work: 0,
                        max_scratch_bytes: usize::MAX,
                    },
                ),
            Err(SearchError::WorkLimitExceeded { limit: 0, .. })
        ));
    }

    #[test]
    #[allow(clippy::too_many_lines)]
    fn warmed_resume_span_hands_off_reverse_at_first_unfilled_without_forward_replay() {
        // Both alternatives reach the same authenticated suffix frontier.
        // Warming `ac` publishes the complete forward `c` row and reverse
        // `c,a` path. The novel `bc` call therefore completes forward through
        // filled rows, then meets its first unpublished cell only in reverse.
        let plan = byte_class_then_range(b"ab", (b'c', b'c'), None);
        let frontier = [1_u32];
        let warmed = b"ac";
        let novel = b"bc";
        let window = SearchWindow::full(warmed);
        let (mut workspace, mut resume) = warm_resume_at_fixture(
            &plan,
            &frontier,
            warmed,
            window,
            1,
            None,
            OutputContract::Span,
        );

        let continuation = match super::try_warm_ordered_resume_span(
            &plan,
            novel,
            window,
            &workspace,
            &resume,
            0,
            1,
            None,
        )
        .unwrap()
        {
            super::WarmResumeSpan::ContinueReverse(continuation) => continuation,
            outcome => panic!("novel reverse class did not hand off exactly: {outcome:?}"),
        };
        assert_eq!(continuation.selected_end, novel.len());
        assert_eq!(continuation.cursor, 1);
        assert_eq!(continuation.candidate, None);
        assert_eq!(
            workspace
                .reverse
                .direct_cell(continuation.row, byte_class(&plan, b'b'))
                .unwrap(),
            super::LAZY_CELL_UNFILLED
        );

        assert_eq!(
            plan.prepare::<Span>()
                .search_prevalidated_span_value_from_ordered_resume_with_authenticated_workspace(
                    novel,
                    window,
                    &mut workspace,
                    &mut resume,
                    0,
                    1,
                    None,
                    SearchLimits::unlimited(),
                )
                .unwrap(),
            Some(MatchSpan::new(0, novel.len()))
        );
        assert_ne!(
            workspace
                .reverse
                .direct_cell(continuation.row, byte_class(&plan, b'b'))
                .unwrap(),
            super::LAZY_CELL_UNFILLED,
            "reverse fallback did not publish the exact handed-off cell"
        );

        // The newly published path is now a completely immutable warm Span.
        let rows = workspace.reverse.rows.clone();
        assert_eq!(
            super::try_warm_ordered_resume_span(
                &plan,
                novel,
                window,
                &workspace,
                &resume,
                0,
                1,
                None,
            )
            .unwrap(),
            super::WarmResumeSpan::Complete(Some(MatchSpan::new(0, novel.len())))
        );
        assert_eq!(workspace.reverse.rows, rows);

        // Poison the already-traversed reverse `c` edge after obtaining a
        // continuation. Reverse recovery must begin at the retained `b` row
        // and leave that completed suffix edge untouched.
        let (mut no_replay_workspace, no_replay_resume) = warm_resume_at_fixture(
            &plan,
            &frontier,
            warmed,
            window,
            1,
            None,
            OutputContract::Span,
        );
        let no_replay = match super::try_warm_ordered_resume_span(
            &plan,
            novel,
            window,
            &no_replay_workspace,
            &no_replay_resume,
            0,
            1,
            None,
        )
        .unwrap()
        {
            super::WarmResumeSpan::ContinueReverse(continuation) => continuation,
            outcome => panic!("no-replay reverse fixture did not continue: {outcome:?}"),
        };
        let reverse_initial_row = no_replay_workspace
            .reverse
            .row_offset(no_replay_workspace.reverse.initial)
            .unwrap();
        let consumed_suffix_cell = usize::try_from(reverse_initial_row)
            .unwrap()
            .checked_add(usize::from(byte_class(&plan, b'c')))
            .unwrap();
        assert_ne!(
            no_replay_workspace.reverse.rows[consumed_suffix_cell],
            super::LAZY_CELL_UNFILLED
        );
        no_replay_workspace.reverse.rows[consumed_suffix_cell] = super::LAZY_CELL_UNFILLED;
        assert_eq!(
            super::continue_warm_ordered_resume_reverse(
                &plan,
                novel,
                window,
                &mut no_replay_workspace,
                &no_replay_resume,
                no_replay.selected_end,
                no_replay.work,
                Some(no_replay),
            )
            .unwrap(),
            Some(MatchSpan::new(0, novel.len()))
        );
        assert_eq!(
            no_replay_workspace.reverse.rows[consumed_suffix_cell],
            super::LAZY_CELL_UNFILLED,
            "reverse continuation replayed a consumed suffix edge"
        );
    }

    #[test]
    #[allow(clippy::too_many_lines)]
    fn ordered_resume_value_paths_cold_publish_then_complete_warm_for_every_contract() {
        let plan = byte_chain(&[(b'a', b'a'), (b'b', b'b')]);
        let frontier = [1_u32];
        let haystack = b"xxab!";
        let window = SearchWindow::new(2, 4);
        let resume_position = 3;

        for contract in [
            OutputContract::Exists,
            OutputContract::SelectedEnd,
            OutputContract::Span,
        ] {
            let mut value_resume =
                K0ResumeSet::new(&plan, 1, 1, [(&frontier[..], false)]).unwrap();
            let mut value_workspace =
                K0Workspace::new_bidirectional(&plan, WorkspaceLimits::unlimited()).unwrap();
            let mut report_resume =
                K0ResumeSet::new(&plan, 1, 1, [(&frontier[..], false)]).unwrap();
            let mut report_workspace =
                K0Workspace::new_bidirectional(&plan, WorkspaceLimits::unlimited()).unwrap();

            let expected = super::search_from_resume_with_workspace(
                &plan,
                haystack,
                window,
                &mut report_workspace,
                &mut report_resume,
                0,
                resume_position,
                None,
                SearchLimits::unlimited(),
                contract,
            )
            .map(|report| report.found);
            match contract {
                OutputContract::Exists => assert_eq!(
                    plan.prepare::<Exists>()
                        .search_prevalidated_exists_value_from_ordered_resume_with_authenticated_workspace(
                            haystack,
                            window,
                            &mut value_workspace,
                            &mut value_resume,
                            0,
                            resume_position,
                            None,
                            SearchLimits::unlimited(),
                        ),
                    expected.map(|found| found.is_some()),
                    "cold {contract:?}"
                ),
                OutputContract::SelectedEnd => assert_eq!(
                    plan.prepare::<SelectedEnd>()
                        .search_prevalidated_selected_end_value_from_ordered_resume_with_authenticated_workspace(
                            haystack,
                            window,
                            &mut value_workspace,
                            &mut value_resume,
                            0,
                            resume_position,
                            None,
                            SearchLimits::unlimited(),
                        ),
                    expected.map(|found| found.map(MatchSpan::end)),
                    "cold {contract:?}"
                ),
                OutputContract::Span => assert_eq!(
                    plan.prepare::<Span>()
                        .search_prevalidated_span_value_from_ordered_resume_with_authenticated_workspace(
                            haystack,
                            window,
                            &mut value_workspace,
                            &mut value_resume,
                            0,
                            resume_position,
                            None,
                            SearchLimits::unlimited(),
                        ),
                    expected,
                    "cold {contract:?}"
                ),
                _ => unreachable!("test contract is capture-free"),
            }
            assert_ne!(value_resume.cached_states[0], super::LAZY_NO_STATE);

            match contract {
                OutputContract::Exists => assert!(matches!(
                    super::try_warm_ordered_resume_endpoint(
                        &plan,
                        haystack,
                        window,
                        &value_workspace,
                        &value_resume,
                        0,
                        resume_position,
                        None,
                        true,
                    )
                    .unwrap(),
                    super::WarmResumeEndpoint::Complete(Some(_))
                )),
                OutputContract::SelectedEnd => assert_eq!(
                    super::try_warm_ordered_resume_endpoint(
                        &plan,
                        haystack,
                        window,
                        &value_workspace,
                        &value_resume,
                        0,
                        resume_position,
                        None,
                        false,
                    )
                    .unwrap(),
                    super::WarmResumeEndpoint::Complete(Some(window.end()))
                ),
                OutputContract::Span => assert_eq!(
                    super::try_warm_ordered_resume_span(
                        &plan,
                        haystack,
                        window,
                        &value_workspace,
                        &value_resume,
                        0,
                        resume_position,
                        None,
                    )
                    .unwrap(),
                    super::WarmResumeSpan::Complete(Some(MatchSpan::new(
                        window.start(),
                        window.end(),
                    )))
                ),
                _ => unreachable!("test contract is capture-free"),
            }
        }
    }

    #[test]
    #[allow(clippy::too_many_lines)]
    fn ordered_resume_value_paths_preserve_every_finite_limit_boundary() {
        #[derive(Clone, Copy, Debug, Eq, PartialEq)]
        enum Value {
            Exists(bool),
            SelectedEnd(Option<usize>),
            Span(Option<MatchSpan>),
        }

        let plan = byte_chain(&[(b'a', b'a'), (b'b', b'b')]);
        let frontier = [1_u32];
        let haystack = b"xxab!";
        let window = SearchWindow::new(2, 4);
        let resume_position = 3;

        for contract in [
            OutputContract::Exists,
            OutputContract::SelectedEnd,
            OutputContract::Span,
        ] {
            macro_rules! call_value {
                ($workspace:expr, $resume:expr, $limits:expr) => {
                    match contract {
                        OutputContract::Exists => plan
                            .prepare::<Exists>()
                            .search_prevalidated_exists_value_from_ordered_resume_with_authenticated_workspace(
                                haystack,
                                window,
                                $workspace,
                                $resume,
                                0,
                                resume_position,
                                None,
                                $limits,
                            )
                            .map(Value::Exists),
                        OutputContract::SelectedEnd => plan
                            .prepare::<SelectedEnd>()
                            .search_prevalidated_selected_end_value_from_ordered_resume_with_authenticated_workspace(
                                haystack,
                                window,
                                $workspace,
                                $resume,
                                0,
                                resume_position,
                                None,
                                $limits,
                            )
                            .map(Value::SelectedEnd),
                        OutputContract::Span => plan
                            .prepare::<Span>()
                            .search_prevalidated_span_value_from_ordered_resume_with_authenticated_workspace(
                                haystack,
                                window,
                                $workspace,
                                $resume,
                                0,
                                resume_position,
                                None,
                                $limits,
                            )
                            .map(Value::Span),
                        _ => unreachable!("test contract is capture-free"),
                    }
                };
            }

            let (mut report_workspace, mut report_resume) = warm_resume_at_fixture(
                &plan,
                &frontier,
                haystack,
                window,
                resume_position,
                None,
                contract,
            );
            let scratch = report_workspace
                .retained_bytes()
                .checked_add(report_resume.retained_bytes())
                .unwrap();
            let report = super::search_from_resume_with_workspace(
                &plan,
                haystack,
                window,
                &mut report_workspace,
                &mut report_resume,
                0,
                resume_position,
                None,
                SearchLimits::unlimited(),
                contract,
            )
            .unwrap();
            let exact_work = report.accounting.work();
            let expected = match contract {
                OutputContract::Exists => Value::Exists(report.found.is_some()),
                OutputContract::SelectedEnd => {
                    Value::SelectedEnd(report.found.map(MatchSpan::end))
                }
                OutputContract::Span => Value::Span(report.found),
                _ => unreachable!("test contract is capture-free"),
            };
            assert!(exact_work > 0);

            let (mut exact_workspace, mut exact_resume) = warm_resume_at_fixture(
                &plan,
                &frontier,
                haystack,
                window,
                resume_position,
                None,
                contract,
            );
            assert_eq!(
                call_value!(
                    &mut exact_workspace,
                    &mut exact_resume,
                    SearchLimits {
                        max_work: exact_work,
                        max_scratch_bytes: scratch,
                    }
                )
                .unwrap(),
                expected,
                "exact finite {contract:?}"
            );

            let (mut work_workspace, mut work_resume) = warm_resume_at_fixture(
                &plan,
                &frontier,
                haystack,
                window,
                resume_position,
                None,
                contract,
            );
            assert!(matches!(
                call_value!(
                    &mut work_workspace,
                    &mut work_resume,
                    SearchLimits {
                        max_work: exact_work - 1,
                        max_scratch_bytes: scratch,
                    }
                ),
                Err(SearchError::WorkLimitExceeded { limit, .. }) if limit == exact_work - 1
            ));

            let (mut scratch_workspace, mut scratch_resume) = warm_resume_at_fixture(
                &plan,
                &frontier,
                haystack,
                window,
                resume_position,
                None,
                contract,
            );
            assert!(matches!(
                call_value!(
                    &mut scratch_workspace,
                    &mut scratch_resume,
                    SearchLimits {
                        max_work: u64::MAX,
                        max_scratch_bytes: scratch - 1,
                    }
                ),
                Err(SearchError::ResourceLimit {
                    resource: ResourceKind::ScratchBytes,
                    needed,
                    limit,
                }) if needed == scratch && limit == scratch - 1
            ));
        }
    }

    #[test]
    #[allow(clippy::too_many_lines)]
    fn ordered_resume_values_exhaustively_match_reports_on_small_novel_inputs() {
        let plan = greedy_a_star_b();
        let frontier = [1_u32, 2_u32];
        let alphabet = [b'a', b'b', b'x'];
        let mut warm_source = vec![b'!', b'!'];
        warm_source.extend_from_slice(b"aaaaab");
        warm_source.push(b'!');
        let warm_window = SearchWindow::new(2, warm_source.len() - 1);
        let mut checked = 0usize;
        let mut completed = 0usize;
        let mut forward_handoffs = 0usize;

        for contract in [
            OutputContract::Exists,
            OutputContract::SelectedEnd,
            OutputContract::Span,
        ] {
            for has_pending in [false, true] {
                let warm_pending = has_pending.then_some(warm_window.start());
                for length in 0_u32..=4 {
                    let cases = alphabet.len().pow(length);
                    for mut encoded in 0..cases {
                        let mut source = vec![b'!', b'!'];
                        for _ in 0..length {
                            source.push(alphabet[encoded % alphabet.len()]);
                            encoded /= alphabet.len();
                        }
                        let window = SearchWindow::new(2, source.len());
                        source.push(b'!');
                        let pending_end = has_pending.then_some(window.start());
                        let (mut value_workspace, mut value_resume) = warm_resume_at_fixture(
                            &plan,
                            &frontier,
                            &warm_source,
                            warm_window,
                            warm_window.start(),
                            warm_pending,
                            contract,
                        );
                        let (mut report_workspace, mut report_resume) = warm_resume_at_fixture(
                            &plan,
                            &frontier,
                            &warm_source,
                            warm_window,
                            warm_window.start(),
                            warm_pending,
                            contract,
                        );

                        match contract {
                            OutputContract::Exists => match super::try_warm_ordered_resume_endpoint(
                                &plan,
                                &source,
                                window,
                                &value_workspace,
                                &value_resume,
                                0,
                                window.start(),
                                pending_end,
                                true,
                            )
                            .unwrap()
                            {
                                super::WarmResumeEndpoint::Complete(_) => completed += 1,
                                super::WarmResumeEndpoint::Continue(_) => forward_handoffs += 1,
                                super::WarmResumeEndpoint::Declined => {}
                            },
                            OutputContract::SelectedEnd => {
                                match super::try_warm_ordered_resume_endpoint(
                                    &plan,
                                    &source,
                                    window,
                                    &value_workspace,
                                    &value_resume,
                                    0,
                                    window.start(),
                                    pending_end,
                                    false,
                                )
                                .unwrap()
                                {
                                    super::WarmResumeEndpoint::Complete(_) => completed += 1,
                                    super::WarmResumeEndpoint::Continue(_) => {
                                        forward_handoffs += 1;
                                    }
                                    super::WarmResumeEndpoint::Declined => {}
                                }
                            }
                            OutputContract::Span => match super::try_warm_ordered_resume_span(
                                &plan,
                                &source,
                                window,
                                &value_workspace,
                                &value_resume,
                                0,
                                window.start(),
                                pending_end,
                            )
                            .unwrap()
                            {
                                super::WarmResumeSpan::Complete(_) => completed += 1,
                                super::WarmResumeSpan::ContinueForward(_) => {
                                    forward_handoffs += 1;
                                }
                                super::WarmResumeSpan::RecoverReverse { .. }
                                | super::WarmResumeSpan::ContinueReverse(_)
                                | super::WarmResumeSpan::Declined => {}
                            },
                            _ => unreachable!("test contract is capture-free"),
                        }

                        let expected = super::search_from_resume_with_workspace(
                            &plan,
                            &source,
                            window,
                            &mut report_workspace,
                            &mut report_resume,
                            0,
                            window.start(),
                            pending_end,
                            SearchLimits::unlimited(),
                            contract,
                        )
                        .map(|report| report.found);
                        match contract {
                            OutputContract::Exists => assert_eq!(
                                plan.prepare::<Exists>()
                                    .search_prevalidated_exists_value_from_ordered_resume_with_authenticated_workspace(
                                        &source,
                                        window,
                                        &mut value_workspace,
                                        &mut value_resume,
                                        0,
                                        window.start(),
                                        pending_end,
                                        SearchLimits::unlimited(),
                                    ),
                                expected.map(|found| found.is_some()),
                                "Exists word {encoded} length {length} pending {has_pending}"
                            ),
                            OutputContract::SelectedEnd => assert_eq!(
                                plan.prepare::<SelectedEnd>()
                                    .search_prevalidated_selected_end_value_from_ordered_resume_with_authenticated_workspace(
                                        &source,
                                        window,
                                        &mut value_workspace,
                                        &mut value_resume,
                                        0,
                                        window.start(),
                                        pending_end,
                                        SearchLimits::unlimited(),
                                    ),
                                expected.map(|found| found.map(MatchSpan::end)),
                                "SelectedEnd word {encoded} length {length} pending {has_pending}"
                            ),
                            OutputContract::Span => assert_eq!(
                                plan.prepare::<Span>()
                                    .search_prevalidated_span_value_from_ordered_resume_with_authenticated_workspace(
                                        &source,
                                        window,
                                        &mut value_workspace,
                                        &mut value_resume,
                                        0,
                                        window.start(),
                                        pending_end,
                                        SearchLimits::unlimited(),
                                    ),
                                expected,
                                "Span word {encoded} length {length} pending {has_pending}"
                            ),
                            _ => unreachable!("test contract is capture-free"),
                        }
                        checked += 1;
                    }
                }
            }
        }

        assert_eq!(checked, 3 * 2 * (1 + 3 + 9 + 27 + 81));
        assert!(completed > 0, "no small input completed from immutable rows");
        assert!(
            forward_handoffs > 0,
            "no novel small input reached a first-unfilled forward handoff"
        );
    }

    #[test]
    #[allow(clippy::too_many_lines)]
    fn warmed_resume_value_paths_zero_identity_reauthenticates_stale_and_out_of_range_hints() {
        let plan = byte_chain(&[(b'a', b'a'), (b'b', b'b')]);
        let frontier = [1_u32];
        let haystack = b"xxab!";
        let window = SearchWindow::new(2, 4);
        let resume_position = 3;

        let (mut stale_workspace, mut stale_resume) = warm_resume_at_fixture(
            &plan,
            &frontier,
            haystack,
            window,
            resume_position,
            None,
            OutputContract::SelectedEnd,
        );
        let stale_hint = stale_workspace.lazy.initial;
        assert_ne!(stale_hint, super::LAZY_NO_STATE);
        let (offset, length, pending) =
            super::resume_lazy_state_bounds(&stale_workspace.lazy, stale_hint).unwrap();
        let end = offset.checked_add(length).unwrap();
        assert!(
            pending
                || stale_workspace.lazy.items.get(offset..end) != Some(frontier.as_slice())
        );
        // Exhausted workspace identity zero cannot authenticate a numeric ID,
        // so both the immutable warm probe and ordinary seed path must compare
        // the retained state contents before using this deliberately stale
        // in-bounds hint.
        stale_workspace.lazy.cache_identity = 0;
        stale_resume.cached_workspace_identities[0] = 0;
        stale_resume.cached_states[0] = stale_hint;
        assert_eq!(
            super::try_warm_ordered_resume_endpoint(
                &plan,
                haystack,
                window,
                &stale_workspace,
                &stale_resume,
                0,
                resume_position,
                None,
                false,
            )
            .unwrap(),
            super::WarmResumeEndpoint::Declined
        );
        assert_eq!(stale_resume.cached_states[0], stale_hint);
        assert_eq!(
            plan.prepare::<SelectedEnd>()
                .search_prevalidated_selected_end_value_from_ordered_resume_with_authenticated_workspace(
                    haystack,
                    window,
                    &mut stale_workspace,
                    &mut stale_resume,
                    0,
                    resume_position,
                    None,
                    SearchLimits::unlimited(),
                )
                .unwrap(),
            Some(window.end())
        );
        let repaired = stale_resume.cached_states[0];
        assert_ne!(repaired, super::LAZY_NO_STATE);
        let (offset, length, pending) =
            super::resume_lazy_state_bounds(&stale_workspace.lazy, repaired).unwrap();
        let end = offset.checked_add(length).unwrap();
        assert!(!pending);
        assert_eq!(
            stale_workspace.lazy.items.get(offset..end),
            Some(frontier.as_slice())
        );

        let (mut outside_workspace, mut outside_resume) = warm_resume_at_fixture(
            &plan,
            &frontier,
            haystack,
            window,
            resume_position,
            None,
            OutputContract::SelectedEnd,
        );
        let outside = u32::try_from(outside_workspace.lazy.state_len).unwrap();
        assert_ne!(outside, super::LAZY_NO_STATE);
        outside_resume.cached_states[0] = outside;
        assert_eq!(
            super::try_warm_ordered_resume_endpoint(
                &plan,
                haystack,
                window,
                &outside_workspace,
                &outside_resume,
                0,
                resume_position,
                None,
                false,
            )
            .unwrap(),
            super::WarmResumeEndpoint::Declined
        );
        assert_eq!(outside_resume.cached_states[0], outside);
        assert_eq!(
            plan.prepare::<SelectedEnd>()
                .search_prevalidated_selected_end_value_from_ordered_resume_with_authenticated_workspace(
                    haystack,
                    window,
                    &mut outside_workspace,
                    &mut outside_resume,
                    0,
                    resume_position,
                    None,
                    SearchLimits::unlimited(),
                )
                .unwrap(),
            Some(window.end())
        );
        assert_ne!(outside_resume.cached_states[0], outside);
    }

